function isPlayerStandingOnBlock(block) {
  if (!block || !block.geometry || !block.geometry.parameters) return false;
  const { width = 1, height = 1, depth = 1 } = block.geometry.parameters;
  const scaleX = block.scale.x || 1;
  const scaleY = block.scale.y || 1;
  const scaleZ = block.scale.z || 1;
  const halfX = (width * scaleX) / 2;
  const halfZ = (depth * scaleZ) / 2;
  const actualHeight = height * scaleY;
  const bounds = {
    minX: block.position.x - halfX,
    maxX: block.position.x + halfX,
    minZ: block.position.z - halfZ,
    maxZ: block.position.z + halfZ,
    topY: block.position.y + actualHeight / 2
  };
  const playerFeet = playerCollider.start;
  return (
    playerFeet.x >= bounds.minX &&
    playerFeet.x <= bounds.maxX &&
    playerFeet.z >= bounds.minZ &&
    playerFeet.z <= bounds.maxZ &&
    playerFeet.y >= bounds.topY - 0.4 &&
    playerFeet.y <= bounds.topY + 0.5
  );
}

function checkLevel2TriggerBlockStanding() {
  if (!level2RiddleState.triggerBlock || level2RiddleState.step0Complete) {
    return false;
  }
  return isPlayerStandingOnBlock(level2RiddleState.triggerBlock);
}

