/**
 * Check if player can climb (Mouse character or Animation Library, near vertical wall)
 * @returns {Object|null} Climb info {canClimb: boolean, surfaceNormal: THREE.Vector3} or null
 */
function checkCanClimb() {
  // Check if player model is loaded and has climb support
  let canCharacterClimb = false;
  
  // Method 1: Check playerModelModule for Mouse character
  if (playerModelModule && 
      typeof playerModelModule.isLoaded === 'function' && 
      playerModelModule.isLoaded() && 
      typeof playerModelModule.isMouseCharacter === 'function') {
    if (playerModelModule.isMouseCharacter() === true) {
      canCharacterClimb = true; // Mouse character can always climb
    }
  }
  
  // Method 2: Animation Library can always climb (even without climb animations)
  // If climb animations exist, they will be used; otherwise movement animations are used
  if (!canCharacterClimb && playerModelModule && 
      typeof playerModelModule.isLoaded === 'function' && 
      playerModelModule.isLoaded() &&
      playerModelModule.characterType === 'animation_library') {
    canCharacterClimb = true; // Animation Library can always climb
    // Check if Animation Library has climb animations (for animation selection)
    const animations = playerModelModule.getAnimations();
    if (animations) {
      const hasClimbAnimation = Object.keys(animations).some(animName => {
        const nameLower = animName.toLowerCase();
        return nameLower.includes('climb') || nameLower.includes('climbing') || nameLower.includes('wall');
      });
      if (hasClimbAnimation) {
        console.log("🧗 [CLIMB] Animation Library character has climb animation - will use climb animation");
      } else {
        console.log("🧗 [CLIMB] Animation Library character can climb (will use movement animations)");
      }
    }
  }
  
  // Method 3: Fallback - Check characterType property directly (Mouse)
  if (!canCharacterClimb && playerModelModule && playerModelModule.characterType === 'mouse') {
    canCharacterClimb = true;
  }
  
  // Method 4: Fallback - Check model userData (Mouse)
  if (!canCharacterClimb && playerCharacterModel && playerCharacterModel.userData && playerCharacterModel.userData.isMouseCharacter) {
    canCharacterClimb = true;
  }
  
  // Method 5: Fallback - Check selectedCharacterPath for Mouse
  if (!canCharacterClimb && typeof selectedCharacterPath !== 'undefined' && selectedCharacterPath && selectedCharacterPath.toLowerCase().includes('mouse')) {
    canCharacterClimb = true;
  }
  
  if (!canCharacterClimb) {
    return { canClimb: false, objectName: null };
  }
  
  // Raycast forward from player to detect vertical walls
  const raycaster = new THREE.Raycaster();
  const forward = getForwardVector();
  const playerPos = new THREE.Vector3().lerpVectors(playerCollider.start, playerCollider.end, 0.5);
  
  // CRITICAL: Check in movement direction, not just camera forward
  // When player walks into wall, their velocity direction is what matters
  // 🚨 CRITICAL: Ensure check direction is HORIZONTAL (y=0) to prevent detecting ground
  const velocity = new THREE.Vector3(playerVelocity.x, 0, playerVelocity.z);
  const hasVelocity = velocity.lengthSq() > 0.1;
  let checkDirection = forward.clone();
  checkDirection.y = 0; // CRITICAL: Force horizontal direction (no downward checks)
  checkDirection.normalize();
  
  if (hasVelocity) {
    const velDir = velocity.clone().normalize();
    checkDirection = velDir; // Already horizontal (y=0 from above)
  } else {
    // If no velocity, check forward in movement input direction
    const movement = playerControls ? playerControls.getMovementState() : { forward: false, backward: false, left: false, right: false };
    if (movement.forward || movement.backward || movement.left || movement.right) {
      // Use forward vector but ensure it's horizontal
      checkDirection = forward.clone();
      checkDirection.y = 0; // CRITICAL: Force horizontal (no downward component)
      checkDirection.normalize();
    }
  }
  
  // Final safety check: Ensure checkDirection is horizontal (y must be 0)
  if (Math.abs(checkDirection.y) > 0.01) {
    console.warn("🧗 [CLIMB] ⚠️ Check direction has vertical component, forcing horizontal:", checkDirection.y);
    checkDirection.y = 0;
    checkDirection.normalize();
  }
  
  // Check multiple heights for climbable surface
  const checkHeights = [
    playerCollider.start.y + 0.2, // Lower body level
    playerCollider.start.y + 0.5, // Mid body level
    playerCollider.start.y + 0.8, // Upper body level
    playerCollider.start.y + 1.1  // Upper chest level
  ];
  
  let closestHit = null;
  let closestDistance = Infinity;
  
  // Check collision mesh first (towers are merged blocks in collision mesh)
  const objectsToCheck = [];
  const isLevel1 = currentLevel === LEVEL_IDS.LEVEL1;
  const isLevel2 = currentLevel === LEVEL_IDS.LEVEL2;
  
  // 🚨 CRITICAL PERFORMANCE FIX: Level 2 is a white room with no climbable surfaces - disable climbing entirely
  // Level 2 collision mesh has 2.9M vertices - checking it every frame causes massive FPS drops (4 FPS)
  // Level 2 uses simple math-based collision detection, not the collision mesh
  if (isLevel2) {
    return null; // Level 2 has no climbable surfaces - skip all climbing checks
  }
  
  // Only check collisionMesh for Level 1 (Level 2 disabled above)
  if (collisionMesh && collisionMesh.geometry && collisionMesh.geometry.boundsTree && isLevel1) {
    objectsToCheck.push({ obj: collisionMesh, name: 'collisionMesh' });
  }
  
  // ✅ STABLE VERSION - December 16, 2025: All 5 inner towers climbable, borders blocked correctly
  // DO NOT check scene objects for Level 1/2 - this prevents climbing on grass, trees, chests, monster statues, etc.
  // Level 2 has 40+ monster preview statues which were causing 144 object checks every frame (FPS killer!)
  
  // Only check scene objects if NOT Level 1 or Level 2 (other levels may have climbable scene objects)
  // CRITICAL: Level 2 has many monster statues - checking them all causes massive FPS drops
  if (!isLevel1 && !isLevel2) {
    // Also check scene for climbable objects (towers, walls, etc.)
    // Filter out non-climbable objects (player, camera, lights, etc.)
    // 🚨 CRITICAL: Exclude player model and all its children from climb detection
    scene.traverse((child) => {
    if (child.isMesh && child.visible && child !== playerCharacterModel && child !== collisionMesh) {
      // CRITICAL: Skip player model and all its child meshes (player model contains tripo_node meshes)
      // Check if this mesh is part of the player model by checking parent chain
      let isPlayerMesh = false;
      let parentCheck = child.parent;
      while (parentCheck) {
        if (parentCheck === playerCharacterModel) {
          isPlayerMesh = true;
          break;
        }
        parentCheck = parentCheck.parent;
      }
      // Also check by name pattern (player model meshes often have tripo_node in name)
      if (!isPlayerMesh && child.name) {
        const nameLower = child.name.toLowerCase();
        if (nameLower.includes('tripo_node') || nameLower.includes('player') || nameLower.includes('character')) {
          isPlayerMesh = true;
        }
      }
      if (isPlayerMesh) {
        return; // Skip player model meshes
      }
      
      // Skip grass, chests, trees, monster statues, and other non-climbable objects
      // CRITICAL: Filter out monster preview statues in Level 2 (major FPS improvement!)
      const nameLower = (child.name || '').toLowerCase();
      if (nameLower.includes('grass') || nameLower.includes('chest') || 
          nameLower.includes('tree') || nameLower.includes('sky') ||
          nameLower.includes('camera') || nameLower.includes('light') ||
          nameLower.includes('monster') || nameLower.includes('preview') || 
          nameLower.includes('statue') || nameLower.includes('blob') ||
          nameLower.includes('weapon') || nameLower.includes('accessory')) {
        return;
      }
      
      // Check if it's a potential climbable object (has geometry and reasonable size)
      if (child.geometry && child.material) {
        // Get bounding box to check if it's tall enough to climb
        const box = new THREE.Box3().setFromObject(child);
        const size = box.getSize(new THREE.Vector3());
        // Must be at least 0.5 units tall and 0.3 units wide (tower/wall dimensions)
        const isTallBlock = size.y > 0.5 && (size.x > 0.3 || size.z > 0.3);
        
        if (isTallBlock) {
          objectsToCheck.push({ obj: child, name: child.name || 'unnamed' });
        }
      }
    }
    });
  } else {
    // Level 1: Only collisionMesh is climbable (the 5 tower blocks: 4 corners + 1 center)
    // ✅ STABLE VERSION - December 16, 2025: All inner towers climbable, borders properly blocked
    // All scene objects (grass, trees, chests, etc.) are excluded from climbing
    // No scene traversal needed - only collisionMesh will be checked
  }
  
  for (const { obj, name } of objectsToCheck) {
    // 🚨 CRITICAL: Skip player model meshes completely
    // Double-check that we're not checking the player model itself
    if (obj === playerCharacterModel || obj.parent === playerCharacterModel) {
      continue; // Skip player model
    }
    // Also check by name to catch player model meshes that might not be direct children
    if (obj.name && (obj.name.toLowerCase().includes('tripo_node') || 
                     obj.name.toLowerCase().includes('player') || 
                     obj.name.toLowerCase().includes('character'))) {
      continue; // Skip player model meshes
    }
    
    for (const checkY of checkHeights) {
      // CRITICAL: Start ray from player position using check direction (velocity or forward)
      const rayStart = new THREE.Vector3(playerPos.x, checkY, playerPos.z);
      raycaster.set(rayStart, checkDirection);
      raycaster.far = 1.5; // Check up to 1.5 units ahead
      raycaster.near = 0.05; // 🚨 CRITICAL: Start 0.05 units away to avoid self-intersection with player model
      
      try {
        // For collision mesh, use false (no recursive) since it's a single merged geometry
        // The collision mesh is a BufferGeometry with all blocks merged
        const recursive = false;
        const hits = raycaster.intersectObject(obj, recursive);
        
        if (hits.length > 0) {
          const hit = hits[0];
          // Use raycaster's distance directly (already accounts for near offset)
          const hitDistance = hit.distance;
          
          // 🚨 CRITICAL: Skip hits that are too close (likely player model self-intersection)
          if (hitDistance < 0.1) {
            continue; // Too close, likely self-intersection
          }
          
          // Check if surface is vertical (wall) - normal should be mostly horizontal
          let normal;
          if (hit.face && hit.face.normal) {
            normal = hit.face.normal.clone();
            // Transform normal to world space if object has matrix
            if (hit.object && hit.object.matrixWorld) {
              normal.transformDirection(hit.object.matrixWorld);
              normal.normalize();
            }
          } else {
            // Fallback: default to up (not vertical)
            normal = new THREE.Vector3(0, 1, 0);
          }
          
          // Surface is vertical if normal.y is close to 0 (pointing horizontally)
          // Accept surfaces up to 45 degrees from vertical (normal.y < 0.707)
          const isVertical = Math.abs(normal.y) < 0.707;
          
          // CRITICAL: Disabled debug logging for performance (was causing FPS drops)
          // Only log when DEBUG_SETTINGS.logClimbChecks is true
          if (DEBUG_SETTINGS.logClimbChecks && hitDistance < 1.5 && Math.random() < 0.01) {
            console.log("🧗 [CLIMB] Hit detected:", {
              objectName: name,
              distance: hitDistance.toFixed(3),
              normalY: normal.y.toFixed(3),
              isVertical: isVertical,
              normal: { x: normal.x.toFixed(2), y: normal.y.toFixed(2), z: normal.z.toFixed(2) },
              point: { x: hit.point.x.toFixed(2), y: hit.point.y.toFixed(2), z: hit.point.z.toFixed(2) },
              rayStart: { x: rayStart.x.toFixed(2), y: rayStart.y.toFixed(2), z: rayStart.z.toFixed(2) },
              checkDirection: { x: checkDirection.x.toFixed(2), y: checkDirection.y.toFixed(2), z: checkDirection.z.toFixed(2) },
              hasVelocity: hasVelocity
            });
          }
          
          // 🚫 BORDER WALL CHECK: Prevent climbing on outer boundary walls (thick walls)
          // ✅ STABLE VERSION - December 16, 2025
          // Verified: All 5 inner towers (4 corners + 1 center) climbable, borders properly blocked
          // CRITICAL: Level 1 coordinates go from 0 to mapSize (0 to 120), NOT -halfSize to +halfSize
          // Border walls are THICK (multiple stepped layers) from the edges
          // Check if hit point is within the thick border wall zone on any of the 4 sides
          const thickWallZone = 12.0; // Thick wall zone (12 units from edge) - covers entire stepped border wall thickness
          // Safe climbing area: x: 12-108, z: 12-108 (96x96 units) - all inner towers are within this zone
          const minSafeX = thickWallZone; // Minimum safe X coordinate (left border is 0 to ~12)
          const maxSafeX = currentMapSize - thickWallZone; // Maximum safe X coordinate (right border is 108 to 120)
          const minSafeZ = thickWallZone; // Minimum safe Z coordinate (bottom border is 0 to ~12)
          const maxSafeZ = currentMapSize - thickWallZone; // Maximum safe Z coordinate (top border is 108 to 120)
          
          // Check if hit point is within border wall zone (outside safe play area)
          const isInBorderWallZone = 
            hit.point.x < minSafeX ||      // Too close to left border (x < 12)
            hit.point.x > maxSafeX ||      // Too close to right border (x > 108)
            hit.point.z < minSafeZ ||      // Too close to bottom border (z < 12)
            hit.point.z > maxSafeZ;        // Too close to top border (z > 108)
          
          // Reject climb attempts on border walls (outside safe play area)
          if (isInBorderWallZone) {
            // CRITICAL: Disabled debug logging for performance (was causing FPS drops)
            // Only log when DEBUG_SETTINGS.logClimbChecks is true
            if (DEBUG_SETTINGS.logClimbChecks && Math.random() < 0.01) {
              console.log("🧗 [CLIMB] ❌ Border wall detected - climbing disabled:", {
                point: { x: hit.point.x.toFixed(2), z: hit.point.z.toFixed(2) },
                mapSize: currentMapSize,
                thickWallZone: thickWallZone,
                safeArea: { 
                  x: `${minSafeX.toFixed(1)} to ${maxSafeX.toFixed(1)}`, 
                  z: `${minSafeZ.toFixed(1)} to ${maxSafeZ.toFixed(1)}` 
                },
                isInBorderWallZone: isInBorderWallZone,
                reason: hit.point.x < minSafeX ? 'left border' : 
                       hit.point.x > maxSafeX ? 'right border' :
                       hit.point.z < minSafeZ ? 'bottom border' : 'top border'
              });
            }
            continue; // Skip this hit - it's a border wall
          }
          
          // Accept any vertical surface within range (not at border)
          if (isVertical && hitDistance < closestDistance && hitDistance < 1.5 && hitDistance >= 0.1) {
            closestDistance = hitDistance;
            closestHit = {
              distance: hitDistance,
              point: hit.point,
              normal: normal,
              surfaceY: hit.point.y,
              objectName: name
            };
          }
        }
      } catch (e) {
        // Log errors for debugging
        if (Math.random() < 0.05) {
          console.error("🧗 [CLIMB] Error in raycast for object:", name, e);
        }
      }
    }
  }
  
  // Can climb if wall is close (within 1.5 units) and vertical
  // 🚨 CRITICAL: Also ensure minimum distance (0.1 units) to avoid player model self-intersection
  if (closestHit && closestHit.distance < 1.5 && closestHit.distance >= 0.1) {
    // CRITICAL: Disabled debug logging for performance (was causing FPS drops)
    // Only log when DEBUG_SETTINGS.logClimbChecks is true
    if (DEBUG_SETTINGS.logClimbChecks && Math.random() < 0.1) {
      console.log("🧗 [CLIMB] ✅ Can climb!", {
        objectName: closestHit.objectName,
        distance: closestHit.distance.toFixed(3),
        normal: {
          x: closestHit.normal.x.toFixed(2),
          y: closestHit.normal.y.toFixed(2),
          z: closestHit.normal.z.toFixed(2)
        },
        normalY: closestHit.normal.y.toFixed(3)
      });
    }
    
    return {
      canClimb: true,
      surfaceNormal: closestHit.normal,
      distance: closestHit.distance,
      point: closestHit.point,
      objectName: closestHit.objectName // Include object name to filter by level
    };
  }
  
  // CRITICAL: Disabled debug logging for performance (was causing FPS drops)
  // Only log when DEBUG_SETTINGS.logClimbChecks is true
  if (DEBUG_SETTINGS.logClimbChecks && Math.random() < 0.01) {
    console.log("🧗 [CLIMB] ❌ No climbable surface found:", {
      closestHit: closestHit ? { distance: closestHit.distance.toFixed(3), objectName: closestHit.objectName } : null,
      objectsChecked: objectsToCheck.length,
      isLevel1: currentLevel === LEVEL_IDS.LEVEL1
    });
  }
  
  return { canClimb: false, objectName: null };
}
