// VR availability detection
let vrSupported = false;
async function checkVRSupport() {
  if (navigator.xr) {
    try {
      vrSupported = await navigator.xr.isSessionSupported('immersive-vr');
      console.log(`🥽 [VR] WebXR support: ${vrSupported ? '✅ Available' : '❌ Not available'}`);
      return vrSupported;
    } catch (err) {
      console.warn('⚠️ [VR] Error checking WebXR support:', err);
      return false;
    }
  } else {
    console.log('💡 [VR] WebXR API not available in this browser');
    return false;
  }
}
// Check VR support on initialization
checkVRSupport();

// VR Session Management
let vrInputProvider = null;
let currentVRSession = null;

/**
 * Start VR Session
 */
async function startVRSession() {
  if (!navigator.xr) {
    console.error('❌ [VR] WebXR not available');
    return false;
  }
  
  if (!vrSupported) {
    console.warn('⚠️ [VR] VR not supported on this device');
    return false;
  }
  
  try {
    // Request immersive VR session
    const session = await navigator.xr.requestSession('immersive-vr', {
      requiredFeatures: ['local-floor'], // Floor-level tracking
      optionalFeatures: ['hand-tracking'] // Optional hand tracking
    });
    
    currentVRSession = session;
    
    // Enable VR in renderer
    await renderer.xr.setSession(session);
    
    // Create and register VR input provider
    vrInputProvider = new VRInputProvider(session);
    if (vrInputProvider.enable()) {
      // Register with PlayerControls
      if (playerControls) {
        playerControls.registerInputProvider(vrInputProvider);
        await playerControls.enableVR(session);
        console.log('✅ [VR] VR session started and registered with PlayerControls');
      }
    }
    
    // Handle session end
    session.addEventListener('end', () => {
      endVRSession();
    });
    
    console.log('🥽 [VR] VR session started successfully');
    return true;
  } catch (err) {
    console.error('❌ [VR] Failed to start VR session:', err);
    return false;
  }
}

/**
 * End VR Session
 */
function endVRSession() {
  if (currentVRSession) {
    currentVRSession.end();
  }
  
  if (vrInputProvider) {
    vrInputProvider.disable();
    if (playerControls) {
      playerControls.disableVR();
    }
    vrInputProvider = null;
  }
  
  currentVRSession = null;
  console.log('🖥️ [VR] VR session ended, returned to desktop mode');
}

/**
 * Check if VR session is active
 */
function isVRSessionActive() {
  return currentVRSession !== null && renderer.xr.isPresenting;
}

