function resumeAudioContextIfNeeded() {
  if (!audioListener || !audioListener.context) {
    return;
  }
  const context = audioListener.context;
  if (context.state === "suspended") {
    context.resume().catch((error) => {
      console.warn("⚠️ [AUDIO] Failed to resume audio context:", error);
    });
  }
}

["pointerdown", "touchstart", "keydown"].forEach((eventName) => {
  document.addEventListener(eventName, resumeAudioContextIfNeeded, { passive: true });
});

function stopFootstepSound() {
  if (footstepSound && footstepSound.isPlaying) {
    footstepSound.stop();
  }
}

function updateFootstepSoundState() {
  if (!footstepAudioReady || !footstepSound) return;
  
  const horizontalSpeed = Math.sqrt(
    (playerVelocity?.x || 0) * (playerVelocity?.x || 0) +
    (playerVelocity?.z || 0) * (playerVelocity?.z || 0)
  );
  const shouldPlay = soundFxEnabled && !isGamePaused && onGround && horizontalSpeed > 0.5;
  
  if (shouldPlay) {
    resumeAudioContextIfNeeded();
    if (!footstepSound.isPlaying) {
      footstepSound.play();
    }
    const playbackRate = THREE.MathUtils.clamp(0.5 + horizontalSpeed / 22, 0.5, 1.0);
    footstepSound.setPlaybackRate(playbackRate);
  } else if (footstepSound.isPlaying) {
    stopFootstepSound();
  }
}

