function triggerCheeseAimCelebration(targetMesh) {
  const mesh =
    targetMesh ||
    (floatingCheese && floatingCheese.mesh ? floatingCheese.mesh : null);
  if (!mesh) return;

  const originalScale = mesh.scale.clone();
  const originalPosition = mesh.position.clone();
  const originalEmissive =
    mesh.material && mesh.material.emissive ? mesh.material.emissive.clone() : null;
  const originalIntensity = mesh.material ? mesh.material.emissiveIntensity : null;

  mesh.scale.multiplyScalar(1.2);
  if (mesh.material) {
    mesh.material.emissive = new THREE.Color(0xfff1a1);
    mesh.material.emissiveIntensity = 0.9;
    mesh.material.needsUpdate = true;
  }

  const shakeStart = performance.now();
  const shakeDuration = 280; // ms
  const shakeAmplitude = 0.08;

  function applyShake(timestamp) {
    const elapsed = timestamp - shakeStart;
    if (elapsed >= shakeDuration) {
      mesh.position.copy(originalPosition);
      mesh.scale.copy(originalScale);
      if (mesh.material) {
        if (originalEmissive) {
          mesh.material.emissive.copy(originalEmissive);
        }
        if (originalIntensity !== null) {
          mesh.material.emissiveIntensity = originalIntensity;
        }
        mesh.material.needsUpdate = true;
      }
      return;
    }

    const shakeOffset = Math.sin((elapsed / shakeDuration) * Math.PI * 10) * shakeAmplitude;
    mesh.position.set(
      originalPosition.x,
      originalPosition.y + shakeOffset,
      originalPosition.z
    );
    requestAnimationFrame(applyShake);
  }

  requestAnimationFrame(applyShake);
}

