// Background Music Functions
function stopBackgroundMusic() {
  if (currentBackgroundMusic && currentBackgroundMusic.isPlaying) {
    currentBackgroundMusic.stop();
  }
  currentBackgroundMusic = null;
}

function pauseBackgroundMusic() {
  if (currentBackgroundMusic && currentBackgroundMusic.isPlaying) {
    currentBackgroundMusic.pause();
  }
}

function resumeBackgroundMusic() {
  if (currentBackgroundMusic && backgroundMusicEnabled && !isGamePaused) {
    if (!currentBackgroundMusic.isPlaying) {
      currentBackgroundMusic.play();
    }
  }
}

function loadBackgroundMusic(levelId) {
  // Check if audioListener is initialized
  try {
    if (!audioListener) {
      console.warn(`⚠️ [AUDIO] Audio listener not initialized yet, cannot load music for ${levelId}`);
      return null;
    }
  } catch (e) {
    // audioListener not initialized yet
    console.warn(`⚠️ [AUDIO] Audio listener not initialized yet, cannot load music for ${levelId}`);
    return null;
  }

  const musicPath = BACKGROUND_MUSIC_PATHS[levelId];
  if (!musicPath) {
    console.warn(`⚠️ [AUDIO] No background music path for level: ${levelId}`);
    return null;
  }

  // Return existing music object if already loaded
  if (backgroundMusicObjects[levelId]) {
    return backgroundMusicObjects[levelId];
  }

  // Create new music object
  const music = new THREE.Audio(audioListener);
  music.userData = music.userData || {};
  music.userData.levelId = levelId;
  backgroundMusicObjects[levelId] = music;

  const resolvedMusicPath = resolveAssetPath(musicPath);
  console.log(`🔍 [AUDIO DEBUG] Loading background music: "${musicPath}" → "${resolvedMusicPath}"`);
  console.log(`🔍 [AUDIO DEBUG] Full URL would be: ${window.location.origin}${resolvedMusicPath}`);
  audioLoader.load(
    resolvedMusicPath,
    (buffer) => {
      music.setBuffer(buffer);
      music.setLoop(true); // Loop the music
      music.setVolume(backgroundMusicVolume);
      console.log(`✅ [AUDIO] Background music loaded for ${levelId}: ${musicPath}`);
      
      // If this is the current level and music is enabled, play it
      if (currentLevel === levelId && backgroundMusicEnabled) {
        playBackgroundMusic(levelId);
      }
    },
    undefined,
    (error) => {
      console.error(`❌ [AUDIO] Failed to load background music for ${levelId}:`, error);
      // Remove failed music object
      delete backgroundMusicObjects[levelId];
    }
  );

  return music;
}

function playBackgroundMusic(levelId) {
  if (!backgroundMusicEnabled) {
    return; // Music is disabled
  }

  // Check if audioListener is initialized (may not be ready during initial setup)
  try {
    if (!audioListener) {
      return;
    }
  } catch (e) {
    // audioListener not initialized yet
    return;
  }

  // Resume audio context if needed (required for autoplay policies)
  resumeAudioContextIfNeeded();

  // Stop current music
  stopBackgroundMusic();

  // Load and play music for this level
  let music = backgroundMusicObjects[levelId];
  if (!music) {
    music = loadBackgroundMusic(levelId);
    if (!music) {
      return; // Failed to load
    }
  }

  // Wait for buffer to be loaded before playing
  if (music.buffer) {
    music.setVolume(backgroundMusicVolume);
    if (!isGamePaused) {
      music.play();
    }
    music.userData = music.userData || {};
    music.userData.levelId = levelId;
    music._levelId = levelId;
    currentBackgroundMusic = music;
    console.log(`🎵 [AUDIO] Playing background music for ${levelId}`);
  } else {
    // Buffer not loaded yet, wait for it
    const checkBuffer = setInterval(() => {
      if (music.buffer) {
        clearInterval(checkBuffer);
        music.setVolume(backgroundMusicVolume);
        if (!isGamePaused) {
          music.play();
        }
        music.userData = music.userData || {};
        music.userData.levelId = levelId;
        music._levelId = levelId;
        currentBackgroundMusic = music;
        console.log(`🎵 [AUDIO] Playing background music for ${levelId}`);
      }
    }, 100);
    
    // Timeout after 5 seconds
    setTimeout(() => {
      clearInterval(checkBuffer);
    }, 5000);
  }
}

function setBackgroundMusicEnabled(enabled) {
  backgroundMusicEnabled = enabled;
  try {
    localStorage.setItem(BACKGROUND_MUSIC_STORAGE_KEY, enabled ? "true" : "false");
  } catch (error) {
    console.warn("⚠️ [AUDIO] Failed to save background music preference:", error);
  }
  
  if (enabled) {
    // Play music for current level
    playBackgroundMusic(currentLevel);
  } else {
    // Stop current music
    stopBackgroundMusic();
  }
  
  updateBackgroundMusicButtons();
}

function setBackgroundMusicVolume(volume) {
  backgroundMusicVolume = Math.max(0, Math.min(1, volume)); // Clamp between 0 and 1
  try {
    localStorage.setItem(BACKGROUND_MUSIC_VOLUME_STORAGE_KEY, backgroundMusicVolume.toString());
  } catch (error) {
    console.warn("⚠️ [AUDIO] Failed to save background music volume:", error);
  }
  
  // Update volume of current music if playing
  if (currentBackgroundMusic) {
    currentBackgroundMusic.setVolume(backgroundMusicVolume);
  }
  
  // Update volume of all loaded music objects
  Object.values(backgroundMusicObjects).forEach(music => {
    if (music && music.buffer) {
      music.setVolume(backgroundMusicVolume);
    }
  });
  
  updateBackgroundMusicVolumeSlider();
}

function updateBackgroundMusicButtons() {
  if (!optionsMenu) return;
  const offBtn = optionsMenu._backgroundMusicOffBtn;
  const onBtn = optionsMenu._backgroundMusicOnBtn;
  if (offBtn && onBtn) {
    offBtn.style.background = !backgroundMusicEnabled ? "rgba(255, 224, 102, 0.3)" : "rgba(255, 255, 255, 0.1)";
    offBtn.style.color = !backgroundMusicEnabled ? "#ffe066" : "#cbd5f5";
    onBtn.style.background = backgroundMusicEnabled ? "rgba(255, 224, 102, 0.3)" : "rgba(255, 255, 255, 0.1)";
    onBtn.style.color = backgroundMusicEnabled ? "#ffe066" : "#cbd5f5";
  }
}

function updateBackgroundMusicVolumeSlider() {
  if (!optionsMenu) return;
  const volumeSlider = optionsMenu._backgroundMusicVolumeSlider;
  const volumeValue = optionsMenu._backgroundMusicVolumeValue;
  if (volumeSlider) {
    volumeSlider.value = backgroundMusicVolume;
  }
  if (volumeValue) {
    volumeValue.textContent = Math.round(backgroundMusicVolume * 100) + "%";
  }
}

function ensureBackgroundMusicForCurrentLevel(force = false) {
  if (!backgroundMusicEnabled) {
    return;
  }

  try {
    if (!audioListener) {
      return;
    }
  } catch (error) {
    return;
  }

  if (force) {
    playBackgroundMusic(currentLevel);
    return;
  }

  const currentLevelId = currentLevel;
  const playingLevelId =
    (currentBackgroundMusic && (currentBackgroundMusic.userData?.levelId || currentBackgroundMusic._levelId)) || null;
  const isPlaying = currentBackgroundMusic && currentBackgroundMusic.isPlaying;

  if (!isPlaying || playingLevelId !== currentLevelId) {
    playBackgroundMusic(currentLevelId);
  } else {
    currentBackgroundMusic.setVolume(backgroundMusicVolume);
  }
}

// 🎮 PLAYER CONTROLS MODULE - VR-Ready Architecture
// NOTE: PointerLockControls is now managed by PlayerControls module
// Old controls variable removed - use playerControls.getPointerLockControls() instead
// Initialize Player Controls Module with all necessary callbacks
let playerControls = null;

// Helper function to initialize Player Controls (called after scene/camera/renderer are ready)
function initializePlayerControls() {
  if (playerControls) {
    console.warn("⚠️ [PLAYER CONTROLS] Already initialized, skipping...");
    return;
  }

  try {
    playerControls = new PlayerControls(scene, camera, renderer, {
      // Callbacks to get current state from main.js
      getGodMode: () => godMode,
      getCameraMode: () => cameraMode,
      getCurrentLevel: () => currentLevel,
      getOnGround: () => onGround,
      isFirstPerson: () => isFirstPerson(),
      isThirdPerson: () => isThirdPerson(),
      isJoystickView: () => isJoystickView(),

      // Callbacks for actions (these will be called from controls)
      onJump: (event) => {
        // 🧗 CLIMBING: Exit climb mode when jump is pressed
        if (isClimbing) {
          isClimbing = false;
          climbSurfaceNormal = null;
        }
        // Jump logic: Space key pressed in normal mode
        // Supports: Normal jump (on ground) and Double jump (in air, somersault animation)
        if (!event || !event.repeat) {
          if (!godMode) {
            // Level 5 has super jump mode (5x higher than normal)
            const isLevel5 = currentLevel === LEVEL_IDS.LEVEL5;
            
            if (onGround) {
              // Normal jump: On ground, first jump
              const jumpHeight = isLevel5 ? 75 : 15; // Super jump in Level 5 (5x = 75), normal jump elsewhere (15)
              playerVelocity.y = jumpHeight;
              hasDoubleJumped = false; // Reset double jump flag when on ground
              playJumpSound();
              
              // Trigger normal jump animation (already handled by animation state machine)
              if (playerModelModule && playerModelModule.isLoaded() && playerModelModule.isMouseCharacter()) {
                // Jump animation will be triggered automatically by animation state machine
                // But we can ensure it's playing
                console.log("🦘 [JUMP] Normal jump - jump animation should play");
              }
              
              if (isLevel5) {
                console.log("🚀 [LEVEL 5] Super jump activated!");
              }
            } else if (!hasDoubleJumped) {
              // Double jump: In air, not yet double jumped
              // Use somersault animation for double jump
              // 🎮 Allow double jump even when falling (removed velocity check for better feel)
              const doubleJumpHeight = isLevel5 ? 50 : 12; // Slightly less than first jump
              playerVelocity.y = doubleJumpHeight;
              hasDoubleJumped = true; // Mark double jump as used
              playJumpSound();
              
              console.log("🤸 [DOUBLE JUMP] Double jump activated! Velocity.y:", playerVelocity.y.toFixed(2));
              
              // Trigger somersault animation for double jump
              if (playerModelModule && playerModelModule.isLoaded() && playerModelModule.isMouseCharacter()) {
                playerModelModule.triggerAnimation('somersoult', true); // Immediate, interrupts other animations
                console.log("🤸 [DOUBLE JUMP] Somersault animation triggered!");
              } else if (playerCharacterAnimations['somersoult']) {
                // Fallback to legacy system if PlayerModel module not available
                const somersaultAction = playerCharacterAnimations['somersoult'];
                if (somersaultAction) {
                  // Stop other animations and play somersault
                  Object.keys(playerCharacterAnimations).forEach(animName => {
                    if (animName !== 'somersoult') {
                      const action = playerCharacterAnimations[animName];
                      if (action && action.enabled) {
                        action.fadeOut(0.1);
                      }
                    }
                  });
                  somersaultAction.reset();
                  somersaultAction.setLoop(THREE.LoopOnce, 1);
                  somersaultAction.setEffectiveWeight(1.0);
                  somersaultAction.play();
                  console.log("🤸 [DOUBLE JUMP] Somersault animation triggered (legacy system)!");
                }
              }
              
              if (isLevel5) {
                console.log("🚀 [LEVEL 5] Super double jump activated!");
              }
            }
          }
        }
      },
      onInteract: () => {
        // E key interaction - open nearest chest if available
        if (nearestInteractableChest && !nearestInteractableChest.opened && chestSystem) {
          // Award DSPOINC reward via API
          const awardRewardCallback = async (chest) => {
            if (!resolvedDiscordId) {
              console.warn(`🎁 [CHEST] Skipping DSPOINC reward for ${chest.id} — no Discord ID.`);
              return;
            }
            try {
              const payload = {
                discord_id: resolvedDiscordId,
                discord_name: playerDisplayName && playerDisplayName !== "Guest" ? playerDisplayName : null,
                riddle_id: `CHEST_${chest.id}`,
                level_id: chest.levelId,
                base_reward: chest.dspoincAmount,
                session_id: cheeseSessionId
              };
              
              console.log(`🎁 [CHEST] Awarding ${chest.dspoincAmount} DSPOINC for opening ${chest.id}`, payload);
              
              const response = await fetch(RIDDLE_REWARD_ENDPOINT, {
                method: 'POST',
                headers: { 'Content-Type': 'application/json' },
                credentials: 'include',
                body: JSON.stringify(payload)
              });
              
              const result = await response.json().catch(() => ({ success: false, error: "Invalid JSON" }));
              
              if (response.ok && result.success) {
                const dsPoincAwarded = result.data?.ds_poinc_awarded || 0;
                const totalDspoinc = result.data?.total_ds_poinc;
                
                if (typeof totalDspoinc === "number") {
                  currentTotalDspoinc = totalDspoinc;
                  window.localStorage.setItem("narrrfs_last_ds_balance", String(currentTotalDspoinc));
                  if (isGamePaused) updatePausePlayerInfo();
                }
                
                // Show reward notification
                showRiddleRewardNotification(dsPoincAwarded, result.data?.multiplier || 1.0);
                
                console.log(`✅ [CHEST] DSPOINC awarded successfully for ${chest.id}:`, {
                  baseReward: chest.dspoincAmount,
                  dsPoincAwarded,
                  totalDspoinc,
                  multiplier: result.data?.multiplier || 1.0
                });
                
                // Increment chest counter (only on successful reward, not 409 Conflict)
                if (chestSystem) {
                  chestSystem.incrementChestsOpenedCount();
                  // Mark chest as opened in cache
                  chestSystem.markChestAsOpened(chest.id);
                }
              } else if (response.status === 409) {
                console.warn(`🎁 [CHEST] Reward already claimed for ${chest.id}`);
                // Mark chest as opened in cache (even though reward was already claimed)
                if (chestSystem) {
                  chestSystem.markChestAsOpened(chest.id);
                }
                // Restore opened state immediately
                if (chest && typeof chest.restoreOpenedState === 'function') {
                  chest.restoreOpenedState();
                }
                showRiddleRewardNotification(0, 1.0, true); // Show "already completed" message
              } else {
                console.warn(`🎁 [CHEST] DSPOINC reward failed for ${chest.id}:`, result.error);
                showRiddleRewardNotification(0, 1.0, true); // Show error as "already completed" to avoid confusion
              }
            } catch (error) {
              console.error(`❌ [CHEST] Failed to award DSPOINC for ${chest.id}:`, error);
            }
          };
          
          // Open the chest
          nearestInteractableChest.open(awardRewardCallback);
          
          // Hide prompt after opening
          if (guiSystem) {
            guiSystem.hideInteractionPrompt();
          }
          
          // Clear nearest chest reference
          nearestInteractableChest = null;
        }
      },
      onWeaponSwitch: (slot) => {
        // Weapon switching for Level 4 (handled in keydown event listener)
        if (currentLevel === LEVEL_IDS.LEVEL4) {
          if (weaponSystem && typeof weaponSystem.switchWeapon === 'function') {
            weaponSystem.switchWeapon(slot);
          } else if (typeof switchLevel4WeaponSlot === 'function') {
            switchLevel4WeaponSlot(slot); // Legacy fallback
          }
        }
      },
      onPause: () => {
        togglePause();
      },
      onCameraModeChange: (mode) => {
        setCameraMode(mode);
      },

      // Mobile detection
      isMobile: isMobile,
      isMobileLandscape: isMobileLandscape,

      // Third-person camera config
      thirdPersonCameraDistanceMin: thirdPersonCameraDistanceMin,
      thirdPersonCameraDistanceMax: thirdPersonCameraDistanceMax,
      thirdPersonCameraHeight: thirdPersonCameraHeight
    });

    console.log("✅ [PLAYER CONTROLS] Module initialized successfully");
  } catch (error) {
    console.error("❌ [PLAYER CONTROLS] Failed to initialize:", error);
  }
}

// Initialize Player Controls after scene/camera/renderer are ready
