// Mouse wheel zoom for third-person camera
renderer.domElement.addEventListener("wheel", (e) => {
  if (!isFirstPerson() && !isGamePaused) {
    e.preventDefault();
    const zoomSpeed = 0.5;
    const delta = e.deltaY > 0 ? zoomSpeed : -zoomSpeed;
    thirdPersonCameraDistance = Math.max(
      thirdPersonCameraDistanceMin,
      Math.min(thirdPersonCameraDistanceMax, thirdPersonCameraDistance + delta)
    );
  }
}, { passive: false });

document.addEventListener("pointerlockchange", () => {
  const locked = document.pointerLockElement === renderer.domElement;
  
  // CRITICAL: Clear pointer lock flags when lock is acquired (January 4, 2026)
  if (locked) {
    window.needsPointerLockAfterLoad = false; // Clear level load flag
    // window.needsPointerLockAfterPause is cleared elsewhere in pause/resume logic
    console.log("✅ [POINTER LOCK] Pointer lock acquired - flags cleared");
  }
  
  // Level 4: Show feedback when pointer locks in Step 1
  if (locked && currentLevel === LEVEL_IDS.LEVEL4 && level4RiddleState.step1Active) {
    showRiddleToast("🔫 Pointer locked! Left-click to shoot at the cheeses!", {
      id: "level4_pointer_locked",
      duration: 3000
    });
  }
  document.body.classList.toggle("cheese-controls-locked", locked);
  
  // If options menu is open, ensure cursor stays visible
  if (optionsMenu && optionsMenu.style.display === "flex") {
    if (playerControls) {
      playerControls.getPointerLockControls().unlock();
    }
    document.body.style.cursor = "default";
    return; // Don't process further if options menu is open
  }
  
  // If game is paused, don't lock pointer
  if (isGamePaused) {
    if (locked && playerControls) {
      playerControls.getPointerLockControls().unlock();
    }
    document.body.style.cursor = "default";
    return;
  }
  
  // FIX: Clear needsPointerLockAfterPause flag when pointer is locked
  if (locked && window.needsPointerLockAfterPause) {
    window.needsPointerLockAfterPause = false;
    console.log("🎮 [PAUSE] Pointer lock re-enabled after resume");
  }
  
  // Don't auto-pause when unlocking - allow free camera movement in third-person
  if (!locked && !isGamePaused && isFirstPerson()) {
    togglePause(true);
  }
});

