// Create NPC monster that patrols the level
async function createNPCMonster(spawnData, blockSize) {
  try {
    console.log("🐉 [NPC] Creating monster NPC...");
    
    // Load monster model (use Bunny for now, can be changed later)
    const monsterModelPath = "/textures/3d models/Monster 1/Big/glTF/Bunny.gltf";
    const gltf = await loadModel(monsterModelPath);
    
    // Clone the scene for the NPC
    npcMonster = gltf.scene.clone(true);
    
    // Set up NPC model properties
    npcMonster.traverse((child) => {
      if (child.isMesh) {
        child.castShadow = true;
        child.receiveShadow = true;
        child.frustumCulled = false; // Disable frustum culling for visibility
        child.visible = true;
        
        // FIX: Handle both single material and material arrays (same as player character)
        const hasMaterialArray = Array.isArray(child.material);
        const materialsToProcess = hasMaterialArray ? child.material : [child.material];
        
        // Use a bright red material to distinguish from player (green)
        if (child.material) {
          // FIX: Use MeshStandardMaterial with high emissive for maximum visibility
          const npcMaterial = new THREE.MeshStandardMaterial({ 
            color: 0xff0000, // Bright red for NPC (distinct from player's green)
            side: THREE.DoubleSide,
            emissive: 0xff3333, // Bright red glow for visibility
            emissiveIntensity: 3.0, // 300% emissive glow - VERY visible! (same as player)
            metalness: 0.0, // Not metallic
            roughness: 0.3 // Lower roughness for brighter appearance
          });
          
          // FIX: Apply material to all material slots (handle arrays)
          if (hasMaterialArray) {
            // Replace all materials in array with red material
            for (let i = 0; i < child.material.length; i++) {
              child.material[i] = npcMaterial;
              child.material[i].needsUpdate = true;
            }
            console.log("🐉 [NPC] Replaced", child.material.length, "materials with bright red MeshStandardMaterial for mesh:", child.name);
          } else {
            // Single material - replace directly
            child.material = npcMaterial;
            child.material.needsUpdate = true;
            console.log("🐉 [NPC] Using bright red MeshStandardMaterial for mesh:", child.name, "Emissive:", npcMaterial.emissiveIntensity);
          }
        } else {
          // No material - create one
          const npcMaterial = new THREE.MeshStandardMaterial({ 
            color: 0xff0000, // Bright red
            emissive: 0xff3333,
            emissiveIntensity: 3.0,
            side: THREE.DoubleSide
          });
          child.material = npcMaterial;
          child.material.needsUpdate = true;
          console.log("🐉 [NPC] Created bright red material for mesh:", child.name);
        }
      }
    });
    
    // Scale NPC to appropriate size (calculate based on original model size, same as player)
    // FIX: Use same scale calculation as player character for consistency
    const npcOriginalBox = new THREE.Box3().setFromObject(npcMonster);
    const npcOriginalSize = npcOriginalBox.getSize(new THREE.Vector3());
    const npcTargetHeight = 1.4; // Slightly smaller than player (1.7 units)
    const npcScale = npcTargetHeight / npcOriginalSize.y; // Scale to match target height
    npcMonster.scale.set(npcScale, npcScale, npcScale);
    
    console.log("🐉 [NPC] NPC scale calculation:", {
      originalSize: { x: npcOriginalSize.x.toFixed(2), y: npcOriginalSize.y.toFixed(2), z: npcOriginalSize.z.toFixed(2) },
      targetHeight: npcTargetHeight.toFixed(2),
      scale: npcScale.toFixed(2)
    });
    
    // Position NPC at a random location in the level (away from spawn)
    const spawnX = spawnData.x || 60;
    const spawnZ = spawnData.z || 15;
    const mapSize = 120; // Level size
    
    // Random position away from spawn (at least 20 units away)
    let npcX = spawnX + (Math.random() > 0.5 ? 1 : -1) * (20 + Math.random() * 30);
    let npcZ = spawnZ + (Math.random() > 0.5 ? 1 : -1) * (20 + Math.random() * 30);
    
    // Clamp to map bounds
    npcX = Math.max(10, Math.min(mapSize - 10, npcX));
    npcZ = Math.max(10, Math.min(mapSize - 10, npcZ));
    
    // Position at ground level (match player ground level calculation)
    // Player collider bottom is at y = playerPos.y - 0.35 (radius)
    // NPC should be at similar ground level - use player spawn position as reference
    const playerSpawnY = (spawnData.y || 2.0) + 0.65; // Player spawn center Y (spawn.y + player radius + half height)
    const npcGroundLevel = playerSpawnY - 0.35 - 0.7; // Ground level (player spawn bottom - half NPC height)
    
    // Calculate NPC height offset based on scaled model size (after scaling)
    // Must calculate after scaling is applied
    npcMonster.updateMatrixWorld(true); // Update matrix after scaling
    const npcLocalBox = new THREE.Box3().setFromObject(npcMonster);
    const npcLocalSize = npcLocalBox.getSize(new THREE.Vector3());
    const npcHeightOffset = npcLocalSize.y / 2; // Half of NPC height (local)
    const npcY = npcGroundLevel + npcHeightOffset; // NPC center at proper height
    
    npcMonster.position.set(npcX, npcY, npcZ);
    npcMonster.updateMatrixWorld(true); // Update matrix after positioning
    
    // Create patrol path (waypoints for NPC to follow)
    // Use same Y level for all waypoints (ground level)
    npcMonsterPath = [
      new THREE.Vector3(npcX, npcY, npcZ),
      new THREE.Vector3(npcX + 20, npcY, npcZ),
      new THREE.Vector3(npcX + 20, npcY, npcZ + 20),
      new THREE.Vector3(npcX, npcY, npcZ + 20),
      new THREE.Vector3(npcX, npcY, npcZ) // Return to start
    ];
    npcMonsterPathIndex = 0;
    npcMonsterTargetPosition = npcMonsterPath[0].clone();
    
    console.log("🐉 [NPC] NPC height calculation:", {
      playerSpawnY: playerSpawnY.toFixed(2),
      npcGroundLevel: npcGroundLevel.toFixed(2),
      npcSizeY: npcLocalSize.y.toFixed(2),
      npcHeightOffset: npcHeightOffset.toFixed(2),
      finalY: npcY.toFixed(2),
      position: { x: npcX.toFixed(2), y: npcY.toFixed(2), z: npcZ.toFixed(2) }
    });
    
    // Set up animations if available
    if (gltf.animations && gltf.animations.length > 0) {
      npcMonsterMixer = new THREE.AnimationMixer(npcMonster);
      
      // Store all animations
      gltf.animations.forEach((clip) => {
        const action = npcMonsterMixer.clipAction(clip);
        npcMonsterAnimations[clip.name] = action;
      });
      
      // Play walk/run animation
      if (npcMonsterAnimations['Walk'] || npcMonsterAnimations['walk']) {
        const walkAnim = npcMonsterAnimations['Walk'] || npcMonsterAnimations['walk'];
        walkAnim.reset().fadeIn(0.2).play();
        console.log("🐉 [NPC] Playing walk animation");
      } else if (npcMonsterAnimations['Run'] || npcMonsterAnimations['run']) {
        const runAnim = npcMonsterAnimations['Run'] || npcMonsterAnimations['run'];
        runAnim.reset().fadeIn(0.2).play();
        console.log("🐉 [NPC] Playing run animation");
      }
    }
    
    // Add NPC to scene
    scene.add(npcMonster);
    window.npcMonster = npcMonster; // Store globally for access
    
    console.log("🐉 [NPC] Monster NPC created at position:", {
      x: npcX.toFixed(2),
      y: npcY.toFixed(2),
      z: npcZ.toFixed(2),
      pathPoints: npcMonsterPath.length
    });
    
    return npcMonster;
    
  } catch (error) {
    console.error("❌ [NPC] Error creating NPC monster:", error);
    return null;
  }
}

// Update NPC monster position and animation (called in animate loop)
function updateNPCMonster(delta) {
  if (!npcMonster || !window.npcMonster) {
    return;
  }
  
  try {
    // Update animation mixer
    if (npcMonsterMixer) {
      npcMonsterMixer.update(delta);
    }
    
    // Move NPC towards target position
    if (npcMonsterTargetPosition) {
      // Calculate horizontal direction (ignore Y for ground-level movement)
      const npcPos = npcMonster.position.clone();
      const targetPos = npcMonsterTargetPosition.clone();
      npcPos.y = 0; // Ignore Y for direction calculation
      targetPos.y = 0; // Ignore Y for direction calculation
      
      const direction = new THREE.Vector3()
        .subVectors(targetPos, npcPos)
        .normalize();
      
      // Calculate horizontal distance (ignore Y)
      const horizontalDistance = new THREE.Vector2(npcMonster.position.x, npcMonster.position.z)
        .distanceTo(new THREE.Vector2(npcMonsterTargetPosition.x, npcMonsterTargetPosition.z));
      
      if (horizontalDistance > 0.5) {
        // Move towards target (horizontal movement only)
        const moveDistance = npcMonsterSpeed * delta;
        npcMonster.position.x += direction.x * moveDistance;
        npcMonster.position.z += direction.z * moveDistance;
        // Keep Y position fixed (ground level)
        
        // Rotate NPC to face movement direction
        if (direction.lengthSq() > 0.01) {
          const targetRotation = Math.atan2(direction.x, direction.z);
          npcMonster.rotation.y = targetRotation;
        }
      } else {
        // Reached target, move to next waypoint
        npcMonsterPathIndex = (npcMonsterPathIndex + 1) % npcMonsterPath.length;
        npcMonsterTargetPosition = npcMonsterPath[npcMonsterPathIndex].clone();
        if (DEBUG_SETTINGS.logNpcWaypoints) {
        console.log("🐉 [NPC] Reached waypoint", (npcMonsterPathIndex - 1 + npcMonsterPath.length) % npcMonsterPath.length, ", moving to next:", npcMonsterPathIndex, "Position:", {
          x: npcMonsterTargetPosition.x.toFixed(2),
          y: npcMonsterTargetPosition.y.toFixed(2),
          z: npcMonsterTargetPosition.z.toFixed(2)
        });
        }
      }
    }
    
    // Update NPC matrix
    npcMonster.updateMatrixWorld(true);
    
  } catch (error) {
    console.error("❌ [NPC] Error updating NPC monster:", error);
  }
}

// 🦋 Update Level 1 butterfly flying animation
function updateLevel1Butterfly(delta) {
  if (!level1State.butterfly) {
    return;
  }
  
  try {
    // Update animation mixer if model has animations
    if (level1State.butterflyMixer) {
      level1State.butterflyMixer.update(delta);
    }
    
    // Update wing flapping animation (since GLB has no animations)
    butterflyWingFlapAngle += butterflyWingFlapSpeed * delta;
    const wingFlapAmount = Math.sin(butterflyWingFlapAngle) * 0.8; // Flap between -0.8 and 0.8 radians (~45 degrees)
    
    // Animate wing meshes (rotate wings up and down)
    if (butterflyWingMeshes.length > 0) {
      butterflyWingMeshes.forEach((wingMesh, index) => {
        if (wingMesh) {
          // Alternate wing direction (one up, one down for realistic flapping)
          const flapDirection = index % 2 === 0 ? 1 : -1;
          
          // Try rotating on X axis (up/down) - most common for wings
          wingMesh.rotation.x = wingFlapAmount * flapDirection;
          
          // Also try Z axis (forward/back) for more visible effect
          wingMesh.rotation.z = Math.sin(butterflyWingFlapAngle * 1.5) * 0.3 * flapDirection;
          
          // Update matrix to ensure rotation is applied
          wingMesh.updateMatrix();
        }
      });
    } else {
      // Fallback: If no wing meshes found, rotate entire butterfly slightly to simulate flapping
      // This creates a subtle "bobbing" effect
      const bodyBob = Math.sin(butterflyWingFlapAngle * 2) * 0.15; // Small rotation
      level1State.butterfly.rotation.x = bodyBob;
    }
    
    // Add unpredictable flight pattern (random direction changes every few seconds)
    butterflyUnpredictabilityTimer += delta;
    if (butterflyUnpredictabilityTimer > 3.0 + Math.random() * 4.0) { // Change direction every 3-7 seconds (less frequent, more natural)
      butterflyUnpredictability = (Math.random() - 0.5) * 0.4; // Random angle offset (-0.2 to 0.2 radians) - reduced for smoother
      butterflyTargetSpeed = 0.2 + Math.random() * 0.25; // Vary speed between 0.2 and 0.45 (slower range)
      butterflyUnpredictabilityTimer = 0;
    }
    
    // Lerp current speed towards target speed for smooth transitions
    butterflyCurrentSpeed += (butterflyTargetSpeed - butterflyCurrentSpeed) * delta * 1.5; // Slower lerp for smoother transitions
    
    // Update flight angle with unpredictability and variable speed
    butterflyAngle += butterflyCurrentSpeed * delta;
    const effectiveAngle = butterflyAngle + butterflyUnpredictability;
    
    // Create more natural butterfly flight pattern (combination of figure-8 and smooth curves)
    // Use multiple sine waves for organic, unpredictable movement
    const pattern1 = Math.sin(effectiveAngle);
    const pattern2 = Math.sin(effectiveAngle * 0.7) * Math.cos(effectiveAngle * 1.3);
    const pattern3 = Math.sin(effectiveAngle * 0.5) * 0.3; // Subtle third pattern
    
    // Combine patterns for natural butterfly flight
    const figure8X = pattern1 * 0.7 + pattern2 * 0.3;
    const figure8Z = pattern1 * Math.cos(effectiveAngle) * 0.6 + pattern2 * 0.4 + pattern3;
    
    // Calculate position with natural pattern
    let x = butterflyCenterX + figure8X * butterflyFlightRadius;
    let z = butterflyCenterZ + figure8Z * butterflyFlightRadius;
    
    // Add vertical sine wave variation (Y) with multiple frequencies for natural movement
    // Keep Y higher to avoid ground - base at 8, with variation up to 10.5 and down to 5.5
    const verticalWave1 = Math.sin(effectiveAngle * butterflyVerticalSpeed) * butterflyVerticalAmplitude;
    const verticalWave2 = Math.sin(effectiveAngle * 0.4) * 1.0; // Slow vertical variation
    const verticalWave3 = Math.sin(effectiveAngle * 1.8) * 0.5; // Fast subtle variation
    const y = butterflyCenterY + verticalWave1 + verticalWave2 + verticalWave3;
    
    // Boundary checking - keep butterfly within game field bounds
    x = Math.max(butterflyMapBounds.minX, Math.min(butterflyMapBounds.maxX, x));
    z = Math.max(butterflyMapBounds.minZ, Math.min(butterflyMapBounds.maxZ, z));
    const clampedY = Math.max(butterflyMapBounds.minY, Math.min(butterflyMapBounds.maxY, y));
    
    // Update butterfly position
    level1State.butterfly.position.set(x, clampedY, z);
    
    // Calculate direction for rotation (butterfly faces movement direction)
    // Use velocity-based direction for smoother rotation
    const prevPos = level1State.butterfly.userData.prevPosition || new THREE.Vector3(x, clampedY, z);
    const velocity = new THREE.Vector3().subVectors(
      new THREE.Vector3(x, clampedY, z),
      prevPos
    );
    
    // Store current position for next frame
    level1State.butterfly.userData.prevPosition = new THREE.Vector3(x, clampedY, z);
    
    // Rotate butterfly to face movement direction (smooth rotation)
    if (velocity.lengthSq() > 0.001) {
      velocity.normalize();
      const targetRotation = Math.atan2(velocity.x, velocity.z);
      // Smooth rotation interpolation
      const currentRotation = level1State.butterfly.rotation.y;
      let rotationDiff = targetRotation - currentRotation;
      
      // Normalize rotation difference to shortest path
      while (rotationDiff > Math.PI) rotationDiff -= Math.PI * 2;
      while (rotationDiff < -Math.PI) rotationDiff += Math.PI * 2;
      
      // Smooth interpolation
      level1State.butterfly.rotation.y = currentRotation + rotationDiff * delta * 5;
    }
    
    // Update matrix
    level1State.butterfly.updateMatrixWorld(true);
    
  } catch (error) {
    console.error("❌ [BUTTERFLY] Error updating butterfly:", error);
  }
}

// Update player character position and rotation (called in animate loop)
/**
 * 🐭 UNIVERSAL CHARACTER RENDERING FUNCTION
 * 
 * This function provides smooth character rendering for ALL levels (1, 2, 3, 4, and all future levels).
 * It is called universally in the animate() loop, outside all level-specific checks.
 * 
 * STANDARD RULE: See MOUSE_CHARACTER_RENDERING_STANDARD.md for complete implementation details.
 * 
 * Features:
 * - Smooth position interpolation (eliminates lag)
 * - Correct height offset (Mouse: 0.95, Animation Library: 0.85 * scale)
 * - Animation speed scaling (matches movement speed)
 * - Velocity-based rotation (smooth character facing)
 * 
 * @param {number} delta - Time delta since last frame (for smooth interpolation)
 */
function updatePlayerCharacter(delta) {
  // 🚨 CRITICAL PERFORMANCE FIX: Throttle Level 3 character checks to prevent per-frame lag
  // The previous code was filtering scene.children every frame which is extremely expensive
  // Only check every 30 frames (~2 times per second) to prevent stuttering during movement
  if (currentLevel === LEVEL_IDS.LEVEL3 && playerCharacterModel) {
    if (!level3State.lastCharacterCheck) level3State.lastCharacterCheck = 0;
    level3State.lastCharacterCheck += delta;
    
    // Only run expensive checks every ~0.5 seconds (30 frames at 60fps)
    if (level3State.lastCharacterCheck >= 0.5) {
      level3State.lastCharacterCheck = 0;
      
      // CRITICAL: Ensure character is NOT in level3State.group (causes rendering conflicts)
      if (level3State && level3State.group && level3State.group.children.includes(playerCharacterModel)) {
        level3State.group.remove(playerCharacterModel);
      }
      // CRITICAL: Ensure character is in scene root (not in any level group)
      // Use direct parent check instead of expensive filter operation
      if (playerCharacterModel.parent !== scene) {
        if (playerCharacterModel.parent) {
          playerCharacterModel.parent.remove(playerCharacterModel);
        }
        scene.add(playerCharacterModel);
      }
    }
    // CRITICAL: Force matrix update once per frame to prevent visual lag
    // This ensures character position is synchronized with moving walls
    // Moving walls require constant matrix updates to maintain synchronization
    playerCharacterModel.updateMatrixWorld(false);
  }
  // Early return if character model doesn't exist or GLTF character is not active
  // CRITICAL: Support both old system and new PlayerModel module
  // If PlayerModel module is loaded, use its model, otherwise use old system
  const hasOldSystem = playerCharacterModel && useGLTFCharacter;
  const hasNewSystem = playerModelModule && playerModelModule.isLoaded();
  
  // If neither system is active, skip animation updates
  if (!hasOldSystem && !hasNewSystem) {
    return;
  }
  
  // CRITICAL: If using PlayerModel module but old system variables aren't set, sync them
  if (hasNewSystem && !hasOldSystem) {
    // Get model from PlayerModel module
    const moduleModel = playerModelModule.getModel();
    const moduleMixer = playerModelModule.getMixer();
    if (moduleModel && !playerCharacterModel) {
      playerCharacterModel = moduleModel;
      useGLTFCharacter = true;
      
      // CRITICAL: Also sync mixer and animations if PlayerModel module has them
      if (moduleMixer && !playerCharacterMixer) {
        playerCharacterMixer = moduleMixer;
      }
      
      // CRITICAL: Sync animations from PlayerModel module to legacy dictionary
      // The PlayerModel module stores animations internally, legacy code needs them in playerCharacterAnimations
      const moduleAnimations = playerModelModule.getAnimations();
      if (moduleAnimations && Object.keys(moduleAnimations).length > 0) {
        // Sync all animations from module to legacy dictionary
        Object.keys(moduleAnimations).forEach(animName => {
          playerCharacterAnimations[animName] = moduleAnimations[animName];
        });
        console.log("🎬 [CHARACTER] Synced PlayerModel module animations to legacy dictionary:", {
          count: Object.keys(moduleAnimations).length,
          animations: Object.keys(moduleAnimations),
          characterType: playerModelModule.characterType
        });
      } else {
        console.warn("⚠️ [CHARACTER] PlayerModel module has no animations - legacy system may not work");
      }
    }
  }
  
  try {
    // Update character position to match player collider with smooth interpolation
    const playerPos = new THREE.Vector3().lerpVectors(playerCollider.start, playerCollider.end, 0.5);
    
    // CRITICAL: Mouse character needs different height offset
    // Mouse character's ground should be at feet, not torso
    const isMouseCharacterModel = (playerCharacterModel && playerCharacterModel.userData && playerCharacterModel.userData.isMouseCharacter) || 
                                   (playerModelModule && playerModelModule.isMouseCharacter());
    let heightOffset = 0.85 * playerCharacterModel.scale.y; // Default for Animation Library (subtract to lower)
    if (isMouseCharacterModel) {
      // Use the same offset during runtime updates
      heightOffset = 0.95;
    }
    
    // Calculate target position with height offset
    const targetY = playerPos.y - heightOffset;
    let targetPos = new THREE.Vector3(playerPos.x, targetY, playerPos.z);
    
    // 🧗 CLIMBING MODE: Special position and rotation handling
    // ✅ STABLE VERSION - December 16, 2025: Character visibility and positioning working correctly
    if (isClimbing && climbSurfaceNormal) {
      // Push character away from wall so it's visible (not inside blocks)
      // CRITICAL: Increase offset to ensure character is fully visible when climbing
      // The player collider might be close to the wall, but the visual model should be offset more
      const wallOffset = 0.5; // STABLE: Increased from 0.3 to 0.5 for better visibility - working correctly
      const offsetDirection = climbSurfaceNormal.clone().negate(); // Point away from wall
      targetPos.add(offsetDirection.multiplyScalar(wallOffset));
      
      // CRITICAL: Ensure character is visible during climbing (even if in first-person mode)
      // Force visibility and ensure all meshes are visible
      if (playerCharacterModel) {
        playerCharacterModel.visible = true;
        playerCharacterModel.traverse((child) => {
          if (child.isMesh) {
            child.visible = true;
            child.frustumCulled = false; // Disable frustum culling to ensure visibility
          }
        });
      }
    }
    
    // MOVEMENT SPEED SYNC: Use centralized settings from PlayerModel module
    // All levels use the same lerp speed (no level-specific overrides)
    // Character model must stay perfectly in sync with player movement for smooth animations
    // CRITICAL: Settings are now in player-model.js - consistent across ALL levels and BOTH character types
    const baseLerpSpeed = playerModelModule ? playerModelModule.getLerpSpeed(godMode) : 180;
    
    // MOVEMENT SPEED SYNC: Tighter delta clamping for smoother interpolation with faster speeds
    // New movement speeds (96/168) require smoother, more consistent interpolation
    // Using actual delta without clamping for maximum responsiveness with faster speeds
    const clampedDelta = delta; // Use actual delta for maximum responsiveness with faster speeds
    const lerpFactor = Math.min(1.0, clampedDelta * baseLerpSpeed); // Smooth interpolation based on delta
    playerCharacterModel.position.lerp(targetPos, lerpFactor);
    
    // 🧗 CLIMBING MODE: Special rotation handling - face the wall
    // ✅ STABLE VERSION - December 16, 2025: Character rotation working correctly - faces wall during climbing
    if (isClimbing && climbSurfaceNormal && useGLTFCharacter && playerCharacterModel) {
      // Face the wall (opposite to wall normal) during climbing
      const wallFacingDirection = climbSurfaceNormal.clone().negate(); // Point toward wall
      wallFacingDirection.y = 0; // Keep horizontal
      wallFacingDirection.normalize();
      
      if (wallFacingDirection.lengthSq() > 0.01) {
        let targetRotation = Math.atan2(wallFacingDirection.x, wallFacingDirection.z);
        
        // CRITICAL: Mouse character has different default orientation
        const isMouseCharacterModel = playerCharacterModel.userData && playerCharacterModel.userData.isMouseCharacter;
        if (isMouseCharacterModel) {
          // Subtract 90 degrees to compensate for Mouse character's default orientation
          targetRotation -= Math.PI / 2;
        }
        
        const currentRotation = playerCharacterModel.rotation.y;
        let rotationDelta = targetRotation - currentRotation;
        
        // Normalize rotation delta to [-PI, PI]
        while (rotationDelta > Math.PI) rotationDelta -= 2 * Math.PI;
        while (rotationDelta < -Math.PI) rotationDelta += 2 * Math.PI;
        
        // Smooth rotation interpolation
        const baseRotationSpeed = playerModelModule ? playerModelModule.getRotationSpeed(godMode) : 0.3;
        const rotationSpeed = Math.min(0.5, Math.abs(rotationDelta) * baseRotationSpeed);
        playerCharacterModel.rotation.y += rotationDelta * rotationSpeed;
      }
    } else if (!isFirstPerson() && playerControls && playerControls.getPointerLockControls().isLocked && useGLTFCharacter && playerCharacterModel) {
      // Normal movement rotation (only in third-person, not climbing)
      const hasMovementInput = movement.forward || movement.backward || movement.left || movement.right;
      // Use velocity magnitude for rotation (same as animation system)
      const velocityMagnitude = Math.sqrt(playerVelocity.x * playerVelocity.x + playerVelocity.z * playerVelocity.z);
      const hasActualVelocity = velocityMagnitude > 0.15;
      
      // Only rotate if there's actual movement (input OR velocity)
      if (hasMovementInput || hasActualVelocity) {
        let targetDirection = new THREE.Vector3();
        
        // Prefer velocity direction (actual movement) over input direction
        if (hasActualVelocity) {
          targetDirection.set(playerVelocity.x, 0, playerVelocity.z);
          targetDirection.normalize();
        } else {
          // Use input direction if no velocity yet (for immediate rotation response)
          const playerMovement = new THREE.Vector3();
          if (movement.forward) playerMovement.z += 1;
          if (movement.backward) playerMovement.z -= 1;
          if (movement.left) playerMovement.x -= 1;
          if (movement.right) playerMovement.x += 1;
          
          if (playerMovement.lengthSq() > 0.01) {
            playerMovement.normalize();
            const forward = getForwardVector();
            const side = getSideVector();
            targetDirection.addScaledVector(forward, playerMovement.z);
            targetDirection.addScaledVector(side, playerMovement.x);
            targetDirection.y = 0;
            targetDirection.normalize();
          }
        }
        
        // Calculate and apply rotation if direction is valid
        if (targetDirection.lengthSq() > 0.01) {
          // CRITICAL: Mouse character has different default orientation
          // Mouse character's visual forward direction needs correction for rotation
          const isMouseCharacterModel = playerCharacterModel.userData && playerCharacterModel.userData.isMouseCharacter;
          
          let targetRotation = Math.atan2(targetDirection.x, targetDirection.z);
          
          // CRITICAL FIX: Mouse character visual rotation offset
          // User feedback: W makes character turn LEFT but move STRAIGHT (forward)
          // This means character's forward is 90 degrees off from movement direction
          // Subtract 90 degrees so character faces the correct direction when moving
          if (isMouseCharacterModel) {
            // Subtract 90 degrees to compensate for Mouse character's default orientation
            // This makes character face forward when moving forward (W key)
            targetRotation -= Math.PI / 2;
          }
          
          const currentRotation = playerCharacterModel.rotation.y;
          let rotationDelta = targetRotation - currentRotation;
          
          // Normalize rotation delta to [-PI, PI]
          while (rotationDelta > Math.PI) rotationDelta -= 2 * Math.PI;
          while (rotationDelta < -Math.PI) rotationDelta += 2 * Math.PI;
          
          // Smooth rotation interpolation (faster when rotating larger angles)
          // STANDARDIZED: Use centralized settings from PlayerModel module
          // Same rotation speed for ALL levels (consistent feel) - no level-specific overrides
          // CRITICAL: Settings are now in player-model.js - consistent across ALL levels and BOTH character types
          const baseRotationSpeed = playerModelModule ? playerModelModule.getRotationSpeed(godMode) : 0.3;
          const rotationSpeed = Math.min(0.5, Math.abs(rotationDelta) * baseRotationSpeed);
          playerCharacterModel.rotation.y += rotationDelta * rotationSpeed;
        }
      }
    }
    
    // Update animations if mixer exists
    if (playerCharacterMixer) {
      try {
        // STANDARDIZED: Use actual delta but ensure it's consistent and clamped
        // This ensures smooth animation playback even when main game loop has frame drops
        // The delta from animate() is already clamped to 0.1, but we ensure smoothness here
        // Use actual time passed for accurate animation speed, but clamp for stability
        // Applied consistently to ALL levels for smooth animation
        // MOVEMENT SPEED SYNC: Use actual delta for smoother animation with faster speeds
        // New movement speeds (96/168) require responsive animation timing
        // Using actual delta without clamping for maximum smoothness with faster speeds
        const animationDelta = delta; // Use actual delta for maximum smoothness with faster speeds
        playerCharacterMixer.update(animationDelta);
        
        // CRITICAL: Properly handle animation transitions based on ACTUAL movement
        // Check both key states AND velocity to prevent rapid switching
        // 🎮 Use movement from Player Controls Module (if available) or fallback to global movement
        const currentMovement = playerControls ? playerControls.getMovementState() : movement;
        const hasMovementInput = currentMovement.forward || currentMovement.backward || currentMovement.left || currentMovement.right;
        
        // DEBUG: Animation debug logging disabled for performance
        // Enable only when specifically debugging animation issues by uncommenting below
        // WARNING: Enabling this will spam console and significantly reduce FPS
        /*
        if (DEBUG_ANIMATION && Math.random() < 0.01) { // 1% chance per frame when enabled
          console.log("🎮 [ANIMATION DEBUG] Movement state:", {
            currentMovement: {
              forward: currentMovement.forward,
              backward: currentMovement.backward,
              left: currentMovement.left,
              right: currentMovement.right,
              sprint: currentMovement.sprint
            },
            hasMovementInput: hasMovementInput,
            playerCharacterAnimations: Object.keys(playerCharacterAnimations),
            hasRun: !!playerCharacterAnimations['run'],
            hasJump: !!playerCharacterAnimations['jump'],
            hasIdle: !!playerCharacterAnimations['idle']
          });
        }
        */
        
        // Calculate velocity magnitude (how fast the character is actually moving)
        const velocityMagnitude = Math.sqrt(playerVelocity.x * playerVelocity.x + playerVelocity.z * playerVelocity.z);
        
        // CRITICAL: Add hysteresis to prevent rapid animation switching (flickering)
        // Track movement state history to smooth out rapid input changes
        if (!window.characterMovementHistory) {
          window.characterMovementHistory = [];
        }
        const history = window.characterMovementHistory;
        history.push({ time: performance.now(), hasInput: hasMovementInput });
        // Keep only last 5 frames of history (smooth over ~83ms at 60 FPS)
        if (history.length > 5) {
          history.shift();
        }
        
        // Require sustained movement input (at least 3 out of 5 frames) to consider "moving"
        // This prevents flickering when input detection is borderline
        const inputFrames = history.filter(h => h.hasInput).length;
        const sustainedInput = inputFrames >= 3; // At least 60% of frames show input
        
        // Character is "moving" if there's sustained input (hysteresis applied)
        // This prevents rapid switching between run and idle animations
        const finalIsMoving = sustainedInput;
        // Use the already-defined currentMovement from above (line 4500)
        const isSprinting = currentMovement.sprint;
        
        // DEBUG: Log movement state occasionally to diagnose animation issues
        if (DEBUG_SETTINGS.logMovementState && Math.random() < 0.02) { // 2% chance = ~1-2 times per second
          console.log("🎮 [CHARACTER] Movement state:", {
            forward: currentMovement.forward,
            backward: currentMovement.backward,
            left: currentMovement.left,
            right: currentMovement.right,
            sprint: currentMovement.sprint,
            hasInput: hasMovementInput,
            velocityMagnitude: velocityMagnitude.toFixed(2),
            velocity: { x: playerVelocity.x.toFixed(2), z: playerVelocity.z.toFixed(2) },
            isMoving: finalIsMoving,
            isSprinting: isSprinting
          });
        }
        
        // CRITICAL: Check if player is jumping (velocity.y > 0 means going up)
        const isJumping = playerVelocity.y > 2.0; // Jumping threshold
        const isFalling = playerVelocity.y < -2.0; // Falling threshold
        
        // CRITICAL: Detect Mouse character and use Mouse-specific animation logic
        const isMouseCharacter = selectedCharacterPath && selectedCharacterPath.includes('Mouse');
        
        // 🧗 CLIMBING: Check if player is climbing (Mouse character only)
        // Determine which animation to play (priority: Climb > Jump > Movement > Idle)
        let targetAnimation = null;
        let targetAnimationName = null;
        
        // 🧗 CLIMBING MODE: Highest priority (Mouse character or Animation Library with climb animation)
        if (isClimbing) {
          if (isMouseCharacter && playerCharacterAnimations['climb']) {
            // Mouse character: Use 'climb' animation
            targetAnimation = playerCharacterAnimations['climb'];
            targetAnimationName = 'climb';
          } else if (!isMouseCharacter) {
            // Animation Library: Try to find climb animations (case-insensitive)
            const climbAnimationNames = Object.keys(playerCharacterAnimations).filter(name => {
              const nameLower = name.toLowerCase();
              return nameLower.includes('climb') || nameLower.includes('climbing') || nameLower.includes('wall');
            });
            if (climbAnimationNames.length > 0) {
              // Use first climb animation found
              targetAnimation = playerCharacterAnimations[climbAnimationNames[0]];
              targetAnimationName = climbAnimationNames[0];
              console.log(`🧗 [ANIMATION] Animation Library using climb animation: ${targetAnimationName}`);
            }
          }
        }
        
        // Continue with other animations if climb not found
        if (!targetAnimation && isJumping) {
        } else if (isJumping) {
          if (isMouseCharacter) {
            // Mouse: Use 'jump' animation
            targetAnimation = playerCharacterAnimations['jump'];
            targetAnimationName = targetAnimation ? 'jump' : null;
          } else {
            // Animation Library: Try jump animations in order
            targetAnimation = playerCharacterAnimations['Jump_Start'] || 
                            playerCharacterAnimations['Jump_Loop'] || 
                            playerCharacterAnimations['Jump'];
            targetAnimationName = targetAnimation ? (
              playerCharacterAnimations['Jump_Start'] ? 'Jump_Start' :
              playerCharacterAnimations['Jump_Loop'] ? 'Jump_Loop' : 'Jump'
            ) : null;
          }
        } else if (isFalling) {
          if (isMouseCharacter) {
            // Mouse: Use 'jump' animation for falling (or could use idle/run)
            targetAnimation = playerCharacterAnimations['jump'] || 
                            playerCharacterAnimations['idle'];
            targetAnimationName = targetAnimation ? (
              playerCharacterAnimations['jump'] ? 'jump' : 'idle'
            ) : null;
          } else {
            // Animation Library: Try landing animations
            targetAnimation = playerCharacterAnimations['Jump_Land'] || 
                            playerCharacterAnimations['Jump_Loop'] ||
                            playerCharacterAnimations['Jump'];
            targetAnimationName = targetAnimation ? (
              playerCharacterAnimations['Jump_Land'] ? 'Jump_Land' :
              playerCharacterAnimations['Jump_Loop'] ? 'Jump_Loop' : 'Jump'
            ) : null;
          }
        } else if (finalIsMoving) {
          if (isMouseCharacter) {
            // Mouse: ALWAYS use 'run' animation for movement (both walk and sprint)
            // Mouse doesn't have separate walk/sprint animations, just 'run'
            targetAnimation = playerCharacterAnimations['run'];
            targetAnimationName = targetAnimation ? 'run' : null;
          } else {
            // Animation Library: Different animations for walk vs sprint
            if (isSprinting) {
              targetAnimation = playerCharacterAnimations['Sprint_Loop'] || 
                              playerCharacterAnimations['Jog_Fwd_Loop'] || 
                              playerCharacterAnimations['Run'] || 
                              playerCharacterAnimations['Running'] || 
                              playerCharacterAnimations['running'] || 
                              playerCharacterAnimations['run'];
              targetAnimationName = targetAnimation ? (
                playerCharacterAnimations['Sprint_Loop'] ? 'Sprint_Loop' :
                playerCharacterAnimations['Jog_Fwd_Loop'] ? 'Jog_Fwd_Loop' :
                playerCharacterAnimations['Run'] ? 'Run' :
                playerCharacterAnimations['Running'] ? 'Running' :
                playerCharacterAnimations['running'] ? 'running' : 'run'
              ) : null;
            } else {
              targetAnimation = playerCharacterAnimations['Walk_Loop'] || 
                              playerCharacterAnimations['Walk'] || 
                              playerCharacterAnimations['walk'];
              targetAnimationName = targetAnimation ? (
                playerCharacterAnimations['Walk_Loop'] ? 'Walk_Loop' :
                playerCharacterAnimations['Walk'] ? 'Walk' : 'walk'
              ) : null;
            }
          }
        } else {
          if (isMouseCharacter) {
            // Mouse: Use 'idle' animation
            targetAnimation = playerCharacterAnimations['idle'];
            targetAnimationName = targetAnimation ? 'idle' : null;
          } else {
            // Animation Library: Try idle animations
            targetAnimation = playerCharacterAnimations['Idle_Loop'] || 
                            playerCharacterAnimations['Idle'];
            targetAnimationName = targetAnimation ? (
              playerCharacterAnimations['Idle_Loop'] ? 'Idle_Loop' : 'Idle'
            ) : null;
          }
        }
        
        // CRITICAL: Track current animation to prevent unnecessary resets
        if (!window.currentCharacterAnimation) {
          window.currentCharacterAnimation = null;
        }
        
        // CRITICAL: Debounce animation switching to prevent rapid flickering
        // LEVEL 3 OPTIMIZATION: Increased debounce delay and added hysteresis for smoother animation
        const now = performance.now();
        const lastAnimationSwitch = window.lastAnimationSwitchTime || 0;
        
        // CRITICAL: Use centralized settings from PlayerModel module
        // Consistent debounce delay for ALL levels - no level-specific overrides
        // CRITICAL: Settings are now in player-model.js - consistent across ALL levels and BOTH character types
        const minSwitchDelay = playerModelModule ? playerModelModule.getMinSwitchDelay() : 250; // Minimum delay between animation switches
        
        // CRITICAL: Idle transitions should be IMMEDIATE (no debouncing)
        // This ensures the character stops walking immediately when keys are released
        // Support both Mouse ('idle') and Animation Library ('Idle', 'Idle_Loop') formats
        const isSwitchingToIdle = targetAnimationName && (
          targetAnimationName.includes('Idle') || 
          targetAnimationName === 'Idle' || 
          targetAnimationName === 'idle' ||
          targetAnimationName.toLowerCase().includes('idle') ||
          targetAnimationName.toLowerCase() === 'idle'
        );
        
        // Allow immediate switch if going to idle, otherwise use debouncing
        // Hysteresis is already applied in finalIsMoving calculation above (sustained input check)
        const shouldSwitch = window.currentCharacterAnimation !== targetAnimationName && 
                            (isSwitchingToIdle || (now - lastAnimationSwitch) > minSwitchDelay);
        
        // CRITICAL: Disabled debug logging for performance (was causing FPS drops)
        // DEBUG: Log animation decision for troubleshooting - DISABLED FOR PERFORMANCE
        if (false && shouldSwitch && Math.random() < 0.1) { // DISABLED: 10% chance when switching
          console.log("🎬 [CHARACTER] Animation decision:", {
            previous: window.currentCharacterAnimation,
            target: targetAnimationName,
              hasInput: hasMovementInput,
              velocityMagnitude: velocityMagnitude.toFixed(2),
              velocity: { x: playerVelocity.x.toFixed(2), z: playerVelocity.z.toFixed(2) },
              isMoving: finalIsMoving,
              isJumping: isJumping,
              isFalling: isFalling,
              timeSinceLastSwitch: (now - lastAnimationSwitch).toFixed(0) + "ms"
          });
        }
        
        // CRITICAL: Stop all other animations and play target animation
        if (targetAnimation && targetAnimationName) {
          
          Object.keys(playerCharacterAnimations).forEach(animName => {
            const action = playerCharacterAnimations[animName];
            if (!action || typeof action.fadeOut !== 'function') return;
            
            if (animName === targetAnimationName) {
              // This is our target animation
              if (shouldSwitch) {
                // Switching to different animation - reset and play
                const previousAnimation = window.currentCharacterAnimation || 'none';
                
                // CRITICAL: First IMMEDIATELY stop and fade out ALL other animations before starting new one
                // CRITICAL: Use centralized fade times from PlayerModel module
                // Consistent fade times for ALL levels - no level-specific overrides
                // CRITICAL: Settings are now in player-model.js - consistent across ALL levels and BOTH character types
                const fadeTimes = playerModelModule ? playerModelModule.getFadeTimes(isSwitchingToIdle) : {
                  fadeIn: 0.2,
                  fadeOut: isSwitchingToIdle ? 0.1 : 0.2
                };
                const fadeOutTime = fadeTimes.fadeOut; // Use centralized fade time
                Object.keys(playerCharacterAnimations).forEach(otherAnimName => {
                  if (otherAnimName !== targetAnimationName) {
                    const otherAction = playerCharacterAnimations[otherAnimName];
                    if (otherAction && otherAction.enabled && otherAction.getEffectiveWeight() > 0.01) {
                      // For idle transitions, immediately stop walk/sprint animations - Support both formats
                      // Support both Mouse and Animation Library formats
                      const otherAnimNameLower = otherAnimName.toLowerCase();
                      const isClimbAnim = otherAnimNameLower.includes('climb') || otherAnimNameLower.includes('climbing') || otherAnimNameLower.includes('wall');
                      const isWalkOrSprintOther = (isMouseCharacter && (otherAnimName === 'run' || otherAnimName === 'climb')) ||
                                                  (!isMouseCharacter && (isClimbAnim || otherAnimName.includes('Walk') || otherAnimName.includes('walk') || 
                                                                         otherAnimName.includes('Sprint') || otherAnimName.includes('sprint') || 
                                                                         otherAnimName.includes('Run') || otherAnimName.includes('run')));
                      if (isSwitchingToIdle && isWalkOrSprintOther) {
                        otherAction.stop();
                        otherAction.reset();
                        otherAction.setEffectiveWeight(0.0);
                      } else {
                        otherAction.fadeOut(fadeOutTime);
                        // Stop after fade completes if weight is low
                        if (otherAction.getEffectiveWeight() < 0.1) {
                          otherAction.stop();
                          otherAction.reset();
                          otherAction.setEffectiveWeight(0.0);
                        }
                      }
                    }
                  }
                });
                
                // Determine if this is a loop animation (check ONCE) - Support both formats
            // Determine loop behavior - support both Mouse and Animation Library formats
            const isMouseAnimation = isMouseCharacter && (
              targetAnimationName === 'idle' || 
              targetAnimationName === 'run' || 
              targetAnimationName === 'climb'
            );
            const targetAnimNameLowerForLoop = targetAnimationName.toLowerCase();
            const isClimbAnimation = targetAnimNameLowerForLoop.includes('climb') || targetAnimNameLowerForLoop.includes('climbing') || targetAnimNameLowerForLoop.includes('wall');
            const isLoopAnimation = isMouseAnimation || 
                                   isClimbAnimation || // Climb animations should loop (for both Mouse and Animation Library)
                                   targetAnimationName.includes('Loop') || 
                                   targetAnimationName.includes('Idle') || 
                                   targetAnimationName.includes('idle') ||
                                   targetAnimationName.includes('Walk') || 
                                   targetAnimationName.includes('walk') ||
                                   targetAnimationName.includes('Sprint') || 
                                   targetAnimationName.includes('Jog') ||
                                   (targetAnimationName.includes('Run') && !targetAnimationName.includes('Jump')) ||
                                   (targetAnimationName.includes('run') && !targetAnimationName.includes('jump')) ||
                                   (!targetAnimationName.includes('Jump') && !targetAnimationName.includes('jump'));
                
                // Reset and configure NEW animation (only when switching)
                // CRITICAL: Order matters - reset FIRST, then configure, then play
                action.reset(); // Reset to beginning of animation
                
                // Scale animation speed to match ACTUAL movement speed (velocity-based)
                // CRITICAL: Use centralized animation speed calculation from PlayerModel module
                // Consistent calculation for ALL levels - no level-specific overrides
                // CRITICAL: Settings are now in player-model.js - consistent across ALL levels and BOTH character types
                // 🧗 CLIMBING: Climb animation uses constant speed (no velocity scaling)
                let animationSpeed = 1.0;
                const targetAnimNameLower = targetAnimationName.toLowerCase();
                if (targetAnimationName === 'climb' || targetAnimNameLower.includes('climb') || targetAnimNameLower.includes('climbing') || targetAnimNameLower.includes('wall')) {
                  // Climb animation always plays at constant speed (1.0x) - for both Mouse and Animation Library
                  animationSpeed = 1.0;
                } else if (finalIsMoving && !isJumping && !isFalling) {
                  // Use centralized calculation from PlayerModel module
                  if (playerModelModule) {
                    animationSpeed = playerModelModule.calculateAnimationSpeed(
                      velocityMagnitude,
                      isSprinting,
                      godMode,
                      hasMovementInput
                    );
                  } else {
                    // Fallback to default if PlayerModel module not available
                    animationSpeed = 1.0;
                  }
                } else {
                  // Not moving or jumping/falling - use default speed
                  animationSpeed = 1.0;
                }
                action.setEffectiveTimeScale(animationSpeed);
                action.enabled = true; // CRITICAL: Ensure animation is enabled
                
                // CRITICAL: Set loop mode BEFORE playing
                if (isLoopAnimation) {
                  action.setLoop(THREE.LoopRepeat, Infinity);
                  action.clampWhenFinished = false; // Don't clamp at end, loop smoothly
                } else {
                  // Non-loop animations (jump, landing, etc.) play once
                  action.setLoop(THREE.LoopOnce, 1);
                  action.clampWhenFinished = true; // Clamp at end for one-time animations
                }
                
                // Start with HIGHER weight for immediate visibility
                // For idle transitions, use full weight immediately for instant stop
                const initialWeight = isSwitchingToIdle ? 1.0 : 0.8;
                action.setEffectiveWeight(initialWeight); // Start at full weight for idle, 80% for others
                action.play(); // CRITICAL: Start playing
                if (!isSwitchingToIdle) {
                  // Use centralized fade time from PlayerModel module
                  const fadeTimes = playerModelModule ? playerModelModule.getFadeTimes(false) : { fadeIn: 0.2 };
                  action.fadeIn(fadeTimes.fadeIn); // Smooth fade in to full weight (1.0) over fade time (only for non-idle)
                }
                
                // Update current animation tracking and timing
                window.currentCharacterAnimation = targetAnimationName;
                window.lastAnimationSwitchTime = now;
                
                // CRITICAL: Disabled debug logging for performance (was causing FPS drops)
                // Only log when DEBUG_SETTINGS.logCharacterAnimations is true
                if (DEBUG_SETTINGS.logCharacterAnimations) {
                  console.log("🎬 [CHARACTER] Switching to animation:", targetAnimationName, {
                    previous: previousAnimation,
                    enabled: action.enabled,
                    weight: action.getEffectiveWeight(),
                    timeScale: action.getEffectiveTimeScale(),
                    isMoving: finalIsMoving,
                    hasInput: hasMovementInput,
                    isSprinting: isSprinting,
                    loops: isLoopAnimation
                  });
                }
              } else {
                // Same animation - ensure it's still playing and has proper weight
                if (!action.enabled) {
                  action.enabled = true; // CRITICAL: Ensure animation is enabled
                  action.play();
                }
                
                // Update animation speed to match ACTUAL movement speed (velocity-based)
                // CRITICAL: Use centralized animation speed calculation from PlayerModel module
                // Consistent calculation for ALL levels - no level-specific overrides
                // CRITICAL: Settings are now in player-model.js - consistent across ALL levels and BOTH character types
                let animationSpeed = 1.0;
                if (finalIsMoving && !isJumping && !isFalling) {
                  // Use centralized calculation from PlayerModel module
                  if (playerModelModule) {
                    animationSpeed = playerModelModule.calculateAnimationSpeed(
                      velocityMagnitude,
                      isSprinting,
                      godMode,
                      hasMovementInput
                    );
                  } else {
                    // Fallback to default if PlayerModel module not available
                    animationSpeed = 1.0;
                  }
                } else {
                  // Not moving or jumping/falling - use default speed
                  animationSpeed = 1.0;
                }
                action.setEffectiveTimeScale(animationSpeed);
                
                // Ensure animation weight is high enough to be visible
                if (action.getEffectiveWeight() < 0.5) {
                  // Use centralized fade time from PlayerModel module
                  const fadeTimes = playerModelModule ? playerModelModule.getFadeTimes(false) : { fadeIn: 0.1 };
                  action.fadeIn(fadeTimes.fadeIn); // Quick fade in if weight is too low
                }
                
                // Ensure loop animations keep looping - Support both Mouse and Animation Library formats
                const targetAnimNameLowerForLoop = targetAnimationName.toLowerCase();
                const isClimbAnimForLoop = targetAnimNameLowerForLoop.includes('climb') || targetAnimNameLowerForLoop.includes('climbing') || targetAnimNameLowerForLoop.includes('wall');
                const isMouseLoopAnim = isMouseCharacter && (
                  targetAnimationName === 'idle' || 
                  targetAnimationName === 'run' || 
                  targetAnimationName === 'climb'
                );
                const isLoopAnim = isMouseLoopAnim ||
                                  isClimbAnimForLoop || // Climb animations should loop (for both Mouse and Animation Library)
                                  targetAnimationName.includes('Loop') || 
                                  targetAnimationName.includes('Idle') || 
                                  targetAnimationName.includes('idle') ||
                                  targetAnimationName.includes('Walk') || 
                                  targetAnimationName.includes('walk') ||
                                  targetAnimationName.includes('Sprint') || 
                                  targetAnimationName.includes('sprint') ||
                                  targetAnimationName.includes('Run') ||
                                  targetAnimationName.includes('run');
                
                if (isLoopAnim) {
                  action.setLoop(THREE.LoopRepeat, Infinity);
                  action.clampWhenFinished = false;
                  // Ensure it's playing (check enabled and weight > 0)
                  if (!action.enabled || action.getEffectiveWeight() < 0.1) {
                    action.enabled = true;
                    action.play();
                    if (action.getEffectiveWeight() < 0.5) {
                      action.setEffectiveWeight(0.8); // Force higher weight
                    }
                  }
                }
              }
            } else {
              // This is NOT our target animation - IMMEDIATELY fade it out and stop it
              if (action.enabled && action.getEffectiveWeight() > 0.01) {
                // CRITICAL: If switching to idle, IMMEDIATELY stop walk/sprint animations - Support both Mouse and Animation Library formats
                // Mouse: 'run' is the movement animation; Animation Library: 'Walk', 'Sprint', 'Run' variations
                const animNameLower = animName.toLowerCase();
                const isClimbAnim = animNameLower.includes('climb') || animNameLower.includes('climbing') || animNameLower.includes('wall');
                const isWalkOrSprint = (isMouseCharacter && (animName === 'run' || animName === 'climb')) ||
                                      (!isMouseCharacter && (isClimbAnim || animName.includes('Walk') || animName.includes('walk') || 
                                                             animName.includes('Sprint') || animName.includes('sprint') || 
                                                             animName.includes('Run') || animName.includes('run')));
                if (isSwitchingToIdle && isWalkOrSprint) {
                  // Immediate stop for walk animations when going to idle
                  action.stop();
                  action.reset();
                  action.setEffectiveWeight(0.0);
                } else {
                  // Aggressively fade out other non-target animations
                  // Use centralized fade time from PlayerModel module
                  const fadeTimes = playerModelModule ? playerModelModule.getFadeTimes(false) : { fadeOut: 0.15 };
                  action.fadeOut(fadeTimes.fadeOut); // Quick fade out for immediate response
                  // Stop immediately if weight is already low
                  if (action.getEffectiveWeight() < 0.2) {
                    action.stop();
                    action.reset();
                    action.setEffectiveWeight(0.0); // Force weight to 0
                  }
                }
              } else if (action.enabled) {
                // Animation is enabled but weight is already low - stop it completely
                action.stop();
                action.reset();
                action.setEffectiveWeight(0.0);
              }
            }
          });
        } else {
          // No target animation found - log warning
          if (Math.random() < 0.05) { // 5% chance to log
            console.warn("⚠️ [CHARACTER] No suitable animation found for state:", {
              isMoving: finalIsMoving,
              isSprinting: isSprinting,
              availableAnimations: Object.keys(playerCharacterAnimations)
            });
          }
        }
      } catch (animError) {
        console.error("❌ [CHARACTER] Animation error:", animError);
      }
    }
    
    // Show/hide character based on camera mode
    const shouldBeVisible = !isFirstPerson();
    const wasVisible = playerCharacterModel.visible;
    playerCharacterModel.visible = shouldBeVisible;
    playerCharacterModel.userData.visibilityVerified = playerCharacterModel.userData.visibilityVerified ?? false;
    
    // CRITICAL: Only refresh visibility when actually needed (switching from hidden to visible)
    // Don't refresh every frame - this causes flickering in Level 3
    const needsVisibilityRefresh =
      shouldBeVisible && (!playerCharacterModel.userData.visibilityVerified || (!wasVisible && shouldBeVisible));
    
    // FIX: Ensure all child meshes are visible when character should be visible
    // OPTIMIZATION: Only run expensive visibility refresh when actually switching from hidden to visible
    // This prevents flickering in Level 3 caused by constant material updates
    if (needsVisibilityRefresh && (!wasVisible || !playerCharacterModel.userData.visibilityVerified)) {
      let meshCount = 0;
      let visibleMeshCount = 0;
      playerCharacterModel.traverse((child) => {
        if (child.isMesh) {
          meshCount++;
          child.visible = true;
          child.frustumCulled = false; // Disable frustum culling for visibility
          
          // CRITICAL: Set render order ONCE to prevent z-fighting and double rendering
          // Use a consistent render order that's higher than level objects
          if (!child.userData || child.userData.renderOrderSet !== true) {
            child.renderOrder = 100; // Higher render order ensures character renders on top
            if (!child.userData) child.userData = {};
            child.userData.renderOrderSet = true; // Mark as set - don't update again
          }
          
          // CRITICAL: Set shadow settings ONCE during visibility refresh (not every frame)
          // This prevents shadow flickering in Level 3 with multiple shadow-casting lights
          if (!child.userData || !child.userData.shadowSettingsSet) {
            child.castShadow = true;
            child.receiveShadow = true;
            if (!child.userData) child.userData = {};
            child.userData.shadowSettingsSet = true; // Mark as set - don't update again
          }
          
          if (child.visible) visibleMeshCount++;
          
          // CRITICAL: Ensure materials are properly configured for rendering
          if (child.material) {
            const hasMaterialArray = Array.isArray(child.material);
            const materialsToProcess = hasMaterialArray ? child.material : [child.material];
            
            materialsToProcess.forEach((material, idx) => {
              if (material) {
                // CRITICAL: Ensure material is MeshStandardMaterial for proper PBR rendering
                if (!(material instanceof THREE.MeshStandardMaterial)) {
                  console.warn("⚠️ [CHARACTER] Material is not MeshStandardMaterial:", material.type, "for mesh:", child.name);
                  // Convert to MeshStandardMaterial
                  const newMaterial = new THREE.MeshStandardMaterial();
                  if (material.color) newMaterial.color.copy(material.color);
                  if (material.map) newMaterial.map = material.map;
                  if (material.roughness !== undefined) newMaterial.roughness = material.roughness;
                  if (material.metalness !== undefined) newMaterial.metalness = material.metalness;
                  if (material.emissive) newMaterial.emissive.copy(material.emissive);
                  if (material.emissiveIntensity !== undefined) newMaterial.emissiveIntensity = material.emissiveIntensity;
                  
                  if (hasMaterialArray) {
                    child.material[idx] = newMaterial;
                  } else {
                    child.material = newMaterial;
                  }
                  material = newMaterial;
                }
                
                // CRITICAL: Force material properties for rendering (only during visibility refresh)
                // Don't force needsUpdate every frame - this causes flickering in Level 3
                material.transparent = false;
                material.opacity = 1.0;
                material.side = THREE.DoubleSide;
                material.visible = true;
                // Only set needsUpdate if material actually changed (not every frame)
                if (!material.userData || !material.userData.initialized) {
                  material.needsUpdate = true;
                  if (!material.userData) material.userData = {};
                  material.userData.initialized = true; // Mark as initialized
                }
                
                // Ensure textures are loaded if present (only check, don't force update every frame)
                if (material.map && material.map instanceof THREE.Texture) {
                  // Only update texture if it's not loaded yet
                  if (!material.map.image || !material.map.image.complete) {
                    material.map.needsUpdate = true;
                  }
                }
              } else {
                console.warn("⚠️ [CHARACTER] Null material found for mesh:", child.name, "index:", idx);
                // Create default material if null
                const defaultMaterial = new THREE.MeshStandardMaterial({
                  color: 0x888888,
                  side: THREE.DoubleSide,
                  visible: true
                });
                if (hasMaterialArray) {
                  child.material[idx] = defaultMaterial;
                } else {
                  child.material = defaultMaterial;
                }
              }
            });
            
            // Ensure material array is valid
            if (hasMaterialArray && child.material.length === 0) {
              console.error("❌ [CHARACTER] Material array is empty for mesh:", child.name);
              child.material = new THREE.MeshStandardMaterial({ color: 0xff0000, side: THREE.DoubleSide }); // Red for debugging
            }
          } else {
            console.error("❌ [CHARACTER] Mesh has no material:", child.name);
            // Create default material
            child.material = new THREE.MeshStandardMaterial({
              color: 0x00ff00, // Green for debugging
              side: THREE.DoubleSide,
              visible: true
            });
          }
          
          // CRITICAL: Force geometry update
          if (child.geometry) {
            child.geometry.computeBoundingBox();
            child.geometry.computeBoundingSphere();
          }
        }
      });
      
      // CRITICAL: Force matrix update after all transformations (only once during refresh)
      playerCharacterModel.updateMatrixWorld(true);
      
      // Force all meshes to update their matrices (only once during refresh)
      playerCharacterModel.traverse((child) => {
        if (child.isMesh) {
          child.updateMatrix();
          child.updateMatrixWorld(true);
        }
      });
      playerCharacterModel.userData.visibilityVerified = true;
      
      // CRITICAL: Mark that we've done the expensive refresh - don't do it again until visibility changes
      playerCharacterModel.userData.lastVisibilityRefresh = performance.now();
      
      // Debug: Log visibility changes (ALWAYS log when switching from hidden to visible)
      // Also log occasionally when visible to verify materials are rendering
      const shouldLog = DEBUG_SETTINGS.logVisibilityUpdates &&
        ((!wasVisible && shouldBeVisible) || (shouldBeVisible && Math.random() < 0.02));
      
      if (shouldLog) {
        const box = new THREE.Box3().setFromObject(playerCharacterModel);
        const size = box.getSize(new THREE.Vector3());
        
        // Get mesh details
        const meshDetails = [];
        playerCharacterModel.traverse((child) => {
          if (child.isMesh) {
            const hasMaterialArray = Array.isArray(child.material);
            const materialsToProcess = hasMaterialArray ? child.material : [child.material];
            const materialInfo = materialsToProcess.map((mat, idx) => ({
              index: idx,
              type: mat ? mat.type : 'null',
              visible: mat ? mat.visible !== false : false,
              transparent: mat ? mat.transparent : false,
              opacity: mat ? mat.opacity : 1.0,
              color: mat && mat.color ? mat.color.getHexString() : 'none',
              emissive: mat && mat.emissive ? mat.emissive.getHexString() : 'none',
              emissiveIntensity: mat ? mat.emissiveIntensity : 0,
              needsUpdate: mat ? mat.needsUpdate : false,
              side: mat ? mat.side : 'none'
            }));
            
            meshDetails.push({
              name: child.name || 'unnamed',
              visible: child.visible,
              frustumCulled: child.frustumCulled,
              renderOrder: child.renderOrder,
              position: {
                x: child.position.x.toFixed(2),
                y: child.position.y.toFixed(2),
                z: child.position.z.toFixed(2)
              },
              scale: {
                x: child.scale.x.toFixed(2),
                y: child.scale.y.toFixed(2),
                z: child.scale.z.toFixed(2)
              },
              materials: materialInfo,
              geometry: child.geometry ? {
                vertexCount: child.geometry.attributes.position ? child.geometry.attributes.position.count : 0,
                hasBoundingBox: !!child.geometry.boundingBox,
                hasBoundingSphere: !!child.geometry.boundingSphere
              } : null
            });
          }
        });
        
        // Check camera position relative to character
        const cameraToCharacter = new THREE.Vector3().subVectors(camera.position, playerCharacterModel.position);
        const distanceToCamera = cameraToCharacter.length();
        
        console.log("🎭 [CHARACTER] Visibility updated:", {
          shouldBeVisible: shouldBeVisible,
          wasVisible: wasVisible,
          modelVisible: playerCharacterModel.visible,
          meshCount: meshCount,
          visibleMeshCount: visibleMeshCount,
          position: {
            x: playerCharacterModel.position.x.toFixed(2),
            y: playerCharacterModel.position.y.toFixed(2),
            z: playerCharacterModel.position.z.toFixed(2)
          },
          scale: {
            x: playerCharacterModel.scale.x.toFixed(2),
            y: playerCharacterModel.scale.y.toFixed(2),
            z: playerCharacterModel.scale.z.toFixed(2)
          },
          boundingBoxSize: {
            x: size.x.toFixed(2),
            y: size.y.toFixed(2),
            z: size.z.toFixed(2)
          },
          inScene: scene.children.includes(playerCharacterModel),
          cameraMode: cameraMode,
          isFirstPerson: isFirstPerson(),
          isThirdPerson: isThirdPerson(),
          cameraPosition: {
            x: camera.position.x.toFixed(2),
            y: camera.position.y.toFixed(2),
            z: camera.position.z.toFixed(2)
          },
          distanceToCamera: distanceToCamera.toFixed(2),
          meshDetails: meshDetails
        });
      }
      
      // CRITICAL: Ensure character is in scene ONLY ONCE (not duplicated)
      // LEVEL 3 SPECIFIC: More aggressive checks to prevent double rendering
      const characterInScene = scene.children.includes(playerCharacterModel);
      const characterInLevel3Group = level3State.group && level3State.group.children.includes(playerCharacterModel);
      
      // CRITICAL: Character should NEVER be in level3State.group - it should only be in scene root
      // LEVEL 3 SPECIFIC: Check and remove immediately if found
      if (characterInLevel3Group) {
        console.warn("⚠️ [CHARACTER] Character found in level3State.group! Removing it...");
        level3State.group.remove(playerCharacterModel);
      }
      
      // CRITICAL: Check if character appears multiple times in scene (duplicate detection)
      // LEVEL 3 SPECIFIC: Count occurrences to detect duplicates
      const characterOccurrences = scene.children.filter(child => child === playerCharacterModel).length;
      if (characterOccurrences > 1) {
        console.warn(`⚠️ [CHARACTER] Character found ${characterOccurrences} times in scene! Removing duplicates...`);
        // Remove all occurrences
        while (scene.children.includes(playerCharacterModel)) {
          scene.remove(playerCharacterModel);
        }
        // Re-add once
        scene.add(playerCharacterModel);
      }
      
      // Ensure character is in scene root (not in any level group)
      if (!characterInScene || characterOccurrences === 0) {
        console.warn("⚠️ [CHARACTER] Character not in scene! Adding it now...");
        scene.add(playerCharacterModel);
      }
      
      // CRITICAL: Force render update (only during visibility refresh, not every frame)
      // This prevents flickering in Level 3
      // Only update matrix once during refresh, not every frame
      // Use force=false to prevent unnecessary matrix recalculations
      playerCharacterModel.updateMatrixWorld(false); // false = only update if needed
      
      // CRITICAL: Ensure character is NOT in any level group (prevents double rendering)
      // LEVEL 3 SPECIFIC: More aggressive removal from all level groups
      if (level1State && level1State.group && level1State.group.children.includes(playerCharacterModel)) {
        level1State.group.remove(playerCharacterModel);
      }
      if (level2State && level2State.group && level2State.group.children.includes(playerCharacterModel)) {
        level2State.group.remove(playerCharacterModel);
      }
      if (level3State && level3State.group && level3State.group.children.includes(playerCharacterModel)) {
        level3State.group.remove(playerCharacterModel);
      }
      if (level4State && level4State.group && level4State.group.children.includes(playerCharacterModel)) {
        level4State.group.remove(playerCharacterModel);
      }
      if (level5State && level5State.group && level5State.group.children.includes(playerCharacterModel)) {
        level5State.group.remove(playerCharacterModel);
      }
      
      // DEBUG: Hide debug sphere now that character is visible (or keep it hidden)
      if (window.characterPositionDebugSphere) {
        window.characterPositionDebugSphere.visible = false; // Hide debug sphere - character is visible
      }
      
      // DEBUG: Simple log when visible (only occasionally to avoid spam)
      if (DEBUG_SETTINGS.logVisibilityUpdates && Math.random() < 0.01) {
        console.log("🎭 [CHARACTER] Character is VISIBLE in 3rd person:", {
          visible: playerCharacterModel.visible,
          inScene: scene.children.includes(playerCharacterModel),
          meshCount: meshCount,
          cameraMode: cameraMode,
          debugSphereVisible: window.characterPositionDebugSphere ? window.characterPositionDebugSphere.visible : false
        });
      }
    } else if (!shouldBeVisible && playerCharacterModel.userData.visibilityVerified) {
      // In first person, hide all meshes once when switching back
      playerCharacterModel.traverse((child) => {
        if (child.isMesh) {
          child.visible = false;
        }
      });
      playerCharacterModel.userData.visibilityVerified = false;
      if (DEBUG_SETTINGS.logVisibilityUpdates) {
        console.log("🎭 [CHARACTER] Character hidden (first-person view).", {
          visible: shouldBeVisible,
          cameraMode,
          debugSphereVisible: window.characterPositionDebugSphere ? window.characterPositionDebugSphere.visible : false
        });
      }
    }
    
    // Hide simple playerModel when GLTF character is active
    if (playerModel && useGLTFCharacter) {
      playerModel.visible = false;
    }
  } catch (error) {
    console.error("❌ [CHARACTER] Error updating player character:", error);
    useGLTFCharacter = false;
    if (playerModel) {
      playerModel.visible = !isFirstPerson();
    }
  }
}

// Load NPC character model (for NPCs, enemies, etc.)
async function loadNPCCharacter(modelPath, position, scale = 1.0) {
  try {
    console.log("👤 [NPC] Loading NPC character model:", modelPath);
    const gltf = await loadModel(modelPath);
    
    // Clone the scene for the NPC
    const npcModel = gltf.scene.clone(true);
    
    // Set up NPC model properties
    npcModel.traverse((child) => {
      if (child.isMesh) {
        child.castShadow = true;
        child.receiveShadow = true;
        child.frustumCulled = true;
      }
    });
    
    // Scale NPC
    npcModel.scale.set(scale, scale, scale);
    
    // Position NPC
    npcModel.position.copy(position);
    
    // Add NPC to scene
    scene.add(npcModel);
    
    // Set up animations if available
    let npcMixer = null;
    if (gltf.animations && gltf.animations.length > 0) {
      npcMixer = new THREE.AnimationMixer(npcModel);
      const action = npcMixer.clipAction(gltf.animations[0]);
      action.play();
    }
    
    console.log("✅ [NPC] NPC character model loaded and added to scene:", modelPath);
    
    return {
      model: npcModel,
      mixer: npcMixer,
      animations: gltf.animations || []
    };
    
  } catch (error) {
    console.error("❌ [NPC] Error loading NPC character model:", error);
    return null;
  }
}

