function toggleShadowCameraHelper(show) {
  if (!skySystem || !skySystem.skybox || !skySystem.skybox.sun) {
    console.warn("⚠️ [DEBUG] Cannot enable shadow camera helper - sky system or sun not available");
    return;
  }
  
  if (show && !shadowCameraHelper) {
    // Create shadow camera helper for the sun's shadow camera (January 4, 2026)
    const shadowCamera = skySystem.skybox.sun.shadow.camera;
    
    // Ensure shadow camera is properly configured for helper visualization
    // CameraHelper automatically shows the frustum for OrthographicCamera
    shadowCameraHelper = new THREE.CameraHelper(shadowCamera);
    shadowCameraHelper.frustumCulled = false; // Disable frustum culling to ensure visibility
    shadowCameraHelper.visible = true; // CRITICAL: Ensure helper is visible (January 4, 2026)
    
    // Ensure shadow camera matrices are updated before creating helper
    shadowCamera.updateMatrixWorld(true); // Force update from root
    shadowCamera.updateProjectionMatrix(); // Ensure projection matrix is updated
    
    scene.add(shadowCameraHelper);
    console.log("✅ [DEBUG] Shadow camera helper enabled");
    console.log("   Shadow camera type:", shadowCamera.type);
    console.log("   Shadow camera frustum:", {
      left: shadowCamera.left,
      right: shadowCamera.right,
      top: shadowCamera.top,
      bottom: shadowCamera.bottom,
      near: shadowCamera.near,
      far: shadowCamera.far,
      zoom: shadowCamera.zoom
    });
    console.log("   Scene children count:", scene.children.length, "Helper in scene:", scene.children.includes(shadowCameraHelper));
  } else if (!show && shadowCameraHelper) {
    scene.remove(shadowCameraHelper);
    if (shadowCameraHelper.dispose) shadowCameraHelper.dispose();
    shadowCameraHelper = null;
    console.log("✅ [DEBUG] Shadow camera helper disabled");
  } else if (show && shadowCameraHelper) {
    // Update helper if it exists - this is called every frame
    // The helper automatically updates its visualization based on the camera's current matrix
    shadowCameraHelper.update();
  }
}

/**
 * Initialize/Refresh shadow camera helper at level start (January 4, 2026)
 * This ensures the shadow camera helper is properly set up when warping to a level
 * Called after level environment is applied to ensure sky system is ready
 * 
 * CRITICAL: Recreates the helper entirely (dispose and create new) to ensure it works correctly.
 * Simply refreshing doesn't work - we need a fresh CameraHelper instance with the current camera state.
 * This matches the behavior of manually toggling the checkbox off and on, which the user reported works.
 */
function initializeShadowCameraHelperAtLevelStart() {
  // Check if shadow camera helper checkbox is checked
  const shadowCameraCheckbox = document.getElementById('debugShadowCamera');
  if (!shadowCameraCheckbox || !shadowCameraCheckbox.checked) {
    // Checkbox not checked, nothing to do
    return;
  }
  
  // Check if sky system and sun are available
  if (!skySystem || !skySystem.skybox || !skySystem.skybox.sun) {
    // Sky system not ready yet, skip initialization
    console.warn("⚠️ [DEBUG] Cannot initialize shadow camera helper - sky system not ready");
    return;
  }
  
  // CRITICAL: Recreate the helper entirely (dispose and create new) to ensure it works correctly
  // Simply refreshing doesn't work - we need a fresh CameraHelper instance with the current camera state
  // This matches the behavior of manually toggling the checkbox off and on, which works correctly
  if (shadowCameraHelper) {
    // Remove from scene and dispose
    scene.remove(shadowCameraHelper);
    if (shadowCameraHelper.dispose) {
      shadowCameraHelper.dispose();
    }
    shadowCameraHelper = null;
    
    console.log("🗑️ [DEBUG] Shadow camera helper disposed for recreation");
  }
  
  // Create new helper with fresh camera reference
  // This ensures the helper has the current camera state and will update correctly
  const shadowCamera = skySystem.skybox.sun.shadow.camera;
  
  // Ensure shadow camera matrices are updated before creating helper
  skySystem.skybox.sun.updateMatrixWorld(true);
  shadowCamera.updateMatrixWorld(true);
  shadowCamera.updateProjectionMatrix();
  
  // Create new helper
  shadowCameraHelper = new THREE.CameraHelper(shadowCamera);
  shadowCameraHelper.frustumCulled = false;
  shadowCameraHelper.visible = true;
  scene.add(shadowCameraHelper);
  
  console.log("✅ [DEBUG] Shadow camera helper recreated at level start");
}

// Helper function to get level center coordinates (January 4, 2026)
function getLevelCenter(levelId) {
  if (!levelId) levelId = currentLevel;
  
  switch (levelId) {
    case LEVEL_IDS.LEVEL1:
      // Level 1: 120x120 field centered around (60, 0, 60)
      return new THREE.Vector3(60, 1, 60);
    case LEVEL_IDS.LEVEL2:
      // Level 2: origin at (0, 0, 600), size 60
      return new THREE.Vector3(level2Config.origin.x, 1, level2Config.origin.z);
    case LEVEL_IDS.LEVEL3:
      // Level 3: origin at (0, 0, 800), size 160
      return new THREE.Vector3(level3Config.origin.x, 1, level3Config.origin.z);
    case LEVEL_IDS.LEVEL4:
      // Level 4: origin at (0, 0, 1000), size 160
      return new THREE.Vector3(level4Config.origin.x, 1, level4Config.origin.z);
    case LEVEL_IDS.LEVEL5:
      // Level 5: Large map centered at origin (0, 0, 0)
      return new THREE.Vector3(0, 1, 0);
    case LEVEL_IDS.LEVEL6:
      // Level 6: Arena at origin (0, 0, 0), size 200
      return new THREE.Vector3(0, 1, 0);
    default:
      return new THREE.Vector3(0, 1, 0);
  }
}

function toggleWorldAxesHelper(show) {
  if (show && !worldAxesHelper) {
    // Get current level center
    const levelCenter = getLevelCenter(currentLevel);
    
    // Create world axes helper at level center - larger size for visibility
    worldAxesHelper = new THREE.AxesHelper(50); // 50 units length
    worldAxesHelper.position.copy(levelCenter);
    worldAxesHelper.frustumCulled = false; // Disable frustum culling to ensure visibility
    scene.add(worldAxesHelper);
    console.log(`✅ [DEBUG] World axes helper enabled at level center (${levelCenter.x}, ${levelCenter.y}, ${levelCenter.z}), size: 50 units, level: ${currentLevel}`);
    console.log("   Scene children count:", scene.children.length, "Helper in scene:", scene.children.includes(worldAxesHelper));
  } else if (!show && worldAxesHelper) {
    scene.remove(worldAxesHelper);
    if (worldAxesHelper.dispose) worldAxesHelper.dispose();
    worldAxesHelper = null;
    console.log("✅ [DEBUG] World axes helper disabled");
  } else if (show && worldAxesHelper) {
    // Update position if level changed
    const levelCenter = getLevelCenter(currentLevel);
    worldAxesHelper.position.copy(levelCenter);
    console.log(`✅ [DEBUG] World axes helper position updated to level center (${levelCenter.x}, ${levelCenter.y}, ${levelCenter.z})`);
  }
}

function togglePlayerAxesHelper(show) {
  if (show && !playerAxesHelper) {
    // Get player position when debug option is turned on (January 4, 2026)
    let playerPosition = new THREE.Vector3(0, 1, 0); // Default position
    
    if (camera && camera.position) {
      // Use camera position (most accurate for player position)
      playerPosition.copy(camera.position);
    } else if (playerCollider && playerCollider.start && playerCollider.end) {
      // Fallback to player collider center
      playerPosition.lerpVectors(playerCollider.start, playerCollider.end, 0.5);
    }
    
    // Create player axes helper at captured player position (does NOT update every frame)
    playerAxesHelper = new THREE.AxesHelper(5); // 5 units length
    playerAxesHelper.position.copy(playerPosition);
    playerAxesHelper.frustumCulled = false; // Disable frustum culling to ensure visibility
    scene.add(playerAxesHelper);
    console.log(`✅ [DEBUG] Player axes helper enabled at captured position (${playerPosition.x.toFixed(2)}, ${playerPosition.y.toFixed(2)}, ${playerPosition.z.toFixed(2)}), size: 5 units`);
    console.log("   Scene children count:", scene.children.length, "Helper in scene:", scene.children.includes(playerAxesHelper));
  } else if (!show && playerAxesHelper) {
    scene.remove(playerAxesHelper);
    if (playerAxesHelper.dispose) playerAxesHelper.dispose();
    playerAxesHelper = null;
    console.log("✅ [DEBUG] Player axes helper disabled");
  }
}

