    saveTimeButton.addEventListener("mouseleave", () => {
      saveTimeButton.style.background = "rgba(255, 224, 102, 0.15)";
      saveTimeButton.style.borderColor = "rgba(255, 224, 102, 0.5)";
      saveTimeButton.style.transform = "scale(1)";
    });

    saveTimeButton.addEventListener("click", () => {
      // Check if currentLevel exists
      if (!currentLevel) {
        console.error("❌ [SKY] Cannot save: currentLevel is not set.");
        saveTimeButton.textContent = "❌ Level Not Set";
        setTimeout(() => {
          saveTimeButton.textContent = "💾 Save Time for Level";
        }, 2000);
        return;
      }

      // Get values from UI controls instead of skySystem object
      // This way we can save even if skySystem isn't initialized yet
      const hourSlider = document.getElementById("skyHourSlider");
      const minuteSlider = document.getElementById("skyMinuteSlider");
      const timeOfDaySelect = document.getElementById("skyTimeOfDaySelect");
      const cloudDensitySlider = document.getElementById("skyCloudDensitySlider");
      const starCountSlider = document.getElementById("skyStarCountSlider");
      
      // Verify controls exist
      if (!hourSlider || !minuteSlider || !timeOfDaySelect) {
        console.error("❌ [SKY] Cannot save: UI controls not found. Controls:", {
          hourSlider: !!hourSlider,
          minuteSlider: !!minuteSlider,
          timeOfDaySelect: !!timeOfDaySelect
        });
        saveTimeButton.textContent = "❌ Controls Not Found";
        setTimeout(() => {
          saveTimeButton.textContent = "💾 Save Time for Level";
        }, 2000);
        return;
      }
      
      const hour = parseInt(hourSlider.value) || 12;
      const minute = parseInt(minuteSlider.value) || 0;
      const timeOfDay = timeOfDaySelect.value || "day";
      const cloudDensity = cloudDensitySlider ? parseFloat(cloudDensitySlider.value) || 0.7 : 0.7;
      const starCount = starCountSlider ? parseInt(starCountSlider.value) || 1500 : 1500;
      
      // Get lensflare state - check if skySystem exists first
      let lensflareEnabled = true; // Default
      if (skySystem && skySystem.skybox && skySystem.skybox.lensflare) {
        lensflareEnabled = skySystem.skybox.lensflare.visible;
      }
      
      // Get enableDayNight - check if skySystem exists first
      let enableDayNight = true; // Default
      if (skySystem && skySystem.options) {
        enableDayNight = skySystem.options.enableDayNight !== false;
      }
      
      // Build saved settings from UI values
      const savedSettings = {
        hour: hour,
        minute: minute,
        timeOfDay: timeOfDay,
        enableDayNight: enableDayNight,
        cloudDensity: cloudDensity,
        starCount: starCount,
        enableLensflare: lensflareEnabled,
        timeSpeedMultiplier: skySystem ? skySystem.options.timeSpeedMultiplier : 1.0,
        savedAt: new Date().toISOString(),
        savedFrom: window.location.hostname // Add hostname to verify domain
      };
      
      // Normalize levelId to uppercase for consistent keys (LEVEL1, LEVEL2, etc.)
      const normalizedLevelId = currentLevel ? currentLevel.toUpperCase() : currentLevel;
      
      // Also update skySystem if it exists (for immediate effect)
      if (skySystem) {
        skySystem.setTime(hour, minute);
        if (timeOfDay) {
          skySystem.setTimeOfDay(timeOfDay);
        }
        if (cloudDensity !== undefined) {
          skySystem.setCloudDensity(cloudDensity);
        }
        if (starCount !== undefined) {
          skySystem.setStarCount(starCount);
        }
        console.log("🌌 [SKY] Updated skySystem with saved time:", { hour, minute, timeOfDay, cloudDensity, starCount });
      } else {
        console.warn("⚠️ [SKY] skySystem is null - settings saved but not applied. Will apply on next level load.");
      }

      // Save to localStorage with normalized level key
      const storageKey = `sky_settings_${normalizedLevelId}`;
      try {
        // Check if localStorage is available
        if (typeof Storage === 'undefined' || !window.localStorage) {
          console.error(`❌ [SKY] localStorage not available (production/private mode?) - Cannot save settings`);
          saveTimeButton.textContent = "❌ localStorage Not Available";
          setTimeout(() => {
            saveTimeButton.textContent = "💾 Save Time for Level";
          }, 2000);
          return;
        }
        
        localStorage.setItem(storageKey, JSON.stringify(savedSettings));
        console.log(`💾 [SKY] Saved sky settings for ${normalizedLevelId} (key: ${storageKey}):`, savedSettings);
        
        // Show visual feedback
        const originalText = saveTimeButton.textContent;
        saveTimeButton.textContent = "✅ Saved!";
        saveTimeButton.style.background = "rgba(34, 197, 94, 0.3)";
        saveTimeButton.style.borderColor = "rgba(34, 197, 94, 0.8)";
        saveTimeButton.style.color = "#22c55e";
        
        setTimeout(() => {
          saveTimeButton.textContent = originalText;
          saveTimeButton.style.background = "rgba(255, 224, 102, 0.15)";
          saveTimeButton.style.borderColor = "rgba(255, 224, 102, 0.5)";
          saveTimeButton.style.color = "#ffe066";
        }, 2000);
      } catch (e) {
        console.error("❌ [SKY] Failed to save sky settings:", e);
        saveTimeButton.textContent = "❌ Save Failed";
        setTimeout(() => {
          saveTimeButton.textContent = "💾 Save Time for Level";
        }, 2000);
      }
    });

    saveTimeContainer.appendChild(saveTimeButton);
    skySystemContent.appendChild(saveTimeContainer);
