    // Helper function to update ground controls visibility based on ground type
    function updateGroundControlsVisibility(groundType) {
      const bladeCountContainer = document.getElementById("bladeCountContainer");
      const chunkedGrassContainer = document.getElementById("chunkedGrassContainer");
      const bladeLengthContainer = document.getElementById("bladeLengthContainer"); // NEW: Blade length container
      const windSpeedContainer = document.getElementById("windSpeedContainer");
      const windStrengthContainer = document.getElementById("windStrengthContainer");
      const groundColorContainer = document.getElementById("groundColorContainer");
      const undergroundTypeContainer = document.getElementById("undergroundTypeContainer");
      const undergroundColorContainer = document.getElementById("undergroundColorContainer");
      const undergroundTextureContainer = document.getElementById("undergroundTextureContainer");
      
      if (groundType === "grass") {
        if (bladeCountContainer) bladeCountContainer.style.display = "flex";
        if (chunkedGrassContainer) chunkedGrassContainer.style.display = "flex"; // PHASE 2: Show chunked grass toggle
        if (bladeLengthContainer) bladeLengthContainer.style.display = "flex";
        if (windSpeedContainer) windSpeedContainer.style.display = "flex";
        if (windStrengthContainer) windStrengthContainer.style.display = "flex";
        const windDirectionContainer = document.getElementById("windDirectionContainer");
        if (windDirectionContainer) windDirectionContainer.style.display = "flex";
        if (groundColorContainer) groundColorContainer.style.display = "none";
        if (undergroundTypeContainer) undergroundTypeContainer.style.display = "block";
        // Underground type controls are shown; visibility of color/texture depends on selection
        if (undergroundTypeContainer) {
          const typeSelect = document.getElementById("groundUndergroundType");
          const type = typeSelect ? typeSelect.value : "color";
          if (undergroundColorContainer) undergroundColorContainer.style.display = type === "color" ? "block" : "none";
          if (undergroundTextureContainer) undergroundTextureContainer.style.display = type === "texture" ? "block" : "none";
        }
      } else if (groundType === "color") {
        if (bladeCountContainer) bladeCountContainer.style.display = "none";
        if (chunkedGrassContainer) chunkedGrassContainer.style.display = "none"; // PHASE 2: Hide chunked grass toggle
        if (bladeLengthContainer) bladeLengthContainer.style.display = "none";
        if (windSpeedContainer) windSpeedContainer.style.display = "none";
        if (windStrengthContainer) windStrengthContainer.style.display = "none";
        const windDirectionContainer = document.getElementById("windDirectionContainer");
        if (windDirectionContainer) windDirectionContainer.style.display = "none";
        const windTurbulenceContainer = document.getElementById("windTurbulenceContainer");
        if (windTurbulenceContainer) windTurbulenceContainer.style.display = "none";
        const windGustFrequencyContainer = document.getElementById("windGustFrequencyContainer");
        if (windGustFrequencyContainer) windGustFrequencyContainer.style.display = "none";
        const windGustIntensityContainer = document.getElementById("windGustIntensityContainer");
        if (windGustIntensityContainer) windGustIntensityContainer.style.display = "none";
        if (groundColorContainer) groundColorContainer.style.display = "flex";
        if (undergroundTypeContainer) undergroundTypeContainer.style.display = "none";
        if (undergroundColorContainer) undergroundColorContainer.style.display = "none";
        if (undergroundTextureContainer) undergroundTextureContainer.style.display = "none";
      } else { // blank
        if (bladeCountContainer) bladeCountContainer.style.display = "none";
        if (chunkedGrassContainer) chunkedGrassContainer.style.display = "none"; // PHASE 2: Hide chunked grass toggle
        if (bladeLengthContainer) bladeLengthContainer.style.display = "none"; // Hide blade length for blank
        if (windSpeedContainer) windSpeedContainer.style.display = "none";
        if (windStrengthContainer) windStrengthContainer.style.display = "none";
        const windDirectionContainer = document.getElementById("windDirectionContainer"); // NEW: Get wind direction container
        if (windDirectionContainer) windDirectionContainer.style.display = "none"; // NEW: Hide wind direction for blank
        if (groundColorContainer) groundColorContainer.style.display = "none";
        if (undergroundTypeContainer) undergroundTypeContainer.style.display = "none";
        if (undergroundColorContainer) undergroundColorContainer.style.display = "none";
        if (undergroundTextureContainer) undergroundTextureContainer.style.display = "none";
      }
    }
    
    // Store function for later use
    optionsMenu._updateGroundControlsVisibility = updateGroundControlsVisibility;

    // Initialize ground controls with current settings
    const groundTypeSelectEl = document.getElementById("groundTypeSelect");
    const bladeCountSliderEl = document.getElementById("groundBladeCountSlider");
    const bladeCountValueEl = document.getElementById("groundBladeCountValue");
    const bladeLengthSliderEl = document.getElementById("groundBladeLengthSlider");
    const bladeLengthValueEl = document.getElementById("groundBladeLengthValue");
    const windSpeedSliderEl = document.getElementById("groundWindSpeedSlider");
    const windSpeedValueEl = document.getElementById("groundWindSpeedValue");
    const windStrengthSliderEl = document.getElementById("groundWindStrengthSlider");
    const windStrengthValueEl = document.getElementById("groundWindStrengthValue");
    const windDirectionSliderEl = document.getElementById("groundWindDirectionSlider");
    const windDirectionValueEl = document.getElementById("groundWindDirectionValue");
    const windTurbulenceSliderEl = document.getElementById("groundWindTurbulenceSlider"); // NEW: Wind turbulence slider
    const windTurbulenceValueEl = document.getElementById("groundWindTurbulenceValue"); // NEW: Wind turbulence value
    const windGustFrequencySliderEl = document.getElementById("groundWindGustFrequencySlider"); // NEW: Wind gust frequency slider
    const windGustFrequencyValueEl = document.getElementById("groundWindGustFrequencyValue"); // NEW: Wind gust frequency value
    const windGustIntensitySliderEl = document.getElementById("groundWindGustIntensitySlider"); // NEW: Wind gust intensity slider
    const windGustIntensityValueEl = document.getElementById("groundWindGustIntensityValue"); // NEW: Wind gust intensity value
    const undergroundTypeSelectEl = document.getElementById("groundUndergroundType");
    const undergroundColorInputEl = document.getElementById("groundUndergroundColor");
    const undergroundTextureInputEl = document.getElementById("groundUndergroundTexturePath");

    const currentGroundSettings = getGroundConfigForLevel(currentLevel || LEVEL_IDS.LEVEL1);
    if (currentGroundSettings) {
      if (groundTypeSelectEl) groundTypeSelectEl.value = currentGroundSettings.groundType || "grass";
      if (bladeCountSliderEl && currentGroundSettings.bladeCount !== undefined) {
        bladeCountSliderEl.value = currentGroundSettings.bladeCount;
        if (bladeCountValueEl) bladeCountValueEl.textContent = currentGroundSettings.bladeCount.toLocaleString();
      }
      // NEW: Initialize blade length slider
      if (bladeLengthSliderEl) {
        const bladeLengthMultiplier = currentGroundSettings.bladeLengthMultiplier !== undefined ? currentGroundSettings.bladeLengthMultiplier : 1.0;
        bladeLengthSliderEl.value = bladeLengthMultiplier;
        if (bladeLengthValueEl) bladeLengthValueEl.textContent = bladeLengthMultiplier.toFixed(1) + "x";
        // Apply to grass system if it exists
        if (grassSystem) {
          grassSystem.setBladeLength(bladeLengthMultiplier);
        }
      }
      if (windSpeedSliderEl && currentGroundSettings.windSpeed !== undefined) {
        windSpeedSliderEl.value = currentGroundSettings.windSpeed;
        if (windSpeedValueEl) windSpeedValueEl.textContent = parseFloat(currentGroundSettings.windSpeed).toFixed(1);
      }
      if (windStrengthSliderEl && currentGroundSettings.windStrength !== undefined) {
        windStrengthSliderEl.value = currentGroundSettings.windStrength;
        if (windStrengthValueEl) windStrengthValueEl.textContent = parseFloat(currentGroundSettings.windStrength).toFixed(2);
      }
      // Initialize wind direction slider
      if (windDirectionSliderEl) {
        const windDirectionAngle = currentGroundSettings.windDirectionAngle !== undefined ? currentGroundSettings.windDirectionAngle : 0.0;
        windDirectionSliderEl.value = windDirectionAngle;
        if (windDirectionValueEl) windDirectionValueEl.textContent = Math.round(windDirectionAngle) + "°";
        if (grassSystem) {
          grassSystem.setWindDirection(windDirectionAngle);
        }
      }
      // NEW: Initialize wind turbulence slider
      if (windTurbulenceSliderEl) {
        const windTurbulence = currentGroundSettings.windTurbulence !== undefined ? currentGroundSettings.windTurbulence : 0.2;
        windTurbulenceSliderEl.value = windTurbulence;
        if (windTurbulenceValueEl) windTurbulenceValueEl.textContent = windTurbulence.toFixed(2);
        if (grassSystem) {
          grassSystem.setWindTurbulence(windTurbulence);
        }
      }
      // NEW: Initialize wind gust frequency slider
      if (windGustFrequencySliderEl) {
        const windGustFrequency = currentGroundSettings.windGustFrequency !== undefined ? currentGroundSettings.windGustFrequency : 0.5;
        windGustFrequencySliderEl.value = windGustFrequency;
        if (windGustFrequencyValueEl) windGustFrequencyValueEl.textContent = windGustFrequency.toFixed(1) + "/s";
        if (grassSystem) {
          grassSystem.setWindGustFrequency(windGustFrequency);
        }
      }
      // NEW: Initialize wind gust intensity slider
      if (windGustIntensitySliderEl) {
        const windGustIntensity = currentGroundSettings.windGustIntensity !== undefined ? currentGroundSettings.windGustIntensity : 1.5;
        windGustIntensitySliderEl.value = windGustIntensity;
        if (windGustIntensityValueEl) windGustIntensityValueEl.textContent = windGustIntensity.toFixed(1) + "x";
        if (grassSystem) {
          grassSystem.setWindGustIntensity(windGustIntensity);
        }
      }
      if (undergroundTypeSelectEl && currentGroundSettings.undergroundType) {
        undergroundTypeSelectEl.value = currentGroundSettings.undergroundType;
      }
      if (undergroundColorInputEl && currentGroundSettings.undergroundColor !== undefined) {
        undergroundColorInputEl.value = toHex(currentGroundSettings.undergroundColor);
      }
      if (undergroundTextureInputEl && currentGroundSettings.undergroundTexturePath) {
        undergroundTextureInputEl.value = currentGroundSettings.undergroundTexturePath;
      }
      updateGroundControlsVisibility(currentGroundSettings.groundType || "grass");
    }

