function awardCheesePoints() {
  playerScore += 1;
  updateCheeseHud(playerScore);

  const discordId = resolvedDiscordId;

  if (!discordId) {
    if (!cheeseHudWarnedNoId) {
      console.warn("Cheese hunt capture skipped — discord_id not found (user not logged in).");
      cheeseHudWarnedNoId = true;
    }
    debugState.lastResponse = { success: false, error: "missing_discord_id" };
    refreshDebugOverlay();
    return;
  }

  const payload = {
    discord_id: discordId,
    discord_name: playerDisplayName && playerDisplayName !== "Guest" ? playerDisplayName : null,
    level_id: floatingCheese?.levelId || "CHEESE_TEMPLE_LVL1",
    base_reward: 50,
    session_id: cheeseSessionId,
    capture_index: playerScore,
    cooldown_seconds: 1
  };

  queueCheeseCapture(payload);
}

function buildLevel(mapData) {
  // Store map size globally for climb border detection
  if (mapData.size) {
    currentMapSize = mapData.size;
    const halfMapSize = currentMapSize / 2;
    const borderExclusionZone = 3.0;
    const safePlayArea = halfMapSize - borderExclusionZone;
    console.log("🗺️ [LEVEL] Map size set to:", currentMapSize, {
      halfMapSize: halfMapSize.toFixed(2),
      borderExclusionZone: borderExclusionZone,
      safePlayArea: safePlayArea.toFixed(2),
      climbableArea: `±${safePlayArea.toFixed(2)} units from center`
    });
  }
  
  const blockSize = 1;
  const renderGeometry = new THREE.BoxGeometry(blockSize, blockSize, blockSize);
  const baseCollisionGeometry = new THREE.BoxGeometry(blockSize, blockSize, blockSize).toNonIndexed();
  const basePositions = baseCollisionGeometry.attributes.position.array;
  const baseNormals = baseCollisionGeometry.attributes.normal?.array || null;
  const positionsPerBlock = basePositions.length;
  const normalsPerBlock = baseNormals ? baseNormals.length : 0;
  const typeById = new Map();

  if (Array.isArray(mapData.blockTypes)) {
    mapData.blockTypes.forEach((type) => {
      typeById.set(type.id, type);
    });
  }

  const groupedBlocks = new Map();
  let totalBlocks = 0;
  if (Array.isArray(mapData.blocks)) {
    for (const block of mapData.blocks) {
      if (!groupedBlocks.has(block.id)) groupedBlocks.set(block.id, []);
      groupedBlocks.get(block.id).push(block);
      totalBlocks += 1;
    }
  }

  const collisionPositions =
    totalBlocks > 0 ? new Float32Array(positionsPerBlock * totalBlocks) : null;
  const collisionNormals =
    totalBlocks > 0 && baseNormals ? new Float32Array(normalsPerBlock * totalBlocks) : null;
  let collisionPositionOffset = 0;
  let collisionNormalOffset = 0;

  groupedBlocks.forEach((list, id) => {
    const blockType = typeById.get(id);
    if (!blockType || list.length === 0) return;

    const materialOptions = blockType.texture
      ? { map: loadTexture(`/textures/${blockType.texture}`) }
      : { color: 0xf5d36b };
    const material = new THREE.MeshLambertMaterial(materialOptions);
    if (blockType.emissive) {
      material.emissive = new THREE.Color(0xffe066);
      material.emissiveIntensity = 0.4;
    }

    const instanced = new THREE.InstancedMesh(renderGeometry, material, list.length);
    const matrix = new THREE.Matrix4();

    list.forEach((block, index) => {
      matrix.setPosition(
        block.x * blockSize + blockSize / 2,
        block.y * blockSize + blockSize / 2,
        block.z * blockSize + blockSize / 2
      );
      instanced.setMatrixAt(index, matrix);

      if (collisionPositions) {
        const offsetX = block.x * blockSize + blockSize / 2;
        const offsetY = block.y * blockSize + blockSize / 2;
        const offsetZ = block.z * blockSize + blockSize / 2;
        for (let i = 0; i < positionsPerBlock; i += 3) {
          collisionPositions[collisionPositionOffset + i] = basePositions[i] + offsetX;
          collisionPositions[collisionPositionOffset + i + 1] = basePositions[i + 1] + offsetY;
          collisionPositions[collisionPositionOffset + i + 2] = basePositions[i + 2] + offsetZ;
        }
        collisionPositionOffset += positionsPerBlock;
      }

      if (collisionNormals && baseNormals) {
        for (let i = 0; i < normalsPerBlock; i++) {
          collisionNormals[collisionNormalOffset + i] = baseNormals[i];
        }
        collisionNormalOffset += normalsPerBlock;
      }
    });

    instanced.instanceMatrix.needsUpdate = true;
    instanced.castShadow = false;
    instanced.receiveShadow = false;
    scene.add(instanced);
  });

  if (mapData.spawn) {
    const spawnX = mapData.spawn.x * blockSize + blockSize / 2;
    // CRITICAL: Blocks are positioned with center at (block.y * blockSize + blockSize / 2)
    // Block center Y = mapData.spawn.y * blockSize + blockSize / 2
    // Block top Y = block center + blockSize/2 = mapData.spawn.y * blockSize + blockSize
    // 
    // FIX: Player was spawning about 1 block too high. The original calculation was:
    //   spawnY = mapData.spawn.y * blockSize + blockSize
    // 
    // If player is exactly 1 block too high, the spawn Y in JSON might already
    // represent the block top, not the block center. In that case, we should use:
    //   spawnY = mapData.spawn.y * blockSize + blockSize / 2 (block center)
    // This places player at block center level, which is 0.5 units below block top.
    // 
    // Alternatively, if spawn Y represents block center, we should use:
    //   spawnY = mapData.spawn.y * blockSize + blockSize / 2 + blockSize / 2 = mapData.spawn.y * blockSize + blockSize
    // But that's what we had, and it was too high.
    // 
    // Let's try: spawnY = mapData.spawn.y * blockSize + blockSize / 2 (block center)
    // This should place player at block center, which is correct for feet position.
    const spawnY = mapData.spawn.y * blockSize + blockSize / 2; // Block center Y (player feet at block center)
    const spawnZ = mapData.spawn.z * blockSize + blockSize / 2;

    // Capsule height is 1.4 (from 0.3 to 1.7 in initial setup)
    // Place feet (start) at block center level, head (end) 1.4 units above
    playerCollider.start.set(spawnX, spawnY, spawnZ);
    playerCollider.end.set(spawnX, spawnY + 1.4, spawnZ);
    playerVelocity.set(0, 0, 0);
    initialSpawnPosition = new THREE.Vector3(spawnX, spawnY, spawnZ);
    
    // Create player model if it doesn't exist (for third-person and joystick view)
    // Only create simple playerModel if GLTF character is not loaded
    if (!playerModel && !isFirstPerson() && !useGLTFCharacter) {
      createPlayerModel();
    }
    // Set visibility based on camera mode
    if (playerModel && !useGLTFCharacter) {
      playerModel.visible = !isFirstPerson();
    } else if (playerModel && useGLTFCharacter) {
      // Hide simple playerModel when GLTF character is active
      playerModel.visible = false;
    }
    
    updateCameraPosition(0);
  }

  // CRITICAL FIX: Always recreate cheese entity for Level 1 (cheese hunting)
  // Check if we're building Level 1 and need the cheese entity
  const isLevel1 = (mapData.levelId === "CHEESE_TEMPLE_LVL1" || currentLevel === LEVEL_IDS.LEVEL1);
  
  if (isLevel1 && mapData.spawn) {
    // Remove existing cheese if it exists (from previous level or failed load)
    if (floatingCheese && floatingCheese.mesh) {
      scene.remove(floatingCheese.mesh);
      floatingCheese = null;
    }
    
    // Create new cheese entity for Level 1
    // FIX: Use resolveAssetPath for texture path
    const cheeseTexture = loadTexture(resolveAssetPath("textures/blocks/cheese-stone.png"));
    const center = new THREE.Vector3(
      mapData.spawn.x * blockSize + blockSize / 2,
      playerCollider.end.y - 0.5,
      mapData.spawn.z * blockSize + blockSize / 2
    );
    floatingCheese = new FloatingCheese({
      texture: cheeseTexture,
      center,
      roamRadius: Math.min(mapData.size * 0.6, 80), // Increased from 0.4/50 to 0.6/80 for bigger range
      baseHeight: 8,
      levelId: mapData.levelId || "CHEESE_TEMPLE_LVL1",
      gameFieldSize: mapData.size || 120 // Pass full game field size for smart AI
    });
    floatingCheese.mesh.position.copy(center);
    floatingCheese.mesh.visible = true; // Ensure it's visible
    scene.add(floatingCheese.mesh);
    console.log("🧀 [CHEESE] Cheese entity created for Level 1:", {
      position: center,
      levelId: mapData.levelId,
      visible: floatingCheese.mesh.visible
    });
  } else if (!isLevel1 && floatingCheese && floatingCheese.mesh) {
    // Hide cheese for non-Level 1 levels (but don't remove it, in case we come back)
    floatingCheese.mesh.visible = false;
  }

  if (collisionPositions) {
    // CRITICAL: For Level 1, preserve existing collision mesh if it exists and is valid
    // Level 1 collision mesh is created once at game start and should persist
    const isLevel1 = (mapData.levelId === "CHEESE_TEMPLE_LVL1" || currentLevel === LEVEL_IDS.LEVEL1);
    const shouldPreserveLevel1Mesh = isLevel1 && collisionMesh && collisionMesh.geometry && collisionMesh.geometry.boundsTree;
    
    if (shouldPreserveLevel1Mesh) {
      console.log("🔒 [LEVEL 1] Preserving existing Level 1 collision mesh (not rebuilding)");
      // Ensure it's in the scene
      if (!scene.children.includes(collisionMesh)) {
        console.log("🔧 [LEVEL 1] Re-adding Level 1 collision mesh to scene");
        scene.add(collisionMesh);
      }
    } else {
      // Don't remove Level 5 collision mesh if we're in Level 5
      if (collisionMesh && currentLevel !== LEVEL_IDS.LEVEL5) {
        scene.remove(collisionMesh);
        if (collisionMesh.geometry) {
          // Dispose boundsTree if it exists
          if (collisionMesh.geometry.boundsTree && typeof collisionMesh.geometry.boundsTree.dispose === 'function') {
            collisionMesh.geometry.boundsTree.dispose();
          }
          collisionMesh.geometry.dispose();
        }
      } else if (collisionMesh && currentLevel === LEVEL_IDS.LEVEL5) {
        console.log("🔒 [LEVEL 5] Preserving Level 5 collision mesh (not removing)");
      }
      
      // Create new collision mesh
      const collisionGeometry = new THREE.BufferGeometry();
      collisionGeometry.setAttribute("position", new THREE.BufferAttribute(collisionPositions, 3));
      if (collisionNormals) {
        collisionGeometry.setAttribute("normal", new THREE.BufferAttribute(collisionNormals, 3));
      }
      collisionGeometry.computeBoundingBox();
      collisionGeometry.boundsTree = new MeshBVH(collisionGeometry);
      collisionMesh = new THREE.Mesh(collisionGeometry, new THREE.MeshBasicMaterial({ visible: false }));
      collisionMesh.visible = false;
      // Mark Level 1 collision mesh for easy identification
      if (isLevel1) {
        collisionMesh.name = 'level1_collision_mesh';
        console.log("✅ [LEVEL 1] Collision mesh created:", {
          hasGeometry: !!collisionMesh.geometry,
          hasBoundsTree: !!collisionMesh.geometry?.boundsTree,
          geometryVertices: collisionMesh.geometry?.attributes?.position?.count || 0,
          inScene: scene.children.includes(collisionMesh),
          meshName: collisionMesh.name
        });
      }
      scene.add(collisionMesh);
    }
  } else {
    console.warn("⚠️ [BUILD LEVEL] No collision positions found - collision mesh will not be created!");
  }
  
  // Create hidden trigger block for riddle Step 0 (player must find and stand on it)
  if (mapData.spawn && !riddleState.triggerBlock) {
    console.log("🧩 [RIDDLE] buildLevel: About to create trigger block, spawn exists:", !!mapData.spawn);
    if (typeof createTriggerBlock === 'function') {
    createTriggerBlock(mapData, blockSize);
    console.log("🧩 [RIDDLE] buildLevel: Trigger block created, riddleState.triggerBlock:", !!riddleState.triggerBlock);
    } else {
      console.warn("⚠️ [RIDDLE] createTriggerBlock function not available yet");
    }
  } else {
    console.warn("🧩 [RIDDLE] buildLevel: NOT creating trigger block - spawn:", !!mapData.spawn, "triggerBlock exists:", !!riddleState.triggerBlock);
  }
  
  // Create unlockable block for riddle (will be shown after step 1)
  if (mapData.spawn && !riddleState.unlockableBlock) {
    if (typeof createUnlockableBlock === 'function') {
      createUnlockableBlock(mapData.spawn, blockSize);
      // CRITICAL FIX: Ensure unlockable block is visible at Level 1 start
      // The block should be visible so players can find it, then use it after completing step 1
      if (riddleState.unlockableBlock) {
        riddleState.unlockableBlock.visible = true;
        console.log("🧩 [RIDDLE] Unlockable block set to visible at Level 1 start:", {
          position: riddleState.unlockableBlock.position,
          visible: riddleState.unlockableBlock.visible
        });
      }
    } else {
      console.warn("⚠️ [RIDDLE] createUnlockableBlock function not available yet - skipping unlockable block creation");
    }
  } else if (riddleState.unlockableBlock) {
    // If block already exists (from previous level), ensure it's visible
    riddleState.unlockableBlock.visible = true;
    console.log("🧩 [RIDDLE] Unlockable block visibility restored for Level 1:", {
      position: riddleState.unlockableBlock.position,
      visible: riddleState.unlockableBlock.visible
    });
  }
  
  // Create blinking oak stone for Riddle #2 (only if Riddle #1 is complete)
  if (mapData.spawn && !riddleState.riddle2.oakStone) {
    createRiddle2OakStone(mapData.spawn, blockSize);
  }
  
  // Create lever for Riddle #3 (always create, but hidden until Riddle #2 is complete)
  if (mapData.spawn && !riddleState.riddle3.lever) {
    createRiddle3Lever(mapData.spawn, blockSize);
  }
  
  // Create bear trap in Level 1 (deadly trap - switches from open to closed when stepped on)
  if (mapData.spawn && !level1State.bearTrap) {
    createLevel1BearTrap(mapData.spawn, blockSize);
  }
  
  // Create tree in Level 1 (huge tree with arms - decorative element)
  if (mapData.spawn && !level1State.tree) {
    createLevel1Tree(mapData.spawn, blockSize);
  }
  
  // Create second tree in Level 1 (left front of spawn, more in back area)
  if (mapData.spawn && !level1State.tree2) {
    createLevel1Tree2(mapData.spawn, blockSize);
  }
  
  // Create third tree in Level 1 (tree dead lians - left of spawn)
  if (mapData.spawn && !level1State.tree3) {
    createLevel1Tree3(mapData.spawn, blockSize);
  }
  
  // Create fourth tree in Level 1 (tree dead lians - back left area)
  if (mapData.spawn && !level1State.tree4) {
    createLevel1Tree4(mapData.spawn, blockSize);
  }
  
  // Create butterfly in Level 1 (flying butterfly at position 67, 2, 100)
  if (mapData.spawn && !level1State.butterfly) {
    createLevel1Butterfly(mapData.spawn, blockSize);
  }
  
  // Create Phormium plant 1 in Level 1 (decorative plant at position 40, 1, 100)
  if (mapData.spawn && !level1State.plant) {
    createLevel1Plant(mapData.spawn, blockSize);
  }
  
  // Create Phormium plant 2 in Level 1 (smaller plant at position 71, 1, 91)
  if (mapData.spawn && !level1State.plant2) {
    createLevel1Plant2(mapData.spawn, blockSize);
  }
  
  // 🎁 Create chests in Level 1 (3 treasure chests with DSPOINC rewards)
  // 
  // 📝 QUICK REFERENCE (see createLevel1Chests() for full docs):
  // ============================================================
  // - chest_001: Y=1.0 (ground level) - 100 DSPOINC
  // - chest_002: Y=1.0 (ground level) - 250 DSPOINC
  // - chest_003: Y=29.0 (tower top, elevated) - 500 DSPOINC
  //
  // Grass exclusion zones automatically registered for all chests
  // Elevated chests (Y>5.0) use custom positioning mode
  //
  // CRITICAL: Since cleanupAllLevels() clears chests, we must always recreate them when building Level 1
  // CRITICAL FIX: Always clear and recreate chests to ensure they're properly loaded after warp/respawn
  if (mapData.spawn && chestSystem) {
    // CRITICAL: Always clear existing chests first to ensure clean state
    // This prevents issues where chests exist but aren't properly loaded after warp/respawn
    console.log("🎁 [LEVEL 1] Clearing existing chests before recreation (ensuring clean state)...");
    chestSystem.clearLevel(LEVEL_IDS.LEVEL1);
    
      // CRITICAL: Small delay to ensure cleanup completes before recreation
      // This prevents race conditions where chests might not be fully disposed
      setTimeout(async () => {
      // Load opened chests from database before creating chests
      if (resolvedDiscordId && chestSystem) {
        console.log("📥 [LEVEL 1] Loading opened chests from database...");
        await chestSystem.loadOpenedChests(resolvedDiscordId, API_BASE_URL);
      }
      
      // Always create chests when building Level 1 (they were just cleared by cleanupAllLevels or previous build)
      console.log("🎁 [LEVEL 1] Creating chests (always recreate to ensure proper loading)...");
      createLevel1Chests(mapData.spawn, blockSize);
      
      // CRITICAL: Multiple verification passes to ensure chests load correctly
      // Pass 1: After 500ms - Check if chests are loading
      setTimeout(() => {
        if (chestSystem) {
          const level1Chests = chestSystem.getChestsForLevel(LEVEL_IDS.LEVEL1);
          console.log(`🔍 [LEVEL 1] First verification pass (500ms):`, {
            totalChests: level1Chests.size,
            chestIds: Array.from(level1Chests.keys()),
            chestsStatus: Array.from(level1Chests.entries()).map(([id, chest]) => ({
              id: id,
              isLoaded: chest.isLoaded,
              hasMesh: !!chest.mesh,
              isLoading: chest.isLoading,
              position: chest.position
            }))
          });
          
          // Check if chest 2 exists and is loading
          const chest2 = level1Chests.get('chest_002');
          if (!chest2) {
            console.error(`❌ [LEVEL 1] Chest 2 (chest_002) not found in chest system! Recreating...`);
            // Recreate chest 2
            const spawnX = mapData.spawn ? mapData.spawn.x * blockSize + blockSize / 2 : 60;
            const spawnZ = mapData.spawn ? mapData.spawn.z * blockSize + blockSize / 2 : 15;
            const chest2X = 35;
            const chest2Z = 50;
            const chest2Y = 1.0;
            chestSystem.addChest(LEVEL_IDS.LEVEL1, {
              id: 'chest_002',
              type: 'chest2',
              position: new THREE.Vector3(chest2X, chest2Y, chest2Z),
              dspoincAmount: 250,
              levelId: 'CHEESE_TEMPLE_LEVEL1'
            });
          } else if (!chest2.isLoaded && !chest2.isLoading) {
            console.warn(`⚠️ [LEVEL 1] Chest 2 exists but not loading, forcing reload...`);
            // Force reload chest 2
            if (chest2.mesh) {
              chest2.dispose();
              level1Chests.delete('chest_002');
            }
            const spawnX = mapData.spawn ? mapData.spawn.x * blockSize + blockSize / 2 : 60;
            const spawnZ = mapData.spawn ? mapData.spawn.z * blockSize + blockSize / 2 : 15;
            const chest2X = 35;
            const chest2Z = 50;
            const chest2Y = 1.0;
            chestSystem.addChest(LEVEL_IDS.LEVEL1, {
              id: 'chest_002',
              type: 'chest2',
              position: new THREE.Vector3(chest2X, chest2Y, chest2Z),
              dspoincAmount: 250,
              levelId: 'CHEESE_TEMPLE_LEVEL1'
            });
          }
        }
      }, 500);
      
      // Pass 2: After 1000ms - Use the verification function
      setTimeout(() => {
        verifyAndFixLevel1ChestPositions();
      }, 1000); // Wait longer for chests to load (1000ms should be enough)
      
      // Pass 3: After 2000ms - Final verification pass
      setTimeout(() => {
        verifyAndFixLevel1ChestPositions();
      }, 2000); // Final check after all async operations complete
    }, 100); // Increased delay to ensure cleanup completes
  }
  
  // Create 3 levers for Riddle #4 (Hidden Secret Riddle)
  if (mapData.spawn && riddleState.riddle4 && !riddleState.riddle4.lever1) {
    createRiddle4Levers(mapData.spawn, blockSize);
  }
  
  // Create movable block for Riddle #3 (only if lever is pressed)
  if (mapData.spawn && !riddleState.riddle3.movableBlock && riddleState.riddle3.step1Complete) {
    createRiddle3MovableBlock(mapData.spawn, blockSize);
  }
  
  // Create oak block for Riddle #3 (only if lever is pressed)
  if (mapData.spawn && !riddleState.riddle3.oakBlock && riddleState.riddle3.step1Complete) {
    createRiddle3OakBlock(mapData.spawn, blockSize);
  }
  
  // Create portal for Riddle #3 (only if Step 2 is complete)
  if (mapData.spawn && !riddleState.riddle3.portal && riddleState.riddle3.step2Complete) {
    createRiddle3Portal(mapData.spawn, blockSize);
    // FIX: If Step 2 is already complete, make portal visible immediately
    if (riddleState.riddle3.portal && riddleState.riddle3.step2Complete) {
      riddleState.riddle3.portal.visible = true;
      console.log("🧩 [RIDDLE #3] Portal created and made visible (Step 2 already complete on level load)");
    }
  }
  
  // 🐉 Create NPC/Monster that runs around the level
  if (mapData.spawn && !window.npcMonster) {
    createNPCMonster(mapData.spawn, blockSize);
    console.log("🐉 [NPC] Monster NPC created and added to level");
  }

  baseCollisionGeometry.dispose();
  renderGeometry.dispose();
}

const movement = { forward: false, backward: false, left: false, right: false, sprint: false, flyUp: false, flyDown: false };
const keyboardMovement = { forward: false, backward: false, left: false, right: false, sprint: false, flyUp: false, flyDown: false };
const joystickMovementFlags = { forward: false, backward: false, left: false, right: false };

function updateAggregatedMovement() {
  movement.forward = keyboardMovement.forward || joystickMovementFlags.forward;
  movement.backward = keyboardMovement.backward || joystickMovementFlags.backward;
  movement.left = keyboardMovement.left || joystickMovementFlags.left;
  movement.right = keyboardMovement.right || joystickMovementFlags.right;
  movement.sprint = keyboardMovement.sprint;
  movement.flyUp = keyboardMovement.flyUp;
  movement.flyDown = keyboardMovement.flyDown;
}

updateAggregatedMovement();

function refreshJoystickMovementFlags() {
  const threshold = 0.2;
  joystickMovementFlags.forward = joystickActive && joystickDirection.y < -threshold;
  joystickMovementFlags.backward = joystickActive && joystickDirection.y > threshold;
  joystickMovementFlags.left = joystickActive && joystickDirection.x < -threshold;
  joystickMovementFlags.right = joystickActive && joystickDirection.x > threshold;
  updateAggregatedMovement();
}
const clock = new THREE.Clock();

// 🚀 GOD MODE - Double speed + Fly mode (like Minecraft)
// 🔐 ROLE-BASED ACCESS CONTROL (January 9, 2026): Access is checked in fetchPlayerDetails()
// God Mode is automatically disabled if user doesn't have Admin, Moderator, or Game Tester role
let godMode = false;
try {
  const savedGodMode = localStorage.getItem("cheese_temple_god_mode");
  if (savedGodMode !== null) {
    godMode = savedGodMode === "true";
  }
} catch (e) {
  console.warn("Failed to load GOD mode setting:", e);
}

function getForwardVector() {
  try {
  if (isFirstPerson()) {
    // First-person: use camera direction
    const vector = new THREE.Vector3(0, 0, -1);
    vector.applyQuaternion(camera.quaternion);
    vector.y = 0;
      const normalized = vector.normalize();
      // Safety check: if vector is invalid, return default forward (positive Z)
      if (!isFinite(normalized.x) || !isFinite(normalized.z) || (normalized.x === 0 && normalized.z === 0)) {
        console.warn("⚠️ [MOVEMENT] Invalid forward vector in first-person, using default (0, 0, 1)");
        return new THREE.Vector3(0, 0, 1);
      }
      return normalized;
  } else {
    // Third-person or Joystick view: use camera's horizontal look direction
    const lookDirection = new THREE.Vector3();
    camera.getWorldDirection(lookDirection);
    lookDirection.y = 0;
      const normalized = lookDirection.normalize();
      // Safety check: if vector is invalid, return default forward (positive Z)
      if (!isFinite(normalized.x) || !isFinite(normalized.z) || (normalized.x === 0 && normalized.z === 0)) {
        console.warn("⚠️ [MOVEMENT] Invalid forward vector in third-person, using default (0, 0, 1)");
        return new THREE.Vector3(0, 0, 1);
      }
      return normalized;
    }
  } catch (error) {
    console.error("❌ [MOVEMENT] Error in getForwardVector:", error);
    // Fallback: return default forward direction (positive Z)
    return new THREE.Vector3(0, 0, 1);
  }
}

function getSideVector() {
  try {
  if (isFirstPerson()) {
    // First-person: use camera direction (right direction)
    const vector = new THREE.Vector3(1, 0, 0);
    vector.applyQuaternion(camera.quaternion);
    vector.y = 0;
      const normalized = vector.normalize();
      // Safety check: if vector is invalid, return default right (positive X)
      if (!isFinite(normalized.x) || !isFinite(normalized.z) || (normalized.x === 0 && normalized.z === 0)) {
        console.warn("⚠️ [MOVEMENT] Invalid side vector in first-person, using default (1, 0, 0)");
        return new THREE.Vector3(1, 0, 0);
      }
      return normalized;
  } else {
    // Third-person or Joystick view: perpendicular to forward vector
    const forward = getForwardVector();
      const side = new THREE.Vector3(-forward.z, 0, forward.x);
      const normalized = side.normalize();
      // Safety check: if vector is invalid, return default right (positive X)
      if (!isFinite(normalized.x) || !isFinite(normalized.z) || (normalized.x === 0 && normalized.z === 0)) {
        console.warn("⚠️ [MOVEMENT] Invalid side vector in third-person, using default (1, 0, 0)");
        return new THREE.Vector3(1, 0, 0);
      }
      return normalized;
    }
  } catch (error) {
    console.error("❌ [MOVEMENT] Error in getSideVector:", error);
    // Fallback: return default right direction (positive X)
    return new THREE.Vector3(1, 0, 0);
  }
}

function handleLevel2Collisions() {
  const floorY = level2Config.origin.y + PLAYER_RADIUS;
  const boundsPadding = PLAYER_RADIUS + 0.2;
  const minX = level2Config.origin.x - level2Config.size + boundsPadding;
  const maxX = level2Config.origin.x + level2Config.size - boundsPadding;
  const minZ = level2Config.origin.z - level2Config.size + boundsPadding;
  const maxZ = level2Config.origin.z + level2Config.size - boundsPadding;

  onGround = false;
  const distanceToFloor = playerCollider.start.y - floorY;
  if (distanceToFloor <= 0.08 && playerVelocity.y <= 0) {
    playerCollider.start.y = floorY;
    playerCollider.end.y = floorY + PLAYER_HEIGHT;
    playerVelocity.y = Math.max(0, playerVelocity.y);
    onGround = true;
    hasDoubleJumped = false; // Reset double jump when landing
  } else if (playerCollider.start.y < floorY) {
    playerCollider.start.y = floorY;
    playerCollider.end.y = floorY + PLAYER_HEIGHT;
    playerVelocity.y = 0;
    onGround = true;
    hasDoubleJumped = false; // Reset double jump when landing
  }

  const prevX = playerCollider.start.x;
  const clampedX = THREE.MathUtils.clamp(playerCollider.start.x, minX, maxX);
  playerCollider.start.x = clampedX;
  playerCollider.end.x = clampedX;
  if (prevX !== clampedX) {
    playerVelocity.x = 0;
  }

  const prevZ = playerCollider.start.z;
  const clampedZ = THREE.MathUtils.clamp(playerCollider.start.z, minZ, maxZ);
  playerCollider.start.z = clampedZ;
  playerCollider.end.z = clampedZ;
  if (prevZ !== clampedZ) {
    playerVelocity.z = 0;
  }

  if (playerCollider.start.y < floorY - 10) {
    playerCollider.start.y = floorY;
    playerCollider.end.y = floorY + PLAYER_HEIGHT;
    playerVelocity.y = 0;
  }
}

function playerCollisions() {
  if (currentLevel === LEVEL_IDS.LEVEL2) {
    handleLevel2Collisions();
    return;
  }
  if (currentLevel === LEVEL_IDS.LEVEL3) {
    handleLevel3Collisions();
    return;
  }
  if (currentLevel === LEVEL_IDS.LEVEL4) {
    handleLevel4Collisions();
    return;
  }

  // 🚀 GOD MODE: Allow free flight while actively pressing fly keys,
  // but still check ground collisions so player can "feel the ground" (same as other levels)
  // Note: We don't return early here - we continue to check ground collisions even in GOD Mode
  // This matches the behavior of Level 2, 3, and 4 where ground collision always works

  if (!collisionMesh || !collisionMesh.geometry || !collisionMesh.geometry.boundsTree) {
    // No collision mesh yet, just prevent falling forever
    if (currentLevel === LEVEL_IDS.LEVEL1) {
      // Level 1 specific: Log if collision mesh is missing (critical for Level 1)
      if (Math.random() < 0.1) { // 10% chance to log (more frequent for Level 1)
        console.error("❌ [LEVEL 1] Collision mesh not ready!", {
          collisionMesh: !!collisionMesh,
          hasGeometry: !!collisionMesh?.geometry,
          hasBoundsTree: !!collisionMesh?.geometry?.boundsTree,
          meshName: collisionMesh?.name,
          inScene: collisionMesh ? scene.children.includes(collisionMesh) : false,
          playerY: playerCollider.start.y.toFixed(2)
        });
      }
    } else if (currentLevel === LEVEL_IDS.LEVEL5) {
      // Level 5 specific: Log if collision mesh is missing
      if (Math.random() < 0.01) { // 1% chance to log (avoid spam)
        console.warn("⚠️ [LEVEL 5] Collision mesh not ready:", {
          collisionMesh: !!collisionMesh,
          hasGeometry: !!collisionMesh?.geometry,
          hasBoundsTree: !!collisionMesh?.geometry?.boundsTree,
          meshName: collisionMesh?.name
        });
      }
    }
    if (playerCollider.start.y < -10) {
      playerCollider.start.y = 5;
      playerCollider.end.y = 6.4;
      playerVelocity.y = 0;
    }
    return;
  }

  onGround = false;

  try {
    // Use Three.js Raycaster for reliable collision detection
    const raycaster = new THREE.Raycaster();
    
    // Ground check: raycast downward from player feet
    // Use longer raycast to detect platforms below
    const rayStart = playerCollider.start.clone();
    rayStart.y += 0.1; // Start slightly above feet to avoid self-intersection
    const rayDir = new THREE.Vector3(0, -1, 0);
    
    raycaster.set(rayStart, rayDir);
    raycaster.far = 5.0; // Increased from 1.0 to detect platforms below (allows falling)
    raycaster.near = 0;
    
    // Level 6: Use map geometry for collision (hills and terrain) - ONLY if using GLTF map
    let groundHits = [];
    if (currentLevel === LEVEL_IDS.LEVEL6) {
      // CRITICAL: Check if we're using GLTF map or normal ground
      const groundConfig = getGroundConfigForLevel(LEVEL_IDS.LEVEL6);
      const isUsingGLTF = groundConfig && groundConfig.groundType === 'gltf';
      
      // Only use GLTF collision if groundType is 'gltf'
      if (isUsingGLTF) {
        // CRITICAL: Ensure map model world matrix is updated for raycasting
        let collisionTarget = null;
        
        // Try collisionMapModel first (set in buildLevel6PhoenixArena)
        if (level6State && level6State.collisionMapModel) {
          collisionTarget = level6State.collisionMapModel;
          // Update world matrix for accurate raycasting
          collisionTarget.updateMatrixWorld(true);
          // Debug: Verify BVH trees exist
          let bvhCount = 0;
          collisionTarget.traverse((child) => {
            if (child.isMesh && child.geometry && child.geometry.boundsTree) {
              bvhCount++;
            }
          });
          if (bvhCount === 0 && Math.random() < 0.1) { // 10% chance to log
            console.warn(`⚠️ [COLLISION] Level 6: collisionMapModel has no BVH trees!`);
          }
        } 
        // Fallback: Try grass system map model (this handles cases where map loads after buildLevel6PhoenixArena)
        else if (grassSystem && typeof grassSystem.getGLTFMapModel === 'function') {
        const grassMapModel = grassSystem.getGLTFMapModel();
        if (grassMapModel) {
          collisionTarget = grassMapModel;
          // Update world matrix for accurate raycasting
          collisionTarget.updateMatrixWorld(true);
          // CRITICAL: Create BVH trees if they don't exist (grass system doesn't create them)
          let bvhCount = 0;
          let bvhErrorCount = 0;
          collisionTarget.traverse((child) => {
            if (child.isMesh && child.geometry && child.geometry.isBufferGeometry) {
              try {
                if (!child.geometry.boundsTree) {
                  child.geometry.boundsTree = new MeshBVH(child.geometry);
                  bvhCount++;
                }
                child.raycast = acceleratedRaycast;
              } catch (bvhError) {
                bvhErrorCount++;
                console.warn(`⚠️ [COLLISION] Failed to create BVH for mesh "${child.name}":`, bvhError);
              }
            }
          });
          if (bvhCount > 0) {
            console.log(`✅ [COLLISION] Created ${bvhCount} BVH trees for grass system map model (fallback)${bvhErrorCount > 0 ? ` (${bvhErrorCount} errors)` : ''}`);
          }
          // CRITICAL: Always store as collision map model for future use (even if no new BVH trees were created)
          // This ensures we use the map model for collision detection
          level6State.collisionMapModel = collisionTarget;
          console.log(`✅ [COLLISION] Set collisionMapModel from grass system fallback:`, {
            hasModel: !!level6State.collisionMapModel,
            children: level6State.collisionMapModel?.children?.length || 0
          });
        } else {
          // Map still not loaded - log detailed info
          if (Math.random() < 0.1) { // 10% chance to log
            console.warn("⚠️ [COLLISION] Grass system map model still not available:", {
              hasGrassSystem: !!grassSystem,
              hasGetGLTFMapModel: typeof grassSystem.getGLTFMapModel === 'function',
              returnedValue: grassMapModel
            });
          }
        }
      }
      
      // Perform raycast if we have a collision target
      if (collisionTarget) {
        // Use recursive intersection to check all map meshes
        groundHits = raycaster.intersectObject(collisionTarget, true);
        if (groundHits.length === 0 && Math.random() < 0.05) { // 5% chance to log
          // Debug: Log raycast details
          console.warn(`⚠️ [COLLISION] Level 6: No ground hits. Ray from (${rayStart.x.toFixed(2)}, ${rayStart.y.toFixed(2)}, ${rayStart.z.toFixed(2)}) direction (${rayDir.x}, ${rayDir.y}, ${rayDir.z})`);
          console.warn(`   Collision target: ${collisionTarget.name || 'unnamed'}, children: ${collisionTarget.children.length}`);
        }
      } else {
        if (Math.random() < 0.1) { // 10% chance to log
          console.warn("⚠️ [COLLISION] Level 6: No collision target available", {
            hasLevel6State: !!level6State,
            hasCollisionMapModel: !!(level6State && level6State.collisionMapModel),
            hasGrassSystem: !!grassSystem,
            hasGetGLTFMapModel: !!(grassSystem && typeof grassSystem.getGLTFMapModel === 'function')
          });
        }
      }
      
        // Final fallback: Use collision mesh if available
        if (groundHits.length === 0 && collisionMesh) {
          groundHits = raycaster.intersectObject(collisionMesh, false);
          if (groundHits.length > 0) {
            console.log("✅ [COLLISION] Level 6: Using fallback collision mesh (GLTF mode)");
          }
        }
      } else {
        // Normal ground system - use standard collision mesh
        if (collisionMesh) {
          groundHits = raycaster.intersectObject(collisionMesh, false);
        }
      }
    } else if (collisionMesh) {
      // Other levels: Use collision mesh
      groundHits = raycaster.intersectObject(collisionMesh, false);
    }
    
    if (groundHits.length > 0) {
      const hit = groundHits[0];
      const groundY = hit.point.y + 0.35; // Player radius
      const distanceToGround = playerCollider.start.y - groundY;
      
      // 🚀 GOD MODE: Always prevent going below ground (same as Level 2, 3, 4)
      // This ensures player "feels the ground" even in GOD Mode
      const activelyFlying = godMode && (movement.flyUp || movement.flyDown);
      
      if (playerCollider.start.y < groundY) {
        // Player is below ground - snap back up (prevents going through floor)
        playerCollider.start.y = groundY;
        playerCollider.end.y = groundY + 1.4;
        // Only reset Y velocity if not actively flying up
        if (!activelyFlying || !movement.flyUp) {
          playerVelocity.y = 0;
        }
        onGround = true;
        hasDoubleJumped = false; // Reset double jump when landing
      } else if (distanceToGround <= 0.2 || (distanceToGround <= 0.5 && playerVelocity.y <= 0)) {
        // Player is on or very close to ground
        // In God Mode: Only snap to ground if NOT actively flying up
        if (activelyFlying && movement.flyUp) {
          // Actively flying up in God Mode: Don't snap to ground, allow upward movement
          // Only prevent going below ground
          if (playerCollider.start.y < groundY) {
            playerCollider.start.y = groundY;
            playerCollider.end.y = groundY + 1.4;
            // Only reset velocity if not actively flying up
            if (!movement.flyUp) {
              playerVelocity.y = 0;
            }
          }
          onGround = false; // Not considered "on ground" when actively flying
          // Debug logging (only occasionally)
          if (Math.random() < 0.05) { // 5% chance to log
            console.log("🚀 [GOD MODE COLLISION] Allowing upward flight from ground", {
              distanceToGround: distanceToGround.toFixed(3),
              playerY: playerCollider.start.y.toFixed(3),
              groundY: groundY.toFixed(3),
              velocityY: playerVelocity.y.toFixed(3),
              flyUp: movement.flyUp
            });
          }
        } else {
          // Normal mode or not flying: Snap to ground and clamp velocity
          playerCollider.start.y = groundY;
          playerCollider.end.y = groundY + 1.4;
          onGround = true;
          hasDoubleJumped = false; // Reset double jump when landing
          // Prevent falling through ground
          playerVelocity.y = Math.max(0, playerVelocity.y);
        }
      } else {
        // Player is above ground but not close enough - allow falling/flying
        onGround = false;
      }
    } else {
      // No ground found - player is in air, allow falling
      onGround = false;
      // Only reset if falling too far (safety net)
      if (playerCollider.start.y < -10) {
        playerCollider.start.y = 5;
        playerCollider.end.y = 6.4;
        playerVelocity.y = 0;
      }
    }

    // Wall collision is now handled before movement in the animate loop
  } catch (error) {
    console.warn("Collision detection error:", error);
    // Fallback: just prevent falling too far
    if (playerCollider.start.y < -5) {
      playerCollider.start.y = 5;
      playerCollider.end.y = 6.4;
      playerVelocity.y = 0;
    }
  }
}

function updateCameraPosition(delta) {
  // If options menu is open, ensure cursor stays visible
  const optionsMenuOpen = window.optionsMenuOpen && optionsMenu && optionsMenu.style.display === "flex";
  if (optionsMenuOpen) {
    document.body.style.cursor = "default";
    if (playerControls) {
      playerControls.getPointerLockControls().unlock();
    }
  }
  
  if (isFirstPerson()) {
    // First-person: camera at player head position
    camera.position.copy(playerCollider.end);
    
    // CRITICAL: PointerLockControls automatically handles camera rotation via mousemove events
    // The camera rotation is applied directly by PointerLockControls when pointer is locked
    // PointerLockControls listens to mousemove events and modifies camera.rotation automatically
    // 
    // DO NOT modify camera.rotation or call camera.lookAt() in first-person mode
    // Let PointerLockControls handle all rotation - it works automatically when pointer is locked
    
    // DEBUG: First-person mode logging disabled for performance
    // Enable only when specifically debugging camera issues by uncommenting below
    // WARNING: Enabling this will spam console and reduce FPS
    /*
    if (DEBUG_CAMERA && playerControls) {
      const controls = playerControls.getPointerLockControls();
      if (controls.isLocked && Math.random() < 0.01) { // 1% chance when enabled
        console.log("🎮 [DEBUG] First-person mode:", {
          pointerLocked: controls.isLocked,
          cameraRotation: {
            x: camera.rotation.x.toFixed(3),
            y: camera.rotation.y.toFixed(3),
            z: camera.rotation.z.toFixed(3)
          }
        });
      }
    }
    */
    
    // Hide player model in first-person
    if (playerModel) {
      playerModel.visible = false;
    }
  } else {
    // Third-person or Joystick view: disable PointerLockControls rotation, use our custom system
    // The controls object still exists but we override camera position/rotation
    // Show player model in third-person and joystick view
    // Note: Visibility is managed by setCameraMode, but we ensure it's visible here as a safety check
    // FIX: Only show simple playerModel if GLTF character is not active
    if (!useGLTFCharacter) {
    if (!playerModel) {
      createPlayerModel();
    }
    if (playerModel && !playerModel.visible) {
      // Only set visible if it's not already visible (avoid unnecessary updates)
      playerModel.visible = true;
      }
    } else {
      // GLTF character is active - ensure it's visible in 3rd person
      if (playerCharacterModel) {
        if (!playerCharacterModel.visible) {
          console.log("🎭 [CHARACTER] Forcing character visibility in 3rd person view");
          playerCharacterModel.visible = true;
        }
        // Ensure character is in scene
        if (!scene.children.includes(playerCharacterModel)) {
          console.warn("⚠️ [CHARACTER] Character not in scene in 3rd person view! Adding it now...");
          scene.add(playerCharacterModel);
        }
      }
    }
    
    // Update camera angles from mouse movement or mobile joystick
    // Use same sensitivity as first-person controls for consistency
    const mouseSensitivity = 0.002; // Match PointerLockControls sensitivity
    
    if (document.pointerLockElement === renderer.domElement && !isJoystickView() && playerControls) {
      // Third-person mode: use mouse for camera control
      // Get mouse deltas from PlayerControls module
      const mouseDelta = playerControls.getMouseDelta();
      
      // Horizontal rotation (yaw): rotate around player
      thirdPersonCameraAngle.horizontal -= mouseDelta.x * mouseSensitivity;
      
      // Vertical rotation (pitch): look up/down
      // Match first-person: mouse up = look up (decrease vertical angle in spherical coords)
      // In spherical coordinates: negative vertical = look up, positive = look down
      // Clamp to reasonable range: -85° to +85° (prevent gimbal lock)
      thirdPersonCameraAngle.vertical = Math.max(-Math.PI / 2 + 0.1, Math.min(Math.PI / 2 - 0.1, thirdPersonCameraAngle.vertical + mouseDelta.y * mouseSensitivity));
      
      // Reset deltas after use
      playerControls.resetMouseDelta();
    } else if ((isMobileLandscape || window.enableDesktopJoysticks || isJoystickView()) && cameraJoystickActive) {
      // Mobile/desktop camera control via joystick (works in third-person and joystick view)
      const joystickSensitivity = 0.05;
      // Horizontal rotation
      thirdPersonCameraAngle.horizontal -= cameraJoystickDirection.x * joystickSensitivity;
      // Vertical rotation: push up = look up (invert Y)
      thirdPersonCameraAngle.vertical = Math.max(-Math.PI / 2 + 0.1, Math.min(Math.PI / 2 - 0.1, thirdPersonCameraAngle.vertical - cameraJoystickDirection.y * joystickSensitivity));
    }
    
    // Third-person or Joystick view: camera follows behind player using spherical coordinates
    const playerPos = new THREE.Vector3().lerpVectors(playerCollider.start, playerCollider.end, 0.5);
    playerPos.y += 0.5; // Center of player body (eye level)
    
    // Use spherical coordinates for smooth camera movement
    const horizontalAngle = thirdPersonCameraAngle.horizontal;
    const verticalAngle = thirdPersonCameraAngle.vertical;
    
    // Calculate camera position using spherical coordinates
    // horizontalAngle: rotation around Y axis (yaw)
    // verticalAngle: pitch (up/down)
    // thirdPersonCameraDistance: radius (distance from player)
    const cameraOffsetX = Math.sin(horizontalAngle) * Math.cos(verticalAngle) * thirdPersonCameraDistance;
    const cameraOffsetY = Math.sin(verticalAngle) * thirdPersonCameraDistance + thirdPersonCameraHeight;
    const cameraOffsetZ = Math.cos(horizontalAngle) * Math.cos(verticalAngle) * thirdPersonCameraDistance;
    
    camera.position.set(
      playerPos.x + cameraOffsetX,
      playerPos.y + cameraOffsetY,
      playerPos.z + cameraOffsetZ
    );
    
    // Look at player position (camera always focuses on player center)
    // This creates a smooth third-person follow camera
    camera.lookAt(playerPos);
    
    // Update player model rotation to face movement direction (or camera direction if not moving)
    // Only update simple playerModel if GLTF character is not active
    // GLTF character rotation is handled in updatePlayerCharacter function
    if (playerModel && !useGLTFCharacter) {
      if (playerVelocity.lengthSq() > 0.01) {
        const moveDir = new THREE.Vector3(playerVelocity.x, 0, playerVelocity.z).normalize();
        const angle = Math.atan2(moveDir.x, moveDir.z);
        playerModel.rotation.y = angle;
      } else {
        // Face camera direction when not moving
        const cameraDir = new THREE.Vector3();
        camera.getWorldDirection(cameraDir);
        cameraDir.y = 0;
        cameraDir.normalize();
        if (cameraDir.lengthSq() > 0.1) {
          const angle = Math.atan2(cameraDir.x, cameraDir.z);
          playerModel.rotation.y = angle;
        }
      }
    }
    // GLTF character position and rotation are handled in updatePlayerCharacter function
  }
}

function createPlayerModel() {
  if (playerModel) {
    console.log("🎮 [DEBUG] Player model already exists, returning existing model");
    return playerModel;
  }
  
  console.log("🎮 [DEBUG] Creating player model (robot character)");
  
  // Create a simple capsule-shaped player model
  const group = new THREE.Group();
  
  // Body (cylinder)
  const bodyGeometry = new THREE.CylinderGeometry(0.3, 0.3, 1.0, 8);
  const bodyMaterial = new THREE.MeshLambertMaterial({ color: 0x4a5568 });
  const body = new THREE.Mesh(bodyGeometry, bodyMaterial);
  body.position.y = 0.5;
  group.add(body);
  
  // Head (sphere)
  const headGeometry = new THREE.SphereGeometry(0.25, 8, 8);
  const headMaterial = new THREE.MeshLambertMaterial({ color: 0xfbbf24 });
  const head = new THREE.Mesh(headGeometry, headMaterial);
  head.position.y = 1.25;
  group.add(head);
  
  // Arms (simple boxes)
  const armGeometry = new THREE.BoxGeometry(0.15, 0.6, 0.15);
  const armMaterial = new THREE.MeshLambertMaterial({ color: 0x4a5568 });
  
  const leftArm = new THREE.Mesh(armGeometry, armMaterial);
  leftArm.position.set(-0.4, 0.5, 0);
  group.add(leftArm);
  
  const rightArm = new THREE.Mesh(armGeometry, armMaterial);
  rightArm.position.set(0.4, 0.5, 0);
  group.add(rightArm);
  
  group.position.copy(playerCollider.start);
  // Visibility will be managed by updateCameraPosition and setCameraMode
  group.visible = !isFirstPerson(); // Hidden in first-person mode by default
  scene.add(group);
  playerModel = group;
  console.log("🎮 [DEBUG] Player model created and added to scene, visible:", group.visible);
  return group;
}

