function jumpToRiddle(riddleNumber) {
  level1Completed = false;
  riddle3Completed = false;

  switch (riddleNumber) {
    case 1:
      jumpToRiddle1();
      break;
    case 2:
      jumpToRiddle2();
      break;
    default:
      jumpToRiddle3();
      break;
  }
}

