const PLAYER_HEIGHT = playerCollider.end.y - playerCollider.start.y;
const PLAYER_RADIUS = typeof playerCollider.radius === "number" ? playerCollider.radius : 0.35;
const LEVEL3_CRUSH_GAP_THRESHOLD = PLAYER_RADIUS * 1.4;
const LEVEL3_CORNER_CRUSH_GAP_THRESHOLD = PLAYER_RADIUS * 2.2;
const LEVEL3_CRUSH_TIME_REQUIRED = 0.2;
function setPlayerFeetPosition(targetPosition) {
  const feetY = targetPosition.y;
  playerCollider.start.set(targetPosition.x, feetY, targetPosition.z);
  playerCollider.end.set(targetPosition.x, feetY + PLAYER_HEIGHT, targetPosition.z);
  playerVelocity.set(0, 0, 0);
  updateCameraPosition(0);
}

function buildLevel2WhiteRoom() {
  if (level2State.built) return;
  // CRITICAL: Don't set group invisible here - it might be visible if player is in Level 2
  // Only set invisible if we're sure we're not in Level 2
  if (currentLevel !== LEVEL_IDS.LEVEL2) {
    level2State.group.visible = false;
  }
  level2State.inspectionZones = [];
  level2State.previewAnchors = [];
  level2State.anchorLabels = [];
  // 🚨 PERFORMANCE: Clear previewModels array on rebuild to prevent memory leaks
  level2State.previewModels = [];
  // CRITICAL: Only reset previewsSpawned if we're actually rebuilding (not just checking)
  // This prevents duplicate model loading when buildLevel2WhiteRoom is called multiple times
  if (!level2State.built) {
    level2State.previewsSpawned = false;
  }
  const origin = level2Config.origin;
  const size = level2Config.size;

  const floorGeometry = new THREE.PlaneGeometry(size * 4, size * 4);
  // 🚨 CRITICAL PERFORMANCE FIX: Use MeshStandardMaterial instead of MeshPhongMaterial
  // MeshStandardMaterial is more efficient and matches Level 3 (which has better FPS)
  // MeshPhongMaterial uses Phong shading which is more expensive to compute
  const floorMaterial = new THREE.MeshStandardMaterial({
    color: 0xffffff,
    side: THREE.DoubleSide,
    metalness: 0.1,
    roughness: 0.9,
    polygonOffset: true,
    polygonOffsetFactor: -1,
    polygonOffsetUnits: -1
  });
  const floor = new THREE.Mesh(floorGeometry, floorMaterial);
  floor.rotation.x = -Math.PI / 2;
  floor.position.set(origin.x, origin.y, origin.z);
  level2State.group.add(floor);

  const grid = new THREE.GridHelper(size * 2.5, size, 0xf5f5f5, 0xf5f5f5);
  grid.position.set(origin.x, origin.y + 0.03, origin.z);
  grid.material.transparent = true;
  grid.material.opacity = 0.12;
  grid.material.depthWrite = false;
  grid.renderOrder = 1;
  level2State.group.add(grid);

  // REMOVED: roomShell completely removed to allow sky to work like Level 1
  // Level 1 has no roomShell, so Levels 2, 3, 4 should also have clear sky
  // Only walls for collision are kept (via collision detection, not visual roomShell)
  // No roomShell = clear sky like Level 1 and Level 5

  const ambient = new THREE.AmbientLight(0xffffff, 1.4);
  level2State.group.add(ambient);
  const directional = new THREE.DirectionalLight(0xffffff, 0.8);
  directional.position.set(origin.x + 20, origin.y + level2Config.wallHeight, origin.z + 8);
  directional.castShadow = false;
  level2State.group.add(directional);

  const shelfGeometry = new THREE.BoxGeometry(1.4, 3.5, 5.6);
  const shelfMaterial = new THREE.MeshStandardMaterial({ color: 0xf5f5f5, metalness: 0.25, roughness: 0.15 });
  const pedestalGeometry = new THREE.BoxGeometry(1.2, 0.35, 1.2);
  const pedestalMaterial = new THREE.MeshStandardMaterial({ color: 0xffffff, emissive: 0xfefefe, emissiveIntensity: 0.15 });
  const shelfConfigs = [
    { id: "shelf_left", label: "Left Weapon Shelf", baseX: origin.x - 9.5 },
    { id: "shelf_right", label: "Right Weapon Shelf", baseX: origin.x + 9.5 }
  ];
  const shelfSpacing = 7;
  const shelfStartZ = origin.z - 18;
  let displayShelfNumber = 0;

  const createShelfSegment = (rowCfg, zPos) => {
    const shelf = new THREE.Mesh(shelfGeometry, shelfMaterial);
    shelf.position.set(rowCfg.baseX, origin.y + 3.4, zPos);
    level2State.group.add(shelf);

    [-1, 1].forEach((sideOffset) => {
      const pedestal = new THREE.Mesh(pedestalGeometry, pedestalMaterial);
      pedestal.position.set(rowCfg.baseX + sideOffset * 1.5, origin.y + 0.18, zPos - 0.6);
      level2State.group.add(pedestal);
      displayShelfNumber++;
      level2State.previewAnchors.push({
        type: "shelf",
        position: pedestal.position.clone(),
        shelfNumber: displayShelfNumber
      });
    });
  };

  shelfConfigs.forEach((rowCfg) => {
    for (let i = 0; i < LEVEL2_BASE_SHELF_SEGMENTS; i++) {
      const zPos = shelfStartZ + i * shelfSpacing;
      createShelfSegment(rowCfg, zPos);
    }

    addLevel2InspectionZone(rowCfg.id, rowCfg.label, {
      minX: rowCfg.baseX - 3,
      maxX: rowCfg.baseX + 3,
      minZ: shelfStartZ - shelfSpacing,
      maxZ: shelfStartZ + shelfSpacing * (LEVEL2_TOTAL_SHELF_SEGMENTS + 1)
    });
  });

  if (LEVEL2_EXTRA_SHELF_SEGMENTS > 0) {
    const extraStartZ = shelfStartZ + LEVEL2_BASE_SHELF_SEGMENTS * shelfSpacing;
    shelfConfigs.forEach((rowCfg) => {
      for (let i = 0; i < LEVEL2_EXTRA_SHELF_SEGMENTS; i++) {
        const zPos = extraStartZ + i * shelfSpacing;
        createShelfSegment(rowCfg, zPos);
      }
    });
  }

  const monsterPadGeometry = new THREE.CylinderGeometry(0.85, 0.85, 0.4, 40);
  const monsterPadMaterial = new THREE.MeshStandardMaterial({ color: 0xffffff, emissive: 0xfdfdfd, emissiveIntensity: 0.2 });
  const monsterCount = 6;
  const monsterSpacing = 6;
  const monsterStartX = origin.x - ((monsterCount - 1) * monsterSpacing) / 2;
  const monsterZ = origin.z + 11;
  for (let m = 0; m < monsterCount; m++) {
    const xPos = monsterStartX + m * monsterSpacing;
    const padPosition = new THREE.Vector3(xPos, origin.y + 0.2, monsterZ);
    const pad = new THREE.Mesh(monsterPadGeometry, monsterPadMaterial);
    pad.position.copy(padPosition);
    level2State.group.add(pad);
    level2State.previewAnchors.push({
      type: "monster",
      position: padPosition.clone(),
      padIndex: m
    });
    const bonusConfig = LEVEL2_BONUS_PAD_TARGETS.find((cfg) => cfg.padIndex === m);
    if (bonusConfig) {
      level2State.previewAnchors.push({
        type: "bonus",
        position: padPosition.clone(),
        label: bonusConfig.label,
        padIndex: m
      });
    }
  }

  addLevel2InspectionZone("monster_row", "Creature Lineup", {
    minX: monsterStartX - 2,
    maxX: monsterStartX + monsterSpacing * monsterCount + 2,
    minZ: monsterZ - 2,
    maxZ: monsterZ + 4
  });

  createPrimaryWeaponRows();
  createAccessoryCorridor();
  createSurvivalPackRows();
  createOldSchoolArmory();
  createSciFiGunRows();
  createLevel2TriggerBlock();
  createLevel2Lever();
  if (SHOW_LEVEL2_ANCHOR_LABELS) {
    createLevel2AnchorLabels();
  }
  
  level2State.built = true;
  
  // NOTE: Chests are created in warpToLevel2() to ensure they're ALWAYS created reliably
  // This prevents race conditions where setTimeout might not execute
  // CRITICAL PERFORMANCE FIX: Load preview models asynchronously to avoid blocking warp function
  // Models will load in background after level is playable - this prevents 60-second timeouts
  // Hundreds of weapon/monster models were blocking the warp function and causing low FPS
  Promise.resolve().then(() => {
    loadLevel2PreviewModels();
  }).catch(err => {
    console.error("❌ [LEVEL 2] Error loading preview models:", err);
  });
  resetLevel2Progress();
  
  // CRITICAL: If we're currently in Level 2, ensure group is visible after building
  if (currentLevel === LEVEL_IDS.LEVEL2) {
    level2State.group.visible = true;
    console.log("✅ [LEVEL 2] Group visibility set to true after building (player is in Level 2)");
  }
}

function buildLevel3HuntArena() {
  if (level3State.built) return;
  level3State.group.visible = false;
  level3State.monsters = [];
  level3State.movingWalls = [];
  const origin = level3Config.origin;
  const size = level3Config.size;

  // Solid static floor (160x160) - No flickering, solid ground for development
  // CRITICAL: Use SOLID COLOR material (no texture) to ensure 100% static floor with zero flickering
  // This completely eliminates any possibility of texture animation or shared texture issues
  try {
    const floorGeometry = new THREE.PlaneGeometry(size, size);
    
    // Create a completely static solid color material - NO TEXTURE to prevent any flickering
    // Using a light gray stone color that matches the cheese-stone texture appearance
    // 🚨 CRITICAL FIX (December 30, 2025): Use MeshBasicMaterial for completely unlit ground (zero flickering)
    // MeshBasicMaterial is completely unaffected by lighting, preventing any color fluctuation
    // This matches the fix applied to Level 5 & 6 underground flickering (grass-system.js createUndergroundMesh)
    // Polygon offset prevents z-fighting with grass system's ground mesh (groundType: 'color')
    const floorMaterial = new THREE.MeshBasicMaterial({
      color: 0xaaaaaa, // Light gray stone color (solid, no texture)
      side: THREE.DoubleSide,
      polygonOffset: true,
      polygonOffsetFactor: -2,
      polygonOffsetUnits: -2
    });
    
    // CRITICAL: Mark material as completely static - no texture, no animation possible
    floorMaterial.userData = {
      isStatic: true,
      isFloorMaterial: true,
      noAnimation: true,
      noTexture: true,
      isSolidColor: true
    };
    Object.freeze(floorMaterial.userData);
    
    const floor = new THREE.Mesh(floorGeometry, floorMaterial);
    floor.rotation.x = -Math.PI / 2;
    floor.position.set(origin.x, origin.y, origin.z); // No elevation offset - solid ground
    // 🚨 CRITICAL FIX (December 30, 2025): MeshBasicMaterial doesn't support shadows
    floor.receiveShadow = false; // MeshBasicMaterial doesn't support shadows
    floor.castShadow = false; // Floor doesn't cast shadows
    
    // CRITICAL: Mark floor as completely static - no texture, no animation, no updates
    floor.userData = {
      isStaticFloor: true,
      noTextureAnimation: true,
      isLevel3Floor: true,
      materialStatic: true,
      isSolidColor: true,
      noTexture: true
    };
    Object.freeze(floor.userData);
    
    // Store floor reference for potential future use (but don't animate it)
    level3State.floor = floor;
    level3State.group.add(floor);
    
    console.log("✅ [LEVEL 3] Solid static floor created (MeshBasicMaterial - zero flickering):", {
      size: size,
      position: { x: origin.x, y: origin.y, z: origin.z },
      materialType: 'MeshBasicMaterial (completely unlit)',
      color: '0xaaaaaa (light gray stone)',
      isStatic: true,
      hasTexture: false,
      isSolidColor: true,
      materialFrozen: true,
      zeroFlickering: true,
      polygonOffset: true,
      fixApplied: 'December 30, 2025 - Matches Level 5 & 6 underground flickering fix'
    });
  } catch (floorError) {
    console.error("❌ [LEVEL 3] CRITICAL ERROR creating floor:", floorError);
    // Create a basic floor even if texture loading fails
    const floorGeometry = new THREE.PlaneGeometry(size, size);
      // 🚨 CRITICAL FIX (December 30, 2025): Use MeshBasicMaterial for fallback floor too
      const floorMaterial = new THREE.MeshBasicMaterial({
        color: 0xcccccc, // Light gray solid color
        side: THREE.DoubleSide,
        polygonOffset: true,
        polygonOffsetFactor: -2,
        polygonOffsetUnits: -2
      });
    const floor = new THREE.Mesh(floorGeometry, floorMaterial);
    floor.rotation.x = -Math.PI / 2;
    floor.position.set(origin.x, origin.y, origin.z);
    floor.receiveShadow = false; // MeshBasicMaterial doesn't support shadows
    level3State.floor = floor;
    level3State.group.add(floor);
    console.log("✅ [LEVEL 3] Basic floor created (fallback - no texture)");
  }
  
  // CRITICAL: Ensure floor was created (either normal or fallback)
  if (!level3State.floor) {
    console.error("❌ [LEVEL 3] CRITICAL: Floor was not created! Creating emergency fallback...");
    const floorGeometry = new THREE.PlaneGeometry(size, size);
    // 🚨 CRITICAL FIX (December 30, 2025): Use MeshBasicMaterial for emergency fallback floor too
    const floorMaterial = new THREE.MeshBasicMaterial({
      color: 0xcccccc,
      side: THREE.DoubleSide,
      polygonOffset: true,
      polygonOffsetFactor: -2,
      polygonOffsetUnits: -2
    });
    const floor = new THREE.Mesh(floorGeometry, floorMaterial);
    floor.rotation.x = -Math.PI / 2;
    floor.position.set(origin.x, origin.y, origin.z);
    floor.receiveShadow = false; // MeshBasicMaterial doesn't support shadows
    level3State.floor = floor;
    level3State.group.add(floor);
    console.log("✅ [LEVEL 3] Emergency fallback floor created");
  }

  // Level 1-style walls (dark like Level 1, not white like Level 2)
  // REMOVED: roomShell completely removed to allow sky to work like Level 1
  // Level 1 has no roomShell, so Levels 2, 3, 4 should also have clear sky
  // Only walls for collision are kept (via collision detection, not visual roomShell)

  // Ambient lighting (darker like Level 1)
  const ambient = new THREE.AmbientLight(0xffffff, 0.35);
  level3State.group.add(ambient);
  const directional = new THREE.DirectionalLight(0xfff2d0, 1.4);
  directional.position.set(origin.x + 60, origin.y + level3Config.wallHeight, origin.z + 10);
  directional.castShadow = true;
  // CRITICAL: Reduced shadow map resolution for better performance (1024x1024 instead of 2048x2048)
  // This reduces shadow rendering cost by 75% while maintaining acceptable quality
  directional.shadow.mapSize.set(1024, 1024);
  directional.shadow.camera.near = 10;
  directional.shadow.camera.far = 400;
  directional.shadow.camera.left = -120;
  directional.shadow.camera.right = 120;
  directional.shadow.camera.top = 120;
  directional.shadow.camera.bottom = -120;
  // CRITICAL: Optimize shadow bias to prevent flickering/doubling
  directional.shadow.bias = -0.0001; // Reduce shadow acne
  directional.shadow.normalBias = 0.02; // Reduce shadow flickering
  level3State.group.add(directional);
  const rimLight = new THREE.PointLight(0xff7b39, 0.65, 260);
  rimLight.position.set(origin.x - 50, origin.y + 20, origin.z - 40);
  // CRITICAL: Disable shadow casting on rim light to reduce flickering/doubling
  // Only main directional light casts shadows for better performance and no flickering
  rimLight.castShadow = false;
  level3State.group.add(rimLight);
  const backLight = new THREE.PointLight(0x57c1ff, 0.55, 260);
  backLight.position.set(origin.x + 55, origin.y + 18, origin.z + 45);
  // CRITICAL: Disable shadow casting on back light to reduce flickering/doubling
  // Only main directional light casts shadows for better performance and no flickering
  backLight.castShadow = false;
  level3State.group.add(backLight);

  // Create hidden cheese stone trigger block
  createLevel3TriggerBlock();
  createLevel3MovingWalls();

  level3State.built = true;
  
  // Create Level 3 chests (after built flag set, ensure chestSystem is initialized)
  // CRITICAL: Small delay to ensure chestSystem is initialized (similar to Level 2 pattern)
  setTimeout(async () => {
    // CRITICAL: Load opened chests from database before creating chests (January 4, 2026)
    // This ensures chests appear as opened when warping back to a level
    if (resolvedDiscordId && chestSystem) {
      console.log("📥 [LEVEL 3] Loading opened chests from database...");
      await chestSystem.loadOpenedChests(resolvedDiscordId, API_BASE_URL);
    }
    createLevel3Chests();
  }, 100);
  
  resetLevel3Progress();
  console.log("🏹 [LEVEL 3] Hunt Arena built - 160x160 cheese stone floor ready.");
}

function createLevel3MovingWalls() {
  level3State.movingWalls = level3State.movingWalls || [];
  const origin = level3Config.origin;

  // Different colors for each wall for debugging
  const wallColors = [
    0xff0000, // Red - Wall 1 (X-axis, left)
    0x00ff00, // Green - Wall 2 (X-axis, right)
    0x0000ff, // Blue - Wall 3 (Z-axis, back)
    0xffff00  // Yellow - Wall 4 (Z-axis, front)
  ];

  LEVEL3_MOVING_WALLS.forEach((spec, index) => {
    const width = spec.size.width;
    const depth = spec.size.depth;
    const height = spec.size.height ?? (level3Config.wallHeight * 0.6);
    const geometry = new THREE.BoxGeometry(width, height, depth);
    
    // Each wall gets a different color for debugging
    const wallColor = wallColors[index] || 0x1d2338;
    
    // Load texture for water effect (each wall gets its own texture instance)
    // FIX: Use resolveAssetPath for texture path
    const texture = loadTexture(resolveAssetPath("textures/blocks/cheese-stone.png"));
    texture.wrapS = THREE.RepeatWrapping;
    texture.wrapT = THREE.RepeatWrapping;
    texture.repeat.set(2, 2); // Repeat texture for better effect
    
    const material = new THREE.MeshStandardMaterial({
      color: wallColor,
      map: texture,
      metalness: 0.4,
      roughness: 0.35,
      emissive: wallColor,
      emissiveIntensity: 0.15 // Subtle glow to make colors more visible
    });
    
    const wall = new THREE.Mesh(geometry, material);
    const worldX = origin.x + spec.offset.x;
    const worldZ = origin.z + spec.offset.z;
    wall.position.set(worldX, origin.y + height / 2, worldZ);
    wall.castShadow = true;
    wall.receiveShadow = true;
    wall.userData = wall.userData || {};
    wall.userData.halfWidth = width / 2;
    wall.userData.halfDepth = depth / 2;
    wall.userData.wallIndex = index; // Store index for debugging
    wall.userData.wallColor = wallColor; // Store color for reference
    wall.userData.uvOffset = { x: 0, y: 0 }; // For water wobble effect
    wall.userData.wobbleTime = 0; // Animation time for wobble

    level3State.group.add(wall);
    level3State.movingWalls.push(wall);
    configureLevel3WallMovement(wall, spec);
    console.log(`🧱 [LEVEL 3] Moving wall ${index + 1} created`, {
      axis: spec.axis,
      amplitude: spec.amplitude,
      speed: spec.speed,
      color: `#${wallColor.toString(16).padStart(6, '0')}`
    });
  });
}

function resetLevel3MovingWalls() {
  if (!level3State.movingWalls || level3State.movingWalls.length === 0) return;
  const origin = level3Config.origin;
  level3State.movingWalls.forEach((wall, index) => {
    const spec = LEVEL3_MOVING_WALLS[index];
    if (!spec) return;
    const height = spec.size.height ?? (level3Config.wallHeight * 0.6);
    const baseX = origin.x + spec.offset.x;
    const baseZ = origin.z + spec.offset.z;
    wall.position.set(baseX, origin.y + height / 2, baseZ);
    configureLevel3WallMovement(wall, spec);
  });
}

function updateLevel3MovingWalls(delta) {
  if (!level3State.movingWalls || level3State.movingWalls.length === 0) return;

  level3State.movingWalls.forEach((wall) => {
    const movement = wall.userData?.movement;
    if (!movement) return;

    if (movement.delay > 0) {
      movement.delay = Math.max(0, movement.delay - delta);
      return;
    }

    if (movement.max === movement.min) return;

    movement.position = (movement.position ?? movement.base) + movement.direction * movement.speed * delta;
    if (movement.position > movement.max) {
      movement.position = movement.max;
      movement.direction = -1;
    } else if (movement.position < movement.min) {
      movement.position = movement.min;
      movement.direction = 1;
    }

    const targetValue = movement.position;
    if (movement.axis === "x") {
      wall.position.x = targetValue;
    } else {
      wall.position.z = targetValue;
    }

    // Water wobble effect on texture (OPTIMIZED: Throttle texture updates to reduce GPU load)
    // CRITICAL: Only animate wall textures, never the floor texture
    if (wall.material && wall.material.map && !wall.userData.isStaticFloor) {
      wall.userData.wobbleTime = (wall.userData.wobbleTime || 0) + delta;
      
      // CRITICAL LEVEL 3 OPTIMIZATION: Further reduce texture updates to prevent flickering
      // Only update texture every 8 frames (reduces GPU texture uploads by 87.5%)
      // This prevents texture update conflicts with character rendering that cause flickering
      wall.userData.wobbleUpdateCounter = (wall.userData.wobbleUpdateCounter || 0) + 1;
      if (wall.userData.wobbleUpdateCounter >= 8) {
        wall.userData.wobbleUpdateCounter = 0;
        
        const wobbleSpeed = 0.5; // Speed of wobble animation
        const wobbleAmount = 0.02; // Amount of UV offset (subtle water effect)
        
        // Create a gentle sine wave wobble effect
        // Different phase for each wall based on index for variety
        const phase = (wall.userData.wallIndex || 0) * Math.PI * 0.5;
        const time = wall.userData.wobbleTime * wobbleSpeed + phase;
        
        // Offset UV coordinates for water-like distortion
        if (!wall.userData.uvOffset) {
          wall.userData.uvOffset = { x: 0, y: 0 };
        }
        const newOffsetX = Math.sin(time) * wobbleAmount;
        const newOffsetY = Math.cos(time * 1.3) * wobbleAmount;
        
        // Only update if offset changed significantly (reduces unnecessary GPU uploads)
        const offsetThreshold = 0.001;
        if (Math.abs(newOffsetX - wall.userData.uvOffset.x) > offsetThreshold ||
            Math.abs(newOffsetY - wall.userData.uvOffset.y) > offsetThreshold) {
          wall.userData.uvOffset.x = newOffsetX;
          wall.userData.uvOffset.y = newOffsetY;
          
          // Apply UV offset to texture
          if (wall.material.map) {
            wall.material.map.offset.x = wall.userData.uvOffset.x;
            wall.material.map.offset.y = wall.userData.uvOffset.y;
            wall.material.map.needsUpdate = true;
          }
        }
      }
    }
  });
}

function configureLevel3WallMovement(wall, spec) {
  if (!wall) return;
  const axis = spec.axis === "z" ? "z" : "x";
  const origin = level3Config.origin;
  const halfArena = level3Config.size / 2;
  const halfWidth = wall.userData?.halfWidth || spec.size.width / 2;
  const halfDepth = wall.userData?.halfDepth || spec.size.depth / 2;
  const baseValue = axis === "x" ? wall.position.x : wall.position.z;
  const rawAmplitude = typeof spec.amplitude === "number" ? spec.amplitude : 20;
  const positiveLimit =
    (axis === "x" ? origin.x : origin.z) + halfArena - (axis === "x" ? halfWidth : halfDepth);
  const negativeLimit =
    (axis === "x" ? origin.x : origin.z) - halfArena + (axis === "x" ? halfWidth : halfDepth);
  const positiveAllowance = Math.min(rawAmplitude, Math.max(0, positiveLimit - baseValue));
  const negativeAllowance = Math.min(rawAmplitude, Math.max(0, baseValue - negativeLimit));
  const movement = {
    axis,
    base: baseValue,
    position: baseValue,
    min: baseValue - negativeAllowance,
    max: baseValue + positiveAllowance,
    speed: spec.speed,
    direction: Math.random() > 0.5 ? 1 : -1,
    delay: spec.delay || 0
  };
  wall.userData = wall.userData || {};
  wall.userData.movement = movement;
}

function handleLevel3CrushCheck(delta) {
  if (!level3State.movingWalls || level3State.movingWalls.length < 2) {
    level3State.crushTimer = Math.max(0, level3State.crushTimer - delta);
    return false;
  }
  const crushInfo = detectLevel3CrushZone();
  if (!crushInfo.crushed) {
    level3State.crushTimer = Math.max(0, level3State.crushTimer - delta);
    return false;
  }
  level3State.crushTimer += delta;
  if (level3State.crushTimer >= LEVEL3_CRUSH_TIME_REQUIRED) {
    triggerLevel3CrushDeath(crushInfo);
    return true;
  }
  return false;
}

function detectLevel3CrushZone() {
  const playerBounds = getPlayerHorizontalBounds();
  
  // PRIMARY CHECK: Check X-axis crush (left-right walls)
  const crushX = computeLevel3AxisCrushInfo("x", playerBounds);
  if (crushX.crushed) {
    console.log("💥 [LEVEL 3] X-axis crush detected", {
      gap: crushX.gap,
      negWall: crushX.negWall?.position,
      posWall: crushX.posWall?.position,
      playerPos: { x: playerBounds.centerX, z: playerBounds.centerZ }
    });
    return crushX;
  }
  
  // PRIMARY CHECK: Check Z-axis crush (front-back walls)
  const crushZ = computeLevel3AxisCrushInfo("z", playerBounds);
  if (crushZ.crushed) {
    console.log("💥 [LEVEL 3] Z-axis crush detected", {
      gap: crushZ.gap,
      negWall: crushZ.negWall?.position,
      posWall: crushZ.posWall?.position,
      playerPos: { x: playerBounds.centerX, z: playerBounds.centerZ }
    });
    return crushZ;
  }

  // SECONDARY CHECK: Corner crush (both axes simultaneously)
  const cornerCrush = evaluateLevel3CornerCrush(crushX, crushZ, playerBounds);
  if (cornerCrush.crushed) {
    console.log("💥 [LEVEL 3] Corner crush detected", {
      xGap: cornerCrush.xGap,
      zGap: cornerCrush.zGap,
      playerPos: { x: playerBounds.centerX, z: playerBounds.centerZ }
    });
    return cornerCrush;
  }

  // TERTIARY CHECK: Comprehensive pair check (catches edge cases)
  const pairCrush = checkAllWallPairsForCrush(playerBounds);
  if (pairCrush.crushed) {
    console.log("💥 [LEVEL 3] Wall pair crush detected", pairCrush);
    return pairCrush;
  }

  return { crushed: false };
}

function computeLevel3AxisCrushInfo(axis, playerBounds) {
  if (!level3State.movingWalls || level3State.movingWalls.length < 2) {
    return { crushed: false };
  }

  const radius = playerBounds.radius;
  const playerMin = axis === "x" ? playerBounds.minX : playerBounds.minZ;
  const playerMax = axis === "x" ? playerBounds.maxX : playerBounds.maxZ;
  const playerCenter = axis === "x" ? playerBounds.centerX : playerBounds.centerZ;
  const perpMin = axis === "x" ? playerBounds.minZ : playerBounds.minX;
  const perpMax = axis === "x" ? playerBounds.maxZ : playerBounds.maxX;

  // Find ALL walls that overlap the player's perpendicular span
  const candidateWalls = [];
  
  level3State.movingWalls.forEach((wall) => {
    const halfWidth = wall.userData?.halfWidth || 0;
    const halfDepth = wall.userData?.halfDepth || 0;
    const xMin = wall.position.x - halfWidth;
    const xMax = wall.position.x + halfWidth;
    const zMin = wall.position.z - halfDepth;
    const zMax = wall.position.z + halfDepth;

    // Check if wall overlaps player's perpendicular span
    const wallPerpMin = axis === "x" ? zMin : xMin;
    const wallPerpMax = axis === "x" ? zMax : xMax;
    const overlapsPerp = perpMax >= wallPerpMin && perpMin <= wallPerpMax;

    if (overlapsPerp) {
      const wallAxisMin = axis === "x" ? xMin : zMin;
      const wallAxisMax = axis === "x" ? xMax : zMax;
      const wallAxisCenter = (wallAxisMin + wallAxisMax) * 0.5;
      
      candidateWalls.push({
        wall: wall,
        min: wallAxisMin,
        max: wallAxisMax,
        center: wallAxisCenter,
        surface: wallAxisCenter < playerCenter ? wallAxisMax : wallAxisMin // Surface facing player
      });
    }
  });

  if (candidateWalls.length < 2) {
    return { crushed: false };
  }

  // Find the closest walls on each side of the player
  let negWall = null;
  let posWall = null;
  let negSurface = -Infinity;
  let posSurface = Infinity;

  candidateWalls.forEach((candidate) => {
    // Wall is on the negative side (left/back)
    if (candidate.max <= playerCenter && candidate.max > negSurface) {
      negSurface = candidate.max;
      negWall = candidate.wall;
    }
    // Wall is on the positive side (right/front)
    if (candidate.min >= playerCenter && candidate.min < posSurface) {
      posSurface = candidate.min;
      posWall = candidate.wall;
    }
  });

  // If we don't have walls on both sides, check for walls that are already past the player
  // but could still crush if another wall is approaching
  if (!negWall || !posWall) {
    // Find walls that overlap the player's bounds (even if past center)
    candidateWalls.forEach((candidate) => {
      const overlapsPlayer = candidate.max > playerMin && candidate.min < playerMax;
      
      if (overlapsPlayer) {
        // Wall is mostly on negative side
        if (candidate.max <= playerMax && (!negWall || candidate.max > negSurface)) {
          negSurface = candidate.max;
          negWall = candidate.wall;
        }
        // Wall is mostly on positive side
        if (candidate.min >= playerMin && (!posWall || candidate.min < posSurface)) {
          posSurface = candidate.min;
          posWall = candidate.wall;
        }
      }
    });
  }

  // Calculate available gap
  const availableGap = posSurface - negSurface - (radius * 2);
  
  // Check if player is actually between the surfaces
  const playerBetween = playerMax > negSurface && playerMin < posSurface;
  
  // Crush condition: walls on both sides AND gap is too small AND player is between them
  const crushed =
    negWall &&
    posWall &&
    negWall !== posWall && // Must be different walls
    playerBetween &&
    availableGap <= LEVEL3_CRUSH_GAP_THRESHOLD;

  return { 
    crushed, 
    axis, 
    gap: availableGap, 
    negWall, 
    posWall, 
    negSurface, 
    posSurface,
    candidateCount: candidateWalls.length
  };
}

let level3GameOverScreen = null;

function triggerLevel3CrushDeath(info) {
  if (level3State.crushActive) return;
  level3State.crushActive = true;
  level3State.crushTimer = 0;
  console.warn("💥 [LEVEL 3] Player crushed between walls", info);
  
  // Trigger death animation if player model is loaded (Mouse character only)
  if (playerModelModule && playerModelModule.isLoaded() && playerModelModule.isMouseCharacter()) {
    const deathTriggered = playerModelModule.triggerAnimation('death', true);
    if (deathTriggered) {
      console.log("💀 [LEVEL 3] Death animation triggered for crush death");
    }
  } else if (playerCharacterModel && useGLTFCharacter && playerCharacterAnimations['death']) {
    // Fallback: Use legacy animation system if PlayerModel module not available
    const deathAction = playerCharacterAnimations['death'];
    if (deathAction) {
      // Stop all other animations
      Object.keys(playerCharacterAnimations).forEach(animKey => {
        const action = playerCharacterAnimations[animKey];
        if (action && action !== deathAction && action.isRunning()) {
          action.setEffectiveWeight(0.0);
          action.stop();
        }
      });
      
      // Play death animation
      deathAction.reset();
      deathAction.setEffectiveTimeScale(1.0);
      deathAction.setLoop(THREE.LoopOnce, 1);
      deathAction.clampWhenFinished = true;
      deathAction.enabled = true;
      deathAction.setEffectiveWeight(1.0);
      deathAction.play();
      window.currentCharacterAnimation = 'death';
      console.log("💀 [LEVEL 3] Death animation triggered (legacy system)");
    }
  }
  
  // CRITICAL: Delay game over screen to let death animation play first
  // Death animation needs time to be visible before pause
  setTimeout(() => {
    // Show spectacular game over screen
    showLevel3GameOverScreen();
  }, 1500); // 1.5 second delay to show death animation (was immediate)
}

function showLevel3GameOverScreen() {
  // Use GUI System if available
  if (guiSystem && typeof guiSystem.showGameOverScreen === 'function') {
    // Determine death type from context
    let deathType = 'crushLevel3';
    if (level1State && level1State.bearTrapTriggered) {
      deathType = 'bearTrapLevel1';
    } else if (level2State && level2State.bearTrapTriggered) {
      deathType = 'bearTrapLevel2';
    }
    guiSystem.showGameOverScreen({ deathType });
    return;
  }
  
  // Legacy fallback
  // Hide any existing game over screen
  hideLevel3GameOverScreen(false);
  
  // Hide completion screen if showing (shouldn't happen, but safety check)
  if (level3CompletionScreen && document.body.contains(level3CompletionScreen)) {
    hideLevel3CompletionScreen(false);
  }
  
  // Hide level selector if open
  if (levelSelectorScreen && document.body.contains(levelSelectorScreen)) {
    hideLevelSelector();
  }
  
  // Pause the game
  if (!isGamePaused) {
    togglePause(true);
  }
  
  // Play death sound (if available) or use a dramatic sound
  // You can add a specific crush death sound here later
  
  // Create game over screen overlay
  level3GameOverScreen = document.createElement("div");
  Object.assign(level3GameOverScreen.style, {
    position: "fixed",
    top: 0,
    left: 0,
    width: "100%",
    height: "100%",
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
    flexDirection: "column",
    gap: "18px",
    background: "rgba(0, 0, 0, 0.95)",
    backdropFilter: "blur(12px)",
    zIndex: "1005",
    color: "#fef3c7",
    fontFamily: "Montserrat, Arial, sans-serif",
    pointerEvents: "auto",
    cursor: "default",
    animation: "fadeIn 0.3s ease-out"
  });

  // Add fade-in animation if not exists
  if (!document.getElementById("gameOverFadeInStyle")) {
    const style = document.createElement("style");
    style.id = "gameOverFadeInStyle";
    style.textContent = `
      @keyframes fadeIn {
        from { opacity: 0; }
        to { opacity: 1; }
      }
      @keyframes shake {
        0%, 100% { transform: translateX(0); }
        25% { transform: translateX(-10px); }
        75% { transform: translateX(10px); }
      }
    `;
    document.head.appendChild(style);
  }

  const panel = document.createElement("div");
  Object.assign(panel.style, {
    background: "linear-gradient(135deg, rgba(127, 29, 29, 0.98), rgba(69, 10, 10, 0.98))",
    border: "3px solid rgba(239, 68, 68, 0.8)",
    borderRadius: "16px",
    padding: "40px 48px",
    maxWidth: "520px",
    textAlign: "center",
    boxShadow: "0 12px 48px rgba(239, 68, 68, 0.4), 0 0 60px rgba(239, 68, 68, 0.2)",
    animation: "shake 0.5s ease-out"
  });

  // Dramatic title
  const title = document.createElement("h2");
  title.textContent = "💥 CRUSHED!";
  Object.assign(title.style, {
    margin: "0 0 8px 0",
    fontSize: "42px",
    fontWeight: "900",
    color: "#fef3c7",
    textShadow: "0 4px 16px rgba(239, 68, 68, 0.8), 0 0 24px rgba(239, 68, 68, 0.6)",
    letterSpacing: "2px"
  });
  panel.appendChild(title);

  // Subtitle
  const subtitle = document.createElement("h3");
  subtitle.textContent = "GAME OVER";
  Object.assign(subtitle.style, {
    margin: "0 0 20px 0",
    fontSize: "24px",
    fontWeight: "700",
    color: "#fca5a5",
    textShadow: "0 2px 8px rgba(239, 68, 68, 0.6)",
    letterSpacing: "4px"
  });
  panel.appendChild(subtitle);

  // Message
  const message = document.createElement("p");
  message.textContent = "The moving walls have crushed you! The labyrinth proved too dangerous this time.";
  Object.assign(message.style, {
    margin: "0 0 32px 0",
    fontSize: "16px",
    lineHeight: "1.6",
    color: "#fecaca"
  });
  panel.appendChild(message);

  // Button container
  const buttonContainer = document.createElement("div");
  Object.assign(buttonContainer.style, {
    display: "flex",
    flexDirection: "column",
    gap: "14px",
    width: "100%"
  });

  const createButton = (text, onClick, isPrimary = false) => {
    const btn = document.createElement("button");
    btn.textContent = text;
    Object.assign(btn.style, {
      padding: "14px 28px",
      fontSize: "17px",
      fontWeight: "600",
      border: "none",
      borderRadius: "10px",
      cursor: "pointer",
      transition: "all 0.2s",
      background: isPrimary
        ? "linear-gradient(135deg, #ef4444, #dc2626)"
        : "rgba(239, 68, 68, 0.25)",
      color: "#fef3c7",
      border: `2px solid ${isPrimary ? "#f87171" : "rgba(239, 68, 68, 0.5)"}`,
      boxShadow: isPrimary ? "0 4px 12px rgba(239, 68, 68, 0.3)" : "none"
    });
    btn.onmouseenter = () => {
      btn.style.transform = "scale(1.05)";
      btn.style.boxShadow = isPrimary 
        ? "0 6px 20px rgba(239, 68, 68, 0.5)" 
        : "0 4px 12px rgba(239, 68, 68, 0.3)";
    };
    btn.onmouseleave = () => {
      btn.style.transform = "scale(1)";
      btn.style.boxShadow = isPrimary 
        ? "0 4px 12px rgba(239, 68, 68, 0.3)" 
        : "none";
    };
    btn.onclick = onClick;
    return btn;
  };

  // Try Again / Restart Level 1 button (primary) - restart current level
  if (level1State.bearTrapDeathActive) {
    // From Level 1 bear trap: Show single "Restart Level 1" button
    buttonContainer.appendChild(
      createButton("🔄 Restart Level 1", () => {
        hideLevel3GameOverScreen();
        level1State.bearTrapDeathActive = false;
        level3State.crushActive = false;
        restartLevel1();
      }, true)
    );
  } else if (level2State.bearTrapDeathActive) {
    // From Level 2 bear trap: Show "Restart Level 2" and "Go to Level 1" buttons
    buttonContainer.appendChild(
      createButton("🔄 Restart Level 2", () => {
        hideLevel3GameOverScreen();
        level2State.bearTrapDeathActive = false;
        level3State.crushActive = false;
        restartLevel2();
      }, true)
    );
    
    buttonContainer.appendChild(
      createButton("🏠 Go to Level 1", () => {
        hideLevel3GameOverScreen();
        level2State.bearTrapDeathActive = false;
        level3State.crushActive = false;
        restartLevel1();
      })
    );
  } else {
    // From Level 3 crush: Show "Try Again" and "Return to Level 1" buttons
    buttonContainer.appendChild(
      createButton("🔄 Try Again", () => {
        hideLevel3GameOverScreen();
        restartLevel3();
        level3State.crushActive = false;
      }, true)
    );
    
    // Level Select button (only show for Level 3 crush deaths)
    buttonContainer.appendChild(
      createButton("🎮 Level Select", () => {
        hideLevel3GameOverScreen();
        // Temporarily enable God Mode to access level selector
        const wasGodMode = godMode;
        if (!godMode) {
          godMode = true;
          localStorage.setItem("cheese_temple_god_mode", "true");
        }
        // Open level selector
        showLevelSelector();
        // Restore previous God Mode state after selector closes (handled in hideLevelSelector)
        level3State.crushActive = false;
      })
    );
    
    // Return to Level 1 button (only for Level 3 crush deaths)
    buttonContainer.appendChild(
      createButton("🏠 Return to Level 1", () => {
        hideLevel3GameOverScreen();
        level3State.crushActive = false;
        restartLevel1();
      })
    );
  }

  panel.appendChild(buttonContainer);
  level3GameOverScreen.appendChild(panel);
  document.body.appendChild(level3GameOverScreen);
}

function hideLevel3GameOverScreen(clearFlag = true) {
  // Use GUI System if available
  if (guiSystem && typeof guiSystem.hideGameOverScreen === 'function') {
    guiSystem.hideGameOverScreen(clearFlag);
    return;
  }
  
  // Legacy fallback
  if (level3GameOverScreen && document.body.contains(level3GameOverScreen)) {
    document.body.removeChild(level3GameOverScreen);
    level3GameOverScreen = null;
  }
  if (clearFlag) {
    level3State.crushActive = false;
  }
}

function getPlayerHorizontalBounds() {
  const centerX = (playerCollider.start.x + playerCollider.end.x) * 0.5;
  const centerZ = (playerCollider.start.z + playerCollider.end.z) * 0.5;
  const radius = PLAYER_RADIUS;
  return {
    centerX,
    centerZ,
    minX: centerX - radius,
    maxX: centerX + radius,
    minZ: centerZ - radius,
    maxZ: centerZ + radius,
    radius
  };
}

function isPlayerOverlapBetweenSurfaces(axis, negSurface, posSurface, playerBounds) {
  const minCoord = axis === "x" ? playerBounds.minX : playerBounds.minZ;
  const maxCoord = axis === "x" ? playerBounds.maxX : playerBounds.maxZ;
  return maxCoord > negSurface && minCoord < posSurface;
}

function checkAllWallPairsForCrush(playerBounds) {
  // This function checks ALL possible wall pairs to catch edge cases
  // where the primary axis checks might miss complex scenarios
  
  if (!level3State.movingWalls || level3State.movingWalls.length < 2) {
    return { crushed: false };
  }

  const radius = playerBounds.radius;
  const playerMinX = playerBounds.minX;
  const playerMaxX = playerBounds.maxX;
  const playerMinZ = playerBounds.minZ;
  const playerMaxZ = playerBounds.maxZ;

  // Get all walls that could potentially crush the player
  const relevantWalls = [];
  
  level3State.movingWalls.forEach((wall) => {
    const halfWidth = wall.userData?.halfWidth || 0;
    const halfDepth = wall.userData?.halfDepth || 0;
    const xMin = wall.position.x - halfWidth;
    const xMax = wall.position.x + halfWidth;
    const zMin = wall.position.z - halfDepth;
    const zMax = wall.position.z + halfDepth;

    // Check if wall overlaps player's bounding box (with some margin)
    const overlapsX = xMax > playerMinX - radius && xMin < playerMaxX + radius;
    const overlapsZ = zMax > playerMinZ - radius && zMin < playerMaxZ + radius;

    if (overlapsX || overlapsZ) {
      relevantWalls.push({
        wall: wall,
        xMin, xMax, zMin, zMax,
        axis: wall.userData?.movement?.axis || "x"
      });
    }
  });

  if (relevantWalls.length < 2) {
    return { crushed: false };
  }

  // Check all pairs of walls for crush scenarios
  for (let i = 0; i < relevantWalls.length; i++) {
    for (let j = i + 1; j < relevantWalls.length; j++) {
      const wall1 = relevantWalls[i];
      const wall2 = relevantWalls[j];

      // Skip if walls are on different axes (handled by corner crush)
      if (wall1.axis !== wall2.axis) continue;

      // Check X-axis pair
      if (wall1.axis === "x") {
        // Check if walls are on opposite sides of player
        const wall1Right = wall1.xMax <= playerBounds.centerX;
        const wall2Left = wall2.xMin >= playerBounds.centerX;
        const wall2Right = wall2.xMax <= playerBounds.centerX;
        const wall1Left = wall1.xMin >= playerBounds.centerX;

        // Check if walls overlap player's Z span
        const bothOverlapZ = 
          (wall1.zMax > playerMinZ && wall1.zMin < playerMaxZ) &&
          (wall2.zMax > playerMinZ && wall2.zMin < playerMaxZ);

        if (bothOverlapZ && ((wall1Right && wall2Left) || (wall2Right && wall1Left))) {
          const leftWall = wall1Right ? wall1 : wall2;
          const rightWall = wall1Right ? wall2 : wall1;
          const gap = rightWall.xMin - leftWall.xMax - (radius * 2);

          if (gap <= LEVEL3_CRUSH_GAP_THRESHOLD) {
            // Verify player is actually between these walls
            const playerBetween = 
              playerMaxX > leftWall.xMax && 
              playerMinX < rightWall.xMin;

            if (playerBetween) {
              return {
                crushed: true,
                axis: "x",
                gap: gap,
                negWall: leftWall.wall,
                posWall: rightWall.wall,
                negSurface: leftWall.xMax,
                posSurface: rightWall.xMin,
                method: "pair-check"
              };
            }
          }
        }
      }

      // Check Z-axis pair
      if (wall1.axis === "z") {
        // Check if walls are on opposite sides of player
        const wall1Back = wall1.zMax <= playerBounds.centerZ;
        const wall2Front = wall2.zMin >= playerBounds.centerZ;
        const wall2Back = wall2.zMax <= playerBounds.centerZ;
        const wall1Front = wall1.zMin >= playerBounds.centerZ;

        // Check if walls overlap player's X span
        const bothOverlapX = 
          (wall1.xMax > playerMinX && wall1.xMin < playerMaxX) &&
          (wall2.xMax > playerMinX && wall2.xMin < playerMaxX);

        if (bothOverlapX && ((wall1Back && wall2Front) || (wall2Back && wall1Front))) {
          const backWall = wall1Back ? wall1 : wall2;
          const frontWall = wall1Back ? wall2 : wall1;
          const gap = frontWall.zMin - backWall.zMax - (radius * 2);

          if (gap <= LEVEL3_CRUSH_GAP_THRESHOLD) {
            // Verify player is actually between these walls
            const playerBetween = 
              playerMaxZ > backWall.zMax && 
              playerMinZ < frontWall.zMin;

            if (playerBetween) {
              return {
                crushed: true,
                axis: "z",
                gap: gap,
                negWall: backWall.wall,
                posWall: frontWall.wall,
                negSurface: backWall.zMax,
                posSurface: frontWall.zMin,
                method: "pair-check"
              };
            }
          }
        }
      }
    }
  }

  return { crushed: false };
}

function evaluateLevel3CornerCrush(crushX, crushZ, playerBounds) {
  // Need walls on both axes for corner crush
  if (!crushX.negWall || !crushX.posWall || !crushZ.negWall || !crushZ.posWall) {
    return { crushed: false };
  }

  // Check if player is actually in the corner zone (between walls on both axes)
  const playerBetweenX = playerBounds.maxX > crushX.negSurface && playerBounds.minX < crushX.posSurface;
  const playerBetweenZ = playerBounds.maxZ > crushZ.negSurface && playerBounds.minZ < crushZ.posSurface;

  if (!playerBetweenX || !playerBetweenZ) {
    return { crushed: false };
  }

  // Calculate gaps on both axes
  const xGap = crushX.posSurface - crushX.negSurface - (playerBounds.radius * 2);
  const zGap = crushZ.posSurface - crushZ.negSurface - (playerBounds.radius * 2);

  // Check if both axes are tight enough to crush
  // Use a slightly larger threshold for corner crushes since both axes are involved
  const xTight = xGap <= LEVEL3_CORNER_CRUSH_GAP_THRESHOLD;
  const zTight = zGap <= LEVEL3_CORNER_CRUSH_GAP_THRESHOLD;

  // Also check if player is being squeezed from both sides on each axis
  const xSqueezed = 
    (playerBounds.maxX - crushX.negSurface <= PLAYER_RADIUS * 1.5) &&
    (crushX.posSurface - playerBounds.minX <= PLAYER_RADIUS * 1.5);
  
  const zSqueezed = 
    (playerBounds.maxZ - crushZ.negSurface <= PLAYER_RADIUS * 1.5) &&
    (crushZ.posSurface - playerBounds.minZ <= PLAYER_RADIUS * 1.5);

  // Corner crush if both axes are tight OR both axes are squeezing the player
  if ((xTight && zTight) || (xSqueezed && zSqueezed)) {
    return {
      crushed: true,
      axis: "corner",
      gap: Math.max(xGap, zGap),
      negWall: [crushX.negWall, crushZ.negWall],
      posWall: [crushX.posWall, crushZ.posWall],
      negSurface: [crushX.negSurface, crushZ.negSurface],
      posSurface: [crushX.posSurface, crushZ.posSurface],
      xGap: xGap,
      zGap: zGap,
      corner: true
    };
  }

  return { crushed: false };
}

function createLevel3TriggerBlock() {
  const blockSize = 1;
  const geometry = new THREE.BoxGeometry(blockSize, blockSize, blockSize);
  // FIX: Use resolveAssetPath for cheese-stone.png texture
  const texture = loadTexture(resolveAssetPath("textures/blocks/cheese-stone.png"));
  // Use MeshLambertMaterial like Level 2 trigger block (but without yellow emissive)
  const material = new THREE.MeshLambertMaterial({
    map: texture,
    emissive: new THREE.Color(0x000000), // No yellow glow - normal texture
    emissiveIntensity: 0.0
  });
  const triggerBlock = new THREE.Mesh(geometry, material);
  triggerBlock.scale.set(1.4, 0.35, 1.4); // Same scale as Level 2
  
  // Position block same as Level 2: blockHeight = 0.35, center at floorY + (blockHeight / 2) + 0.05
  const blockHeight = blockSize * 0.35; // Scaled height = 0.35
  const floorY = level3Config.origin.y; // Floor is at y: 0
  const blockCenterY = floorY + (blockHeight / 2) + 0.05; // Center at 0.225, top at 0.4 (same as Level 2)
  
  triggerBlock.position.set(
    level3Config.origin.x - 20,
    blockCenterY,
    level3Config.origin.z - 30
  );
  triggerBlock.visible = true;
  triggerBlock.userData.isTrigger = true;
  level3State.group.add(triggerBlock);
  level3RiddleState.triggerBlock = triggerBlock;

  // Visual clone for animation (same as Level 2)
  const visualMaterial = material.clone();
  const visualBlock = new THREE.Mesh(geometry.clone(), visualMaterial);
  visualBlock.scale.copy(triggerBlock.scale);
  visualBlock.position.copy(triggerBlock.position);
  visualBlock.userData.restY = visualBlock.position.y;
  visualBlock.userData.pressedY = visualBlock.position.y - 0.2;
  visualBlock.userData.lerpSpeed = 6;
  level3State.group.add(visualBlock);
  level3RiddleState.triggerBlockVisual = visualBlock;
  level3RiddleState.triggerBlockTargetY = visualBlock.userData.restY;

  // Hide the collider block, show only the visual
  triggerBlock.visible = false;
  console.log("🧩 [LEVEL 3] Hidden cheese stone trigger block created at:", {
    x: triggerBlock.position.x.toFixed(2),
    y: triggerBlock.position.y.toFixed(2),
    z: triggerBlock.position.z.toFixed(2),
    blockTopY: (triggerBlock.position.y + blockHeight / 2).toFixed(2),
    floorY: floorY.toFixed(2)
  });
}

function resetLevel3Progress() {
  level3RiddleState.step0Complete = false;
  level3RiddleState.step0StandingSoundPlayed = false;
  level3RiddleState.triggerBlockTimer = 0;
  level3RiddleState.step0TraitUnlocked = false;
  level3RiddleState.currentStep = 0;
  level3RiddleState.firstMonsterSpawned = false;
  level3RiddleState.monstersCaught = 0;
  level3RiddleState.currentMonsterIndex = 0;
  level3RiddleState.step1TraitUnlocked = false;
  level3RiddleState.step2TraitUnlocked = false;
  // CRITICAL: Reset spawning flag to allow new monsters after reset
  isSpawningLevel3Monster = false;
  if (level3RiddleState.triggerBlock) {
    level3RiddleState.triggerBlock.visible = false;
  }
  if (level3RiddleState.triggerBlockVisual) {
    level3RiddleState.triggerBlockVisual.visible = true;
    const restY = level3RiddleState.triggerBlockVisual.userData?.restY ?? level3RiddleState.triggerBlockVisual.position.y;
    level3RiddleState.triggerBlockVisual.position.y = restY;
    level3RiddleState.triggerBlockTargetY = restY;
  }
  // Clear all monsters
  level3State.monsters.forEach((monster) => {
    if (monster.mesh && monster.mesh.parent) {
      monster.mesh.parent.remove(monster.mesh);
    }
    if (monster.mixer) {
      monster.mixer.stopAllAction();
    }
  });
  level3State.monsters = [];
  if (level3State.portal) {
    level3State.portal.visible = false;
  }
  level3State.portalActive = false;
  level3State.completionScreenShown = false;
  level3State.crushActive = false;
  level3State.crushTimer = 0;
  resetLevel3MovingWalls();
  
  // CRITICAL: Reset intro state so intro toast can show again
  level3State.introShown = false;
  if (level3State.introToastElement && document.body.contains(level3State.introToastElement)) {
    document.body.removeChild(level3State.introToastElement);
    level3State.introToastElement = null;
  }
}

// CRITICAL: Flag to prevent multiple simultaneous monster spawns (prevents continuous loading)
let isSpawningLevel3Monster = false;

async function spawnLevel3Monster(monsterPath) {
  // CRITICAL: Prevent multiple simultaneous spawns (was causing continuous loading)
  if (isSpawningLevel3Monster) {
    if (DEBUG_SETTINGS.logLevel3Monsters) {
      console.log("⏭️ [LEVEL 3] Monster spawn already in progress, skipping duplicate call:", monsterPath);
    }
    return;
  }
  
  // CRITICAL: Verify level is active before spawning
  if (currentLevel !== LEVEL_IDS.LEVEL3) {
    console.warn("⚠️ [LEVEL 3] Cannot spawn monster - level not active", { currentLevel, expected: LEVEL_IDS.LEVEL3 });
    return;
  }
  
  // CRITICAL: Check if this exact monster is already spawned (prevent duplicates)
  const existingMonster = level3State.monsters.find(m => 
    m.path === monsterPath && m.mesh && m.mesh.visible && !m.caught
  );
  if (existingMonster) {
    if (DEBUG_SETTINGS.logLevel3Monsters) {
      console.log("⏭️ [LEVEL 3] Monster already exists and is active, skipping duplicate spawn:", monsterPath);
    }
    return;
  }
  
  // Set spawning flag to prevent concurrent spawns
  isSpawningLevel3Monster = true;
  
  // CRITICAL: Verify group is in scene and visible
  if (!level3State.group || !scene.children.includes(level3State.group)) {
    console.error("❌ [LEVEL 3] Cannot spawn monster - group not in scene", {
      groupExists: !!level3State.group,
      groupInScene: level3State.group ? scene.children.includes(level3State.group) : false
    });
    // Attempt to add group to scene if it exists but isn't there
    if (level3State.group && !scene.children.includes(level3State.group)) {
      scene.add(level3State.group);
      console.log("✅ [LEVEL 3] Added level3State.group to scene");
    } else {
      return;
    }
  }
  
  // Allow spawning if no monsters currently active
  // CRITICAL: Clear any leftover/invisible monsters before spawning
  if (level3State.monsters.length > 0) {
    console.log("🏹 [LEVEL 3] Found existing monsters, checking if they're valid...", {
      monstersCount: level3State.monsters.length,
      monsters: level3State.monsters.map(m => ({
        hasMesh: !!m.mesh,
        meshVisible: m.mesh ? m.mesh.visible : false,
        meshInGroup: m.mesh && level3State.group ? level3State.group.children.includes(m.mesh) : false,
        caught: m.caught
      }))
    });
    
    // Remove any invalid or caught monsters
    level3State.monsters = level3State.monsters.filter(monster => {
      if (!monster.mesh || monster.caught || !monster.mesh.visible) {
        if (monster.mesh && monster.mesh.parent) {
          monster.mesh.parent.remove(monster.mesh);
        }
        if (monster.mixer) {
          monster.mixer.stopAllAction();
        }
        console.log("🧹 [LEVEL 3] Removed invalid/caught monster");
        return false;
      }
      return true;
    });
    
    // If there are still valid monsters, don't spawn
    if (level3State.monsters.length > 0) {
      console.log("🏹 [LEVEL 3] Valid monster already active, skipping spawn", {
        remainingMonsters: level3State.monsters.length
      });
      return;
    }
  }
  
  console.log(`🏹 [LEVEL 3] Spawning monster: ${monsterPath}`, {
    currentLevel,
    groupVisible: level3State.group.visible,
    groupInScene: scene.children.includes(level3State.group),
    monstersCount: level3State.monsters.length
  });
  
  try {
    const gltf = await loadModel(monsterPath);
    const monsterMesh = gltf.scene;
    
    // Progressive scaling: each monster gets bigger within its step
    // Step 1: 1.2 → 1.8 → 2.4 → 3.0 → 3.6 (3x larger than original)
    // Step 2: 1.2 → 1.8 → 2.4 → 3.0 → 3.6 (3x larger than original)
    // 🚨 CRITICAL FIX (December 30, 2025): Monsters are now 3x larger for better visibility
    // Calculate scale based on index within current step (0-4 for each step)
    const indexInStep = level3RiddleState.currentMonsterIndex % LEVEL3_MONSTERS_PER_STEP;
    const monsterScale = LEVEL3_MONSTER_BASE_SCALE + (indexInStep * LEVEL3_MONSTER_SCALE_INCREMENT);
    monsterMesh.scale.set(monsterScale, monsterScale, monsterScale);
    
    // Random spawn position within arena bounds (avoid walls)
    const origin = level3Config.origin;
    const size = level3Config.size;
    const margin = 20;
    const spawnX = origin.x + (Math.random() * (size - margin * 2) - (size / 2 - margin));
    const spawnZ = origin.z + (Math.random() * (size - margin * 2) - (size / 2 - margin));
    
    // Adjust Y position based on scale (bigger monsters need higher Y to sit on ground)
    // 🚨 CRITICAL FIX (December 30, 2025): Monsters positioned 1 unit lower to reach ground level
    const baseY = origin.y + 0.2; // Changed from 1.2 to 0.2 (1 unit lower)
    const scaledY = baseY + (monsterScale - LEVEL3_MONSTER_BASE_SCALE) * 0.5; // Adjust for scale
    monsterMesh.position.set(spawnX, scaledY, spawnZ);
    
    // Set up animations
    let mixer = null;
    const animations = {};
    if (gltf.animations && gltf.animations.length > 0) {
      mixer = new THREE.AnimationMixer(monsterMesh);
      gltf.animations.forEach((clip) => {
        const action = mixer.clipAction(clip);
        animations[clip.name] = action;
      });
      // Play walk/run animation
      if (animations['Walk'] || animations['walk']) {
        const walkAnim = animations['Walk'] || animations['walk'];
        walkAnim.reset().fadeIn(0.2).play().setLoop(THREE.LoopRepeat);
      } else if (animations['Run'] || animations['run']) {
        const runAnim = animations['Run'] || animations['run'];
        runAnim.reset().fadeIn(0.2).play().setLoop(THREE.LoopRepeat);
      } else if (gltf.animations.length > 0) {
        // Play first available animation
        const firstAnim = mixer.clipAction(gltf.animations[0]);
        firstAnim.reset().fadeIn(0.2).play().setLoop(THREE.LoopRepeat);
      }
    }
    
    // Random target position for movement
    const targetX = origin.x + (Math.random() * (size - margin * 2) - (size / 2 - margin));
    const targetZ = origin.z + (Math.random() * (size - margin * 2) - (size / 2 - margin));
    const targetPosition = new THREE.Vector3(targetX, scaledY, targetZ);
    
    // Monster speed (slightly slower for bigger monsters to balance difficulty)
    const speed = 3.0 - (indexInStep * 0.1);
    
    // CRITICAL: Ensure group is visible and in scene before adding monster
    if (!scene.children.includes(level3State.group)) {
      scene.add(level3State.group);
      console.log("✅ [LEVEL 3] Added level3State.group to scene before spawning monster");
    }
    level3State.group.visible = true; // Ensure group is visible
    
    level3State.group.add(monsterMesh);
    level3State.monsters.push({
      mesh: monsterMesh,
      mixer: mixer,
      animations: animations,
      targetPosition: targetPosition,
      speed: speed,
      path: monsterPath,
      caught: false,
      catchEffect: null, // For visual effects when caught
      baseY: scaledY, // Store the base Y position for this monster's scale
      scale: monsterScale // Store scale for reference
    });
    
    level3RiddleState.firstMonsterSpawned = true;
    
    // CRITICAL: Clear spawning flag after successful spawn
    isSpawningLevel3Monster = false;
    
    // Verify monster was added correctly
    console.log(`✅ [LEVEL 3] Monster spawned successfully:`, {
      monsterPath,
      monsterMeshVisible: monsterMesh.visible,
      monsterInGroup: level3State.group.children.includes(monsterMesh),
      groupVisible: level3State.group.visible,
      groupInScene: scene.children.includes(level3State.group),
      totalMonsters: level3State.monsters.length,
      position: { x: monsterMesh.position.x.toFixed(2), y: monsterMesh.position.y.toFixed(2), z: monsterMesh.position.z.toFixed(2) }
    });
    const monsterNumberInStep = indexInStep + 1; // 1-5 within current step
    const monsterNameRaw = monsterPath.split('/').pop().replace('.gltf', '');
    // Capitalize first letter of monster name
    const monsterName = monsterNameRaw.charAt(0).toUpperCase() + monsterNameRaw.slice(1);
    console.log(`🏹 [LEVEL 3] Step ${level3RiddleState.currentStep} - Monster ${monsterNumberInStep}/${LEVEL3_MONSTERS_PER_STEP} (${monsterName}) spawned at:`, monsterMesh.position, `Scale: ${monsterScale.toFixed(2)}x`);
    
    // Create hunt message with monster name and step info
    let huntMessage = `🏹 Hunt the ${monsterName}!`;
    if (monsterNumberInStep === LEVEL3_MONSTERS_PER_STEP) {
      huntMessage = `🔥 Hunt the ${monsterName} - HUGE FINAL BOSS! 🔥`;
    }
    huntMessage += ` (Step ${level3RiddleState.currentStep} - ${monsterNumberInStep}/${LEVEL3_MONSTERS_PER_STEP})`;
    
    showRiddleToast(huntMessage, { 
      id: `level3_step${level3RiddleState.currentStep}_monster_${monsterNumberInStep}_spawn`, 
      duration: 5000 
    });
  } catch (error) {
    console.error("❌ [LEVEL 3] Failed to spawn monster:", error);
    // CRITICAL: Clear spawning flag on error to allow retry
    isSpawningLevel3Monster = false;
  }
}

function checkLevel3MonsterCapture() {
  if (!level3State.monsters || level3State.monsters.length === 0) return;
  
  const playerPos = playerCollider.start.clone();
  playerPos.y = level3Config.origin.y + 1.0; // Adjust to monster height level
  
  level3State.monsters.forEach((monster) => {
    if (!monster.mesh || !monster.mesh.visible || monster.caught) return;
    
    const monsterPos = monster.mesh.position.clone();
    const horizontalDistance = new THREE.Vector2(playerPos.x, playerPos.z)
      .distanceTo(new THREE.Vector2(monsterPos.x, monsterPos.z));
    
    if (horizontalDistance <= LEVEL3_CAPTURE_DISTANCE) {
      // Capture the monster!
      captureLevel3Monster(monster);
    }
  });
}

function captureLevel3Monster(monster) {
  if (monster.caught) return;
  
  monster.caught = true;
  level3RiddleState.monstersCaught++;
  const currentStep = level3RiddleState.currentStep;
  
  // Calculate monsters caught in current step
  // Step 1: monsters 1-5, Step 2: monsters 6-10
  const monstersCaughtInStep = currentStep === 1 
    ? level3RiddleState.monstersCaught 
    : currentStep === 2 
    ? level3RiddleState.monstersCaught - LEVEL3_MONSTERS_PER_STEP 
    : 0;
  
  console.log(`🏹 [LEVEL 3] Step ${currentStep} - Monster ${monstersCaughtInStep}/${LEVEL3_MONSTERS_PER_STEP} caught! Total: ${level3RiddleState.monstersCaught}`);
  
  // Visual effect: make monster disappear with a scale animation
  const originalScale = monster.mesh.scale.clone();
  let scaleTime = 0;
  const scaleDuration = 0.5;
  
  const scaleDown = () => {
    scaleTime += 0.016; // ~60fps
    const progress = Math.min(scaleTime / scaleDuration, 1.0);
    const scale = THREE.MathUtils.lerp(1.0, 0.0, progress);
    monster.mesh.scale.set(
      originalScale.x * scale,
      originalScale.y * scale,
      originalScale.z * scale
    );
    
    if (progress < 1.0) {
      requestAnimationFrame(scaleDown);
    } else {
      // Hide monster completely and remove from scene
      monster.mesh.visible = false;
      if (monster.mesh.parent) {
        monster.mesh.parent.remove(monster.mesh);
      }
      if (monster.mixer) {
        monster.mixer.stopAllAction();
      }
      // Remove from monsters array
      const index = level3State.monsters.indexOf(monster);
      if (index > -1) {
        level3State.monsters.splice(index, 1);
      }
    }
  };
  scaleDown();
  
  // Play capture sound
  if (cheeseAimClearSound) {
    cheeseAimClearSound.play();
  }
  
  // Award 50 DSPOINC per monster
  awardLevel3MonsterDspoincReward(level3RiddleState.monstersCaught);
  
  // Check if step is complete
  if (monstersCaughtInStep < LEVEL3_MONSTERS_PER_STEP) {
    // More monsters to catch in this step
    showRiddleToast(`🎯 Step ${currentStep} - Monster ${monstersCaughtInStep}/${LEVEL3_MONSTERS_PER_STEP} caught! +${LEVEL3_DSPOINC_PER_MONSTER} DSPOINC`, { 
      id: `level3_step${currentStep}_monster_${monstersCaughtInStep}_caught`, 
      duration: 3000 
    });
    
    // Spawn next monster after a short delay
    setTimeout(() => {
      spawnNextLevel3Monster();
    }, 1500);
  } else {
    // Step complete! (5 monsters caught in current step)
    if (currentStep === 1) {
      // Step 1 complete - unlock trait and start Step 2
      console.log(`🏹 [LEVEL 3] ✅ STEP 1 COMPLETE! All 5 monsters caught. Starting Step 2...`);
      showRiddleToast(`🎯 Step 1 Complete! All 5 monsters caught! Starting Step 2...`, { 
        id: "level3_step1_complete", 
        duration: 5000 
      });
      
      // Unlock Step 1 trait
      if (!level3RiddleState.step1TraitUnlocked) {
        unlockLevel3Step1Trait();
        level3RiddleState.step1TraitUnlocked = true;
      }
      
      // Transition to Step 2
      setTimeout(() => {
        startLevel3Step2();
      }, 2000);
    } else if (currentStep === 2) {
      // Step 2 complete - unlock trait and activate portal (Step 3)
      console.log(`🏹 [LEVEL 3] ✅ STEP 2 COMPLETE! All 10 monsters caught. Activating portal...`);
      showRiddleToast(`🎯 Step 2 Complete! All monsters hunted! The portal opens!`, { 
        id: "level3_step2_complete", 
        duration: 5000 
      });
      
      // Unlock Step 2 trait
      if (!level3RiddleState.step2TraitUnlocked) {
        unlockLevel3Step2Trait();
        level3RiddleState.step2TraitUnlocked = true;
      }
      
      // Activate portal (Step 3)
      setTimeout(() => {
        level3RiddleState.currentStep = 3;
        activateLevel3Portal();
      }, 2000);
    }
  }
}

async function spawnNextLevel3Monster() {
  level3RiddleState.currentMonsterIndex++;
  
  // Get the correct queue based on current step
  const currentQueue = level3RiddleState.currentStep === 1 
    ? LEVEL3_MONSTER_QUEUE_STEP1 
    : level3RiddleState.currentStep === 2 
    ? LEVEL3_MONSTER_QUEUE_STEP2 
    : null;
  
  if (!currentQueue) {
    console.log("🏹 [LEVEL 3] No queue available for current step:", level3RiddleState.currentStep);
    return;
  }
  
  // Calculate index within current step (0-4)
  const indexInStep = level3RiddleState.currentMonsterIndex % LEVEL3_MONSTERS_PER_STEP;
  
  if (indexInStep >= currentQueue.length) {
    console.log(`🏹 [LEVEL 3] All monsters spawned for Step ${level3RiddleState.currentStep}! Waiting for final capture...`);
    return;
  }
  
  const nextMonsterPath = currentQueue[indexInStep];
  console.log(`🏹 [LEVEL 3] Spawning next monster: Step ${level3RiddleState.currentStep}, Monster ${indexInStep + 1}/${LEVEL3_MONSTERS_PER_STEP} - ${nextMonsterPath}`);
  await spawnLevel3Monster(nextMonsterPath);
}

function startLevel3Step2() {
  console.log("🏹 [LEVEL 3] Starting Step 2 - Second set of 5 monsters!");
  level3RiddleState.currentStep = 2;
  
  // CRITICAL: Reset spawning flag to allow new monsters to spawn
  isSpawningLevel3Monster = false;
  
  // CRITICAL: Clean up any leftover monsters from Step 1
  if (level3State.monsters && level3State.monsters.length > 0) {
    console.log("🧹 [LEVEL 3] Cleaning up Step 1 monsters before starting Step 2...");
    level3State.monsters.forEach(monster => {
      if (monster.mesh && monster.mesh.parent) {
        monster.mesh.parent.remove(monster.mesh);
      }
      if (monster.mixer) {
        monster.mixer.stopAllAction();
      }
    });
    level3State.monsters = [];
    console.log("✅ [LEVEL 3] Step 1 monsters cleaned up");
  }
  
  // Reset index for Step 2 (set to -1 so spawnNextLevel3Monster increments to 0)
  level3RiddleState.currentMonsterIndex = -1;
  level3RiddleState.firstMonsterSpawned = false; // Allow spawning again
  
  // Spawn first monster of Step 2 using spawnNextLevel3Monster (properly handles index)
  spawnNextLevel3Monster();
}

function updateLevel3Monsters(delta) {
  if (!level3State.monsters || level3State.monsters.length === 0) return;
  
  level3State.monsters.forEach((monster) => {
    if (!monster.mesh || !monster.mesh.visible || monster.caught) return;
    
    // Update animation mixer
    if (monster.mixer) {
      monster.mixer.update(delta);
    }
    
    // Move monster towards target
    const monsterPos = monster.mesh.position.clone();
    const targetPos = monster.targetPosition.clone();
    monsterPos.y = 0;
    targetPos.y = 0;
    
    const direction = new THREE.Vector3()
      .subVectors(targetPos, monsterPos)
      .normalize();
    
    const horizontalDistance = new THREE.Vector2(monster.mesh.position.x, monster.mesh.position.z)
      .distanceTo(new THREE.Vector2(monster.targetPosition.x, monster.targetPosition.z));
    
    if (horizontalDistance > 2.0) {
      // Move towards target
      const moveDistance = monster.speed * delta;
      monster.mesh.position.x += direction.x * moveDistance;
      monster.mesh.position.z += direction.z * moveDistance;
      // Use stored baseY or calculate from scale
      // 🚨 CRITICAL FIX (December 30, 2025): Updated fallback calculation to match new baseY (0.2 instead of 1.2)
      const monsterY = monster.baseY || (level3Config.origin.y + 0.2 + (monster.scale - LEVEL3_MONSTER_BASE_SCALE) * 0.5);
      monster.mesh.position.y = monsterY;
      
      // Rotate to face movement direction
      if (direction.lengthSq() > 0.01) {
        const targetRotation = Math.atan2(direction.x, direction.z);
        monster.mesh.rotation.y = targetRotation;
      }
    } else {
      // Reached target, pick new random target
      const origin = level3Config.origin;
      const size = level3Config.size;
      const margin = 20;
      const newTargetX = origin.x + (Math.random() * (size - margin * 2) - (size / 2 - margin));
      const newTargetZ = origin.z + (Math.random() * (size - margin * 2) - (size / 2 - margin));
      // Use stored baseY for target position
      // 🚨 CRITICAL FIX (December 30, 2025): Updated fallback calculation to match new baseY (0.2 instead of 1.2)
      const monsterY = monster.baseY || (origin.y + 0.2 + (monster.scale - LEVEL3_MONSTER_BASE_SCALE) * 0.5);
      monster.targetPosition.set(newTargetX, monsterY, newTargetZ);
    }
    
    // OPTIMIZATION: Use false instead of true for better performance in Level 3
    // Only force full update when absolutely necessary (position/rotation changed)
    // This reduces CPU load significantly when multiple monsters are present
    monster.mesh.updateMatrixWorld(false);
  });
}

function checkLevel3TriggerBlockStanding() {
  if (!level3RiddleState.triggerBlock) return false;
  const block = level3RiddleState.triggerBlock;
  const blockTopY = block.position.y + (block.scale.y * 0.5);
  const playerFeet = playerCollider.start;
  const horizontalDistance = Math.sqrt(
    Math.pow(playerFeet.x - block.position.x, 2) + Math.pow(playerFeet.z - block.position.z, 2)
  );
  const verticalDistance = Math.abs(playerFeet.y - blockTopY);
  return horizontalDistance < 1.2 && verticalDistance < 0.8;
}

function updateLevel3Step0(delta) {
  const isStandingOnTrigger = checkLevel3TriggerBlockStanding();
  
  if (isStandingOnTrigger) {
    if (!level3RiddleState.step0StandingSoundPlayed) {
      playCheesePlatformSound();
      level3RiddleState.step0StandingSoundPlayed = true;
    }
    level3RiddleState.triggerBlockTimer += delta;
    if (level3RiddleState.triggerBlockTimer >= LEVEL3_STEP0_TRIGGER_TIME && !level3RiddleState.step0Complete) {
      level3RiddleState.step0Complete = true;
      level3RiddleState.triggerBlockTimer = LEVEL3_STEP0_TRIGGER_TIME;
      if (level3RiddleState.triggerBlock) {
        level3RiddleState.triggerBlock.visible = false;
      }
      if (level3RiddleState.triggerBlockVisual) {
        level3RiddleState.triggerBlockVisual.visible = false;
      }
      showRiddleToast("Step 1 begins! Hunt 5 monsters!", {
        id: "level3_step1_start",
        duration: 5000
      });
      if (!level3RiddleState.step0TraitUnlocked) {
        unlockLevel3Trait(LEVEL3_STEP0_TRAIT, "Level 3 Step 0");
      }
      awardLevel3DspoincReward("CHEESE_TEMPLE_LEVEL3_STEP0", 100, "Level 3 Step 0");
      // Start Step 1 - First set of 5 monsters
      level3RiddleState.currentStep = 1;
      level3RiddleState.currentMonsterIndex = 0;
      
      // CRITICAL: Verify level is still active before spawning
      console.log("🎯 [LEVEL 3] Step 0 complete - preparing to spawn first monster", {
        currentLevel,
        expectedLevel: LEVEL_IDS.LEVEL3,
        levelMatches: currentLevel === LEVEL_IDS.LEVEL3,
        groupExists: !!level3State.group,
        groupInScene: level3State.group ? scene.children.includes(level3State.group) : false,
        groupVisible: level3State.group ? level3State.group.visible : false,
        monstersCount: level3State.monsters.length,
        queueLength: LEVEL3_MONSTER_QUEUE_STEP1.length,
        levelBuilt: level3State.built
      });
      
      // CRITICAL: Ensure group is in scene before spawning
      if (level3State.group && !scene.children.includes(level3State.group)) {
        scene.add(level3State.group);
        console.log("✅ [LEVEL 3] Added level3State.group to scene before spawning monster");
      }
      if (level3State.group) {
        level3State.group.visible = true;
      }
      
      // CRITICAL: Spawn the first monster from Step 1 queue (only if level is still active AND not already spawned)
      // CRITICAL: Only spawn if firstMonsterSpawned is false (prevents continuous loading every frame)
      if (currentLevel === LEVEL_IDS.LEVEL3 && LEVEL3_MONSTER_QUEUE_STEP1.length > 0 && !level3RiddleState.firstMonsterSpawned) {
        if (DEBUG_SETTINGS.logLevel3Monsters) {
          console.log(`🏹 [LEVEL 3] Calling spawnLevel3Monster with: ${LEVEL3_MONSTER_QUEUE_STEP1[0]}`, {
            currentLevel,
            expectedLevel: LEVEL_IDS.LEVEL3,
            queueLength: LEVEL3_MONSTER_QUEUE_STEP1.length,
            firstMonster: LEVEL3_MONSTER_QUEUE_STEP1[0],
            groupExists: !!level3State.group,
            groupVisible: level3State.group ? level3State.group.visible : false,
            groupInScene: level3State.group ? scene.children.includes(level3State.group) : false,
            firstMonsterSpawned: level3RiddleState.firstMonsterSpawned
          });
        }
        spawnLevel3Monster(LEVEL3_MONSTER_QUEUE_STEP1[0]).catch((error) => {
          console.error("❌ [LEVEL 3] Failed to spawn monster after Step 0 complete:", error);
          console.error("❌ [LEVEL 3] Error details:", {
            errorMessage: error.message,
            errorStack: error.stack,
            currentLevel,
            groupExists: !!level3State.group,
            groupInScene: level3State.group ? scene.children.includes(level3State.group) : false
          });
        });
      } else {
        if (currentLevel !== LEVEL_IDS.LEVEL3) {
          console.error("❌ [LEVEL 3] Cannot spawn monster - level changed!", {
            currentLevel,
            expectedLevel: LEVEL_IDS.LEVEL3
          });
        } else if (LEVEL3_MONSTER_QUEUE_STEP1.length === 0) {
          console.error("❌ [LEVEL 3] Cannot spawn monster - queue is empty!");
        }
      }
    }
  } else {
    level3RiddleState.triggerBlockTimer = Math.max(0, level3RiddleState.triggerBlockTimer - delta * 0.5);
    level3RiddleState.step0StandingSoundPlayed = false;
  }
  
  // Update visual block animation
  const targetY = isStandingOnTrigger && level3RiddleState.triggerBlockVisual
    ? level3RiddleState.triggerBlockVisual.userData?.pressedY ?? level3RiddleState.triggerBlockVisual.position.y
    : level3RiddleState.triggerBlockVisual?.userData?.restY ?? level3RiddleState.triggerBlockVisual?.position.y;
  level3RiddleState.triggerBlockTargetY = targetY;
  updateLevel3TriggerBlockVisual(delta);
}

function updateLevel3TriggerBlockVisual(delta) {
  const visual = level3RiddleState.triggerBlockVisual;
  if (!visual || !visual.visible) return;
  const targetY = level3RiddleState.triggerBlockTargetY ?? visual.position.y;
  const speed = visual.userData?.lerpSpeed ?? 6;
  const t = Math.min(1, delta * speed);
  const newY = THREE.MathUtils.lerp(visual.position.y, targetY, t);
  visual.position.y = newY;
}

function updateLevel3(delta) {
  if (!level3State.built || currentLevel !== LEVEL_IDS.LEVEL3) return;
  updateLevel3MovingWalls(delta);
  if (!level3State.crushActive && handleLevel3CrushCheck(delta)) {
    return;
  }
  updateLevel3Step0(delta);
  if (level3RiddleState.step0Complete) {
    updateLevel3Monsters(delta);
    // Check for monster capture
    checkLevel3MonsterCapture();
  }
  
  // Handle portal proximity if active
  if (level3State.portalActive && level3State.portal && !level3State.completionScreenShown) {
    const playerCenter = playerCollider.start.clone();
    playerCenter.y += PLAYER_HEIGHT / 2;
    handleLevel3PortalProximity(playerCenter, delta);
  }
}

// ==================== LEVEL 4: THE FIRST SHOT ====================

function buildLevel4FirstShotArena() {
  if (level4State.built) return;
  
  const size = level4Config.size;
  const origin = level4Config.origin;
  
  // Cheese stone floor (160x160) - Fixed flickering with polygonOffset and slight elevation
  // 🚨 CRITICAL FIX: Make material unlit to prevent color fluctuation from lighting changes
  // Set emissive to match texture color and high emissiveIntensity so it doesn't respond to light
  const cheeseTexture = loadTexture("textures/blocks/cheese-stone.png");
  const floorGeometry = new THREE.PlaneGeometry(size, size);
    // FIXED (December 16, 2025): Underground flickering issue resolved
    // Uses emissive material to reduce lighting influence on textured floor
    // All levels now match saved grass ground system settings perfectly
    const floorMaterial = new THREE.MeshStandardMaterial({
      map: cheeseTexture,
      emissive: 0x888888, // Neutral gray emissive to maintain consistent brightness
      emissiveIntensity: 0.5, // High emissive = less affected by lighting changes
      side: THREE.DoubleSide,
      metalness: 0.1,
      roughness: 0.8,
      polygonOffset: true,
      polygonOffsetFactor: -1,
      polygonOffsetUnits: -1
    });
  if (cheeseTexture) {
    cheeseTexture.wrapS = THREE.RepeatWrapping;
    cheeseTexture.wrapT = THREE.RepeatWrapping;
    cheeseTexture.repeat.set(size / 4, size / 4);
  }
  const floor = new THREE.Mesh(floorGeometry, floorMaterial);
  floor.rotation.x = -Math.PI / 2;
  floor.position.set(origin.x, origin.y + 0.01, origin.z); // Slight elevation to prevent z-fighting
  level4State.group.add(floor);

  // REMOVED: roomShell completely removed to allow sky to work like Level 1
  // Level 1 has no roomShell, so Levels 2, 3, 4 should also have clear sky
  // Only walls for collision are kept (via collision detection, not visual roomShell)
  // No roomShell = clear sky like Level 1 and Level 5

  // Ambient lighting (darker like Level 1)
  const ambient = new THREE.AmbientLight(0xffffff, 0.6);
  level4State.group.add(ambient);
  const directional = new THREE.DirectionalLight(0xffffff, 0.8);
  directional.position.set(origin.x + 40, origin.y + level4Config.wallHeight, origin.z + 20);
  directional.castShadow = false;
  level4State.group.add(directional);

  // Create hidden cheese stone trigger block
  createLevel4TriggerBlock();

  level4State.built = true;
  
  // Create Level 4 chests (after built flag set, ensure chestSystem is initialized)
  // CRITICAL: Small delay to ensure chestSystem is initialized (similar to Level 2/3 pattern)
  setTimeout(async () => {
    // CRITICAL: Load opened chests from database before creating chests (January 4, 2026)
    // This ensures chests appear as opened when warping back to a level
    if (resolvedDiscordId && chestSystem) {
      console.log("📥 [LEVEL 4] Loading opened chests from database...");
      await chestSystem.loadOpenedChests(resolvedDiscordId, API_BASE_URL);
    }
    createLevel4Chests();
  }, 100);
  
  resetLevel4Progress();
  console.log("🎯 [LEVEL 4] First Shot Arena built - 160x160 cheese stone floor ready.");
}

// ==================== LEVEL 5: THE WALK ====================

// Level 5 "The Walk" - Load Klagenfurt city map
async function buildLevel5TheWalk() {
  if (level5State.built) {
    console.log("✅ [LEVEL 5] Already built, skipping rebuild");
    return;
  }
  
  console.log("🚶 [LEVEL 5] Building 'The Walk' level...");
  
  // Level group is already created in level5State initialization
  level5State.group.name = "Level5_TheWalk";
  
  // Load Klagenfurt map
  try {
    const loader = new GLTFLoader();
    const gltf = await new Promise((resolve, reject) => {
      const mapPath = resolveAssetPath("textures/3d models/Maps/klagenfurt.gltf");
      console.log("🗺️ [LEVEL 5] Loading Klagenfurt map from:", mapPath);
      loader.load(
        mapPath,
        (gltf) => {
          console.log("✅ [LEVEL 5] GLTF file loaded successfully");
          resolve(gltf);
        },
        (progress) => {
          if (progress.lengthComputable) {
            const percentComplete = (progress.loaded / progress.total) * 100;
            console.log(`📦 [LEVEL 5] Loading map: ${percentComplete.toFixed(1)}%`);
          }
        },
        (error) => {
          console.error("❌ [LEVEL 5] GLTF loader error:", error);
          reject(error);
        }
      );
    });
    
    console.log("✅ [LEVEL 5] Klagenfurt map loaded:", gltf);
    console.log("📊 [LEVEL 5] Map structure:", {
      children: gltf.scene.children.length,
      hasAnimations: gltf.animations.length > 0,
      scene: gltf.scene
    });
    
    // Ensure all children are visible and ready
    gltf.scene.traverse((child) => {
      if (child.isMesh) {
        child.visible = true;
        child.frustumCulled = true;
        // Ensure materials are set up correctly
        if (child.material) {
          if (Array.isArray(child.material)) {
            child.material.forEach(mat => {
              if (mat) mat.needsUpdate = true;
            });
          } else {
            child.material.needsUpdate = true;
          }
        }
      }
    });
    
    // Calculate scale based on map bounding box (includes all children/meshes)
    const box = new THREE.Box3().setFromObject(gltf.scene);
    const size = box.getSize(new THREE.Vector3());
    const center = box.getCenter(new THREE.Vector3());
    const maxDimension = Math.max(size.x, size.y, size.z);
    
    console.log("📏 [LEVEL 5] Map dimensions:", {
      size: size,
      center: center,
      maxDimension: maxDimension,
      boundingBox: box
    });
    
    // Scale to be 5x larger than typical level size (~60 units)
    // Adjust base size based on actual map dimensions
    const baseLevelSize = 60;
    const targetSize = baseLevelSize * 5; // 300 units
    const scaleFactor = maxDimension > 0 ? targetSize / maxDimension : 1.0;
    
    // Apply scale (multiply by level5State.mapScale for additional scaling)
    const finalScale = scaleFactor * level5State.mapScale;
    gltf.scene.scale.setScalar(finalScale);
    
    // First, calculate the bounding box BEFORE positioning
    let scaledBox = new THREE.Box3().setFromObject(gltf.scene);
    const scaledCenter = scaledBox.getCenter(new THREE.Vector3());
    
    // Position map so it's centered at origin (subtract the center offset)
    gltf.scene.position.sub(scaledCenter);
    
    // Recalculate bounding box AFTER positioning to get accurate ground level
    scaledBox = new THREE.Box3().setFromObject(gltf.scene);
    const scaledSize = scaledBox.getSize(new THREE.Vector3());
    const scaledMin = scaledBox.min;
    const scaledMax = scaledBox.max;
    
    // Add to level group
    level5State.group.add(gltf.scene);
    level5State.mapMesh = gltf.scene;
    
    // Calculate spawn position - spawn at center X/Z, on top of the map's ground
    // Since map is centered at origin, spawn at 0,0 for X/Z
    const spawnX = 0;
    const spawnZ = 0;
    
    // For city maps, the ground is usually at a specific Y level
    // Since we centered the map at origin, we need to find the actual ground level
    // Use the maximum Y of the bounding box (top of buildings) as reference
    // But we want to spawn on the ground, not on top of buildings
    // The ground level is typically near 0 after centering, but may vary
    
    // Try raycasting to find actual ground level at spawn position
    let spawnY;
    try {
      const raycaster = new THREE.Raycaster();
      const rayStart = new THREE.Vector3(spawnX, scaledMax.y + 50, spawnZ); // Start well above map
      const rayDirection = new THREE.Vector3(0, -1, 0); // Cast downward
      
      // Ensure scene is visible and updated for raycasting
      gltf.scene.visible = true;
      gltf.scene.updateMatrixWorld(true);
      
      raycaster.set(rayStart, rayDirection);
      raycaster.far = (scaledMax.y - scaledMin.y) + 100; // Cast through entire map
      const intersects = raycaster.intersectObject(gltf.scene, true); // Recursive
      
      if (intersects.length > 0) {
        // FIX: Find the FIRST intersection (top surface) at spawn position, not the lowest point
        // The raycast goes from top to bottom, so the first intersection is the walkable surface
        // We want the surface the player will actually stand on, not underground structures
        let groundY;
        
        // Find intersections very close to spawn position (within 1 unit)
        const spawnRadius = 1.0; // Check within 1 unit of spawn position
        const nearbyIntersects = intersects.filter(intersect => {
          const dx = intersect.point.x - spawnX;
          const dz = intersect.point.z - spawnZ;
          const distance = Math.sqrt(dx * dx + dz * dz);
          return distance <= spawnRadius;
        });
        
        if (nearbyIntersects.length > 0) {
          // Use the FIRST (highest) intersection near spawn - this is the walkable surface
          // Sort by Y descending to get the top surface first
          nearbyIntersects.sort((a, b) => b.point.y - a.point.y);
          groundY = nearbyIntersects[0].point.y;
          console.log(`✅ [LEVEL 5] Found ground surface at spawn position: Y=${groundY.toFixed(2)} (top surface from ${nearbyIntersects.length} nearby intersections)`);
        } else {
          // Fallback: use the first intersection overall (should be the top surface)
          // Sort all intersections by Y descending and take the first one
          const sortedIntersects = [...intersects].sort((a, b) => b.point.y - a.point.y);
          groundY = sortedIntersects[0].point.y;
          console.warn(`⚠️ [LEVEL 5] No intersections near spawn, using highest intersection: Y=${groundY.toFixed(2)}`);
        }
        
        spawnY = groundY; // Ground level (player feet on ground)
        console.log(`✅ [LEVEL 5] Spawn position set to: Y=${spawnY.toFixed(2)} (ground level)`);
        
        // NOTE: Grass system position will be updated in warpToLevel5() after applyLevelEnvironment()
        // This ensures the grass system is initialized before we try to update its position
      } else {
        // Fallback: assume ground is at Y=0 (after centering)
        // FIX: Changed from Math.max(scaledMax.y * 0.5, 5.0) to 0 (ground level)
        spawnY = 0; // Ground level (player feet on ground)
        console.warn(`⚠️ [LEVEL 5] Raycast found no intersections, using ground level spawn Y: ${spawnY}`);
        console.warn(`   Map bounds: min Y=${scaledMin.y}, max Y=${scaledMax.y}`);
      }
    } catch (raycastError) {
      // Fallback if raycast fails - use ground level
      spawnY = 0; // Ground level (player feet on ground)
      console.error(`❌ [LEVEL 5] Raycast error:`, raycastError);
      console.warn(`   Using fallback spawn Y: ${spawnY} (ground level)`);
    }
    
    level5State.spawnPosition.set(spawnX, spawnY, spawnZ);
    
    console.log(`✅ [LEVEL 5] Spawn position calculated:`, {
      spawnY: spawnY,
      spawnPosition: level5State.spawnPosition,
      mapBounds: { minY: scaledMin.y, maxY: scaledMax.y }
    });
    
    console.log(`✅ [LEVEL 5] Map positioned and centered`);
    
    console.log(`✅ [LEVEL 5] Map scaled by ${finalScale.toFixed(2)}x`);
    console.log(`📏 [LEVEL 5] Final map dimensions:`, {
      size: scaledSize,
      min: scaledMin,
      max: scaledMax,
      spawnPosition: level5State.spawnPosition,
      spawnY: spawnY
    });
    
    console.log(`✅ [LEVEL 5] Map scaled by ${finalScale.toFixed(2)}x, original size:`, size, "scaled size:", scaledSize);
    
    // Create huge cheese walls around the play zone (borders on all 4 sides)
    console.log("🧀 [LEVEL 5] Creating cheese border walls around the play zone...");
    try {
      const cheeseTexture = loadTexture("textures/blocks/cheese-stone.png");
      
      // Calculate wall dimensions based on map bounds
      // Walls should directly border the map with no gap
      const wallHeight = 200; // Tall walls to contain the play zone
      const wallThickness = 50; // Thick walls for visual presence
      
      // Map bounds (after centering, map is centered at origin)
      const mapWidth = scaledSize.x;
      const mapDepth = scaledSize.z;
      const mapMinX = scaledMin.x;
      const mapMaxX = scaledMax.x;
      const mapMinZ = scaledMin.z;
      const mapMaxZ = scaledMax.z;
      
      // Calculate wall positions (walls overlap map edges slightly to eliminate any visible gap)
      // Position walls so inner face is slightly inside map bounds to ensure no gap
      const overlapOffset = 5; // Small overlap to ensure no visible gap
      
      // North Wall (positive Z) - inner face overlaps into map slightly
      const northWallX = 0; // Center X
      const northWallZ = mapMaxZ - overlapOffset + (wallThickness / 2); // Wall overlaps into map to close gap
      const northWallWidth = mapWidth + wallThickness; // Full width + wall thickness to cover corners
      
      // South Wall (negative Z) - inner face overlaps into map slightly
      const southWallX = 0; // Center X
      const southWallZ = mapMinZ + overlapOffset - (wallThickness / 2); // Wall overlaps into map to close gap
      const southWallWidth = mapWidth + wallThickness; // Full width + wall thickness to cover corners
      
      // East Wall (positive X) - inner face overlaps into map slightly
      const eastWallX = mapMaxX - overlapOffset + (wallThickness / 2); // Wall overlaps into map to close gap
      const eastWallZ = 0; // Center Z
      const eastWallDepth = mapDepth + (overlapOffset * 2); // Full depth + overlap on both ends
      
      // West Wall (negative X) - inner face overlaps into map slightly
      const westWallX = mapMinX + overlapOffset - (wallThickness / 2); // Wall overlaps into map to close gap
      const westWallZ = 0; // Center Z
      const westWallDepth = mapDepth + (overlapOffset * 2); // Full depth + overlap on both ends
      
      // Ground level for wall base (align with map ground - walls sit on ground)
      const wallBaseY = scaledMin.y;
      
      // Create material with cheese texture
      // Keep original PNG scale - no texture repeat (preserve original texture appearance)
      if (cheeseTexture) {
        cheeseTexture.wrapS = THREE.RepeatWrapping;
        cheeseTexture.wrapT = THREE.RepeatWrapping;
        // Keep original texture scale (1, 1) - don't stretch or scratch the PNG
        cheeseTexture.repeat.set(1, 1);
        cheeseTexture.needsUpdate = true;
      }
      
      const cheeseMaterial = new THREE.MeshStandardMaterial({
        map: cheeseTexture,
        emissive: 0x000000,
        emissiveIntensity: 0
      });
      
      // North Wall (positive Z)
      const northWallGeometry = new THREE.BoxGeometry(northWallWidth, wallHeight, wallThickness);
      const northWall = new THREE.Mesh(northWallGeometry, cheeseMaterial);
      northWall.position.set(northWallX, wallBaseY + (wallHeight / 2), northWallZ);
      northWall.castShadow = false;
      northWall.receiveShadow = false;
      level5State.group.add(northWall);
      console.log(`🧀 [LEVEL 5] North wall created:`, { x: northWallX, z: northWallZ, width: northWallWidth, height: wallHeight });
      
      // South Wall (negative Z)
      const southWallGeometry = new THREE.BoxGeometry(southWallWidth, wallHeight, wallThickness);
      const southWall = new THREE.Mesh(southWallGeometry, cheeseMaterial);
      southWall.position.set(southWallX, wallBaseY + (wallHeight / 2), southWallZ);
      southWall.castShadow = false;
      southWall.receiveShadow = false;
      level5State.group.add(southWall);
      console.log(`🧀 [LEVEL 5] South wall created:`, { x: southWallX, z: southWallZ, width: southWallWidth, height: wallHeight });
      
      // East Wall (positive X)
      const eastWallGeometry = new THREE.BoxGeometry(wallThickness, wallHeight, eastWallDepth);
      const eastWall = new THREE.Mesh(eastWallGeometry, cheeseMaterial);
      eastWall.position.set(eastWallX, wallBaseY + (wallHeight / 2), eastWallZ);
      eastWall.castShadow = false;
      eastWall.receiveShadow = false;
      level5State.group.add(eastWall);
      console.log(`🧀 [LEVEL 5] East wall created:`, { x: eastWallX, z: eastWallZ, depth: eastWallDepth, height: wallHeight });
      
      // West Wall (negative X)
      const westWallGeometry = new THREE.BoxGeometry(wallThickness, wallHeight, westWallDepth);
      const westWall = new THREE.Mesh(westWallGeometry, cheeseMaterial);
      westWall.position.set(westWallX, wallBaseY + (wallHeight / 2), westWallZ);
      westWall.castShadow = false;
      westWall.receiveShadow = false;
      level5State.group.add(westWall);
      console.log(`🧀 [LEVEL 5] West wall created:`, { x: westWallX, z: westWallZ, depth: westWallDepth, height: wallHeight });
      
      // Store wall references in level5State for potential future use
      level5State.borderWalls = {
        north: northWall,
        south: southWall,
        east: eastWall,
        west: westWall
      };
      
      console.log(`✅ [LEVEL 5] All 4 cheese border walls created successfully!`);
    } catch (wallError) {
      console.error("❌ [LEVEL 5] Error creating cheese border walls:", wallError);
      // Continue without walls if creation fails
    }
    
    console.log(`🚶 [LEVEL 5] 'The Walk' level built successfully. Spawn position:`, level5State.spawnPosition);
    
    // Create collision mesh from Level 5 GLTF map geometry
    // This is essential for ground detection and wall collision
    try {
      console.log("🔧 [LEVEL 5] Creating collision mesh from map geometry...");
      
      // Remove old collision mesh if it exists (from other levels)
      // Wrap in try-catch to prevent cleanup errors from blocking collision mesh creation
      if (collisionMesh) {
        // Only remove if it's not already Level 5's collision mesh (avoid recreating if already valid)
        if (collisionMesh.name === "Level5_CollisionMesh" && collisionMesh.geometry && collisionMesh.geometry.boundsTree) {
          console.log("✅ [LEVEL 5] Level 5 collision mesh already exists and is valid, reusing it");
          // Don't recreate - collision mesh is already set up correctly
          return; // Exit early - collision mesh already exists
        }
        
        try {
          scene.remove(collisionMesh);
          if (collisionMesh.geometry) {
            // Dispose boundsTree if it exists and has dispose method
            try {
              if (collisionMesh.geometry.boundsTree && typeof collisionMesh.geometry.boundsTree.dispose === 'function') {
                collisionMesh.geometry.boundsTree.dispose();
              }
            } catch (boundsTreeError) {
              // Ignore boundsTree disposal errors - not critical
              console.warn("⚠️ [LEVEL 5] Could not dispose boundsTree (non-critical):", boundsTreeError.message);
            }
            collisionMesh.geometry.dispose();
          }
          console.log("🗑️ [LEVEL 5] Old collision mesh removed");
        } catch (cleanupError) {
          console.warn("⚠️ [LEVEL 5] Error removing old collision mesh (continuing anyway):", cleanupError.message);
        } finally {
          collisionMesh = null;
        }
      }
      
      // For Level 5, we'll use the GLTF scene directly as collision source
      // Extract ALL mesh geometries (including all 8 patterns the user mentioned)
      const meshes = [];
      const meshNames = [];
      const meshDetails = [];
      
      console.log(`🔍 [LEVEL 5] Scanning GLTF scene for meshes (recursive traversal)...`);
      console.log(`   GLTF scene has ${gltf.scene.children.length} direct children`);
      
      // Count total objects in scene for debugging
      let totalObjects = 0;
      gltf.scene.traverse(() => { totalObjects++; });
      console.log(`   Total objects in scene (including nested): ${totalObjects}`);
      
      // Recursively traverse the entire scene to find ALL meshes (including nested ones)
      gltf.scene.traverse((child) => {
        // Find ALL meshes - check that geometry has position attribute (valid mesh)
        if (child.isMesh && child.geometry && child.geometry.attributes && child.geometry.attributes.position) {
          const meshName = child.name || `unnamed_mesh_${meshes.length + 1}`;
          const vertexCount = child.geometry.attributes.position.count;
          const indexCount = child.geometry.index ? child.geometry.index.count : 0;
          const isSkinned = child.isSkinnedMesh;
          const parentName = child.parent ? (child.parent.name || child.parent.type || 'unnamed_parent') : 'root';
          
          // Include ALL meshes for collision (regular, skinned, etc.)
          meshes.push(child);
          meshNames.push(meshName);
          meshDetails.push({
            name: meshName,
            parent: parentName,
            vertices: vertexCount,
            indices: indexCount,
            isSkinned: isSkinned,
            type: child.type,
            visible: child.visible
          });
          
          console.log(`📦 [LEVEL 5] Found mesh ${meshes.length}: "${meshName}" (parent: "${parentName}", ${vertexCount} vertices, ${indexCount} indices, ${isSkinned ? 'skinned' : 'regular'})`);
        }
      });
      
      console.log(`📊 [LEVEL 5] Scene traversal complete: ${meshes.length} meshes found`);
      
      if (meshes.length > 0) {
        console.log(`📦 [LEVEL 5] Found ${meshes.length} meshes for collision:`, meshNames);
        console.log(`📋 [LEVEL 5] Mesh details:`, meshDetails);
        
        // Verify we found meshes (optimized map uses 5 meshes)
        if (meshes.length === 0) {
          console.error(`❌ [LEVEL 5] No meshes found! Collision detection will not work.`);
        } else if (meshes.length >= 3) {
          console.log(`✅ [LEVEL 5] Found ${meshes.length} meshes - collision detection ready!`);
        } else {
          console.warn(`⚠️ [LEVEL 5] Only ${meshes.length} meshes found - collision may be incomplete`);
        }
        
        // Create a combined geometry from all meshes using BufferGeometryUtils
        // This properly merges geometries with indices (faces) for collision detection
        const geometriesToMerge = [];
        
        // Helper function to normalize geometry attributes for mergeGeometries compatibility
        // mergeGeometries requires ALL geometries to have the SAME attributes (position, normal, uv, etc.)
        const normalizeGeometryAttributes = (geometry) => {
          const vertexCount = geometry.attributes.position.count;
          
          // Ensure geometry has indices
          if (!geometry.index || geometry.index.count === 0) {
            // Non-indexed geometry - create index buffer
            const triangleCount = Math.floor(vertexCount / 3);
            const indexCount = triangleCount * 3;
            
            // Create sequential indices assuming triangles (0,1,2, 3,4,5, 6,7,8, ...)
            const indices = new Uint32Array(indexCount);
            for (let i = 0; i < indexCount; i++) {
              indices[i] = i;
            }
            geometry.setIndex(new THREE.BufferAttribute(indices, 1));
          }
          
          // Ensure geometry has normals
          if (!geometry.attributes.normal) {
            geometry.computeVertexNormals();
          }
          
          // Ensure geometry has UV coordinates (required for merge compatibility)
          // If missing, add dummy UVs (0,0) - we don't need UVs for collision detection
          if (!geometry.attributes.uv) {
            const uvs = new Float32Array(vertexCount * 2);
            for (let i = 0; i < vertexCount; i++) {
              uvs[i * 2] = 0;
              uvs[i * 2 + 1] = 0;
            }
            geometry.setAttribute('uv', new THREE.BufferAttribute(uvs, 2));
          }
          
          return geometry;
        };
        
        meshes.forEach((mesh) => {
          mesh.updateMatrixWorld(true);
          
          // Clone geometry to avoid modifying original
          const geometry = mesh.geometry.clone();
          
          // Apply world matrix to geometry vertices
          geometry.applyMatrix4(mesh.matrixWorld);
          
          // Normalize attributes (indices, normals, UVs) for mergeGeometries compatibility
          normalizeGeometryAttributes(geometry);
          
          geometriesToMerge.push(geometry);
        });
        
        // Add border walls to collision mesh
        if (level5State.borderWalls) {
          console.log("🧀 [LEVEL 5] Adding border walls to collision mesh...");
          console.log("🧀 [LEVEL 5] Border walls object:", level5State.borderWalls);
          const walls = [
            level5State.borderWalls.north,
            level5State.borderWalls.south,
            level5State.borderWalls.east,
            level5State.borderWalls.west
          ];
          
          let wallsAdded = 0;
          walls.forEach((wall, index) => {
            if (wall && wall.geometry) {
              wall.updateMatrixWorld(true);
              
              // Clone geometry to avoid modifying original
              const wallGeometry = wall.geometry.clone();
              
              // Apply world matrix to geometry vertices
              wallGeometry.applyMatrix4(wall.matrixWorld);
              
              // Normalize attributes (indices, normals, UVs) for mergeGeometries compatibility
              normalizeGeometryAttributes(wallGeometry);
              
              geometriesToMerge.push(wallGeometry);
              wallsAdded++;
              console.log(`🧀 [LEVEL 5] Added ${['North', 'South', 'East', 'West'][index]} wall to collision mesh`, {
                position: wall.position,
                geometry: { 
                  vertices: wallGeometry.attributes.position.count,
                  indices: wallGeometry.index ? wallGeometry.index.count : 0
                }
              });
            } else {
              console.warn(`⚠️ [LEVEL 5] Wall ${['North', 'South', 'East', 'West'][index]} is missing or has no geometry:`, wall);
            }
          });
          console.log(`✅ [LEVEL 5] Total walls added to collision mesh: ${wallsAdded}/4`);
        } else {
          console.error("❌ [LEVEL 5] CRITICAL: level5State.borderWalls is null/undefined - walls not added to collision mesh!");
        }
        
        // Merge all geometries into one using BufferGeometryUtils
        // All geometries now have indices for compatibility
        if (geometriesToMerge.length > 0) {
          console.log(`📦 [LEVEL 5] Merging ${geometriesToMerge.length} geometries for collision mesh...`);
          
          // Verify all geometries have compatible attributes before merging
          console.log(`🔍 [LEVEL 5] Verifying geometry attribute compatibility...`);
          geometriesToMerge.forEach((geom, idx) => {
            // Normalize attributes to ensure compatibility
            normalizeGeometryAttributes(geom);
            
            const hasPosition = !!geom.attributes.position;
            const hasNormal = !!geom.attributes.normal;
            const hasUV = !!geom.attributes.uv;
            const hasIndex = !!geom.index;
            
            console.log(`   Geometry ${idx}: position=${hasPosition}, normal=${hasNormal}, uv=${hasUV}, index=${hasIndex}`);
          });
          
          let mergedGeometry;
          try {
            // Use BufferGeometryUtils to merge geometries (all now have compatible indices)
            console.log(`🔄 [LEVEL 5] Attempting to merge ${geometriesToMerge.length} geometries...`);
            mergedGeometry = mergeGeometries(geometriesToMerge);
            console.log(`✅ [LEVEL 5] Geometry merge successful`);
          } catch (mergeError) {
            console.error("❌ [LEVEL 5] Failed to merge geometries:", mergeError);
            console.error("   Error details:", mergeError.message);
            
            // Enhanced fallback: try to merge in groups
            console.error("   Trying grouped merge fallback...");
            try {
              // Ensure all geometries have normalized attributes
              console.log(`   Normalizing all geometry attributes for compatibility...`);
              geometriesToMerge.forEach((geom, idx) => {
                normalizeGeometryAttributes(geom);
              });
              
              // Try merge again after normalization
              mergedGeometry = mergeGeometries(geometriesToMerge);
              console.log(`✅ [LEVEL 5] Merge successful after attribute normalization`);
            } catch (fallbackError) {
              console.error("❌ [LEVEL 5] Fallback merge also failed:", fallbackError);
              // Last resort: use first geometry only
              mergedGeometry = geometriesToMerge[0];
              if (geometriesToMerge.length > 1) {
                console.warn(`⚠️ [LEVEL 5] Using only first geometry (${geometriesToMerge.length - 1} meshes skipped)`);
              }
            }
          }
          
          // Verify mergedGeometry was created successfully
          if (!mergedGeometry) {
            console.error("❌ [LEVEL 5] CRITICAL: mergedGeometry is null/undefined after merge attempts!");
            throw new Error("Failed to create merged geometry for collision mesh");
          }
          
          // Dispose geometries we merged (except the merged one)
          geometriesToMerge.forEach((geom) => {
            if (geom !== mergedGeometry) {
              geom.dispose();
            }
          });
          
          // Ensure geometry has normals for proper collision
          if (!mergedGeometry.attributes || !mergedGeometry.attributes.normal) {
            console.log("🔧 [LEVEL 5] Computing vertex normals...");
            mergedGeometry.computeVertexNormals();
          }
          
          // Compute bounding box
          mergedGeometry.computeBoundingBox();
          const bbox = mergedGeometry.boundingBox;
          console.log(`📦 [LEVEL 5] Merged geometry bounding box:`, {
            min: `${bbox.min.x.toFixed(2)}, ${bbox.min.y.toFixed(2)}, ${bbox.min.z.toFixed(2)}`,
            max: `${bbox.max.x.toFixed(2)}, ${bbox.max.y.toFixed(2)}, ${bbox.max.z.toFixed(2)}`,
            size: `${(bbox.max.x - bbox.min.x).toFixed(2)}, ${(bbox.max.y - bbox.min.y).toFixed(2)}, ${(bbox.max.z - bbox.min.z).toFixed(2)}`
          });
          
          // Create BVH tree for efficient collision detection
          console.log("🌳 [LEVEL 5] Creating BVH tree for collision detection...");
          try {
            mergedGeometry.boundsTree = new MeshBVH(mergedGeometry);
            console.log("✅ [LEVEL 5] BVH tree created successfully");
          } catch (bvhError) {
            console.error("❌ [LEVEL 5] Failed to create BVH tree:", bvhError);
            throw bvhError; // Re-throw to trigger outer catch
          }
          
          // Create invisible collision mesh
          collisionMesh = new THREE.Mesh(mergedGeometry, new THREE.MeshBasicMaterial({ visible: false }));
          collisionMesh.visible = false;
          collisionMesh.name = "Level5_CollisionMesh";
          scene.add(collisionMesh);
          
          const vertexCount = mergedGeometry.attributes.position.count;
          const indexCount = mergedGeometry.index ? mergedGeometry.index.count : 0;
          const hasBoundsTree = !!mergedGeometry.boundsTree;
          
          const wallsCount = level5State.borderWalls ? 
            Object.values(level5State.borderWalls).filter(w => w && w.geometry).length : 0;
          
          console.log(`✅ [LEVEL 5] Collision mesh created successfully!`, {
            vertices: vertexCount,
            indices: indexCount,
            faces: indexCount > 0 ? indexCount / 3 : 'unknown',
            mapMeshes: meshes.length,
            wallsIncluded: wallsCount,
            totalGeometries: geometriesToMerge.length,
            hasBoundsTree: hasBoundsTree,
            collisionMeshInScene: scene.children.includes(collisionMesh),
            collisionMeshName: collisionMesh.name
          });
          
          // Verify collision mesh is ready
          if (!hasBoundsTree) {
            console.error("❌ [LEVEL 5] CRITICAL: Collision mesh created but BVH tree is missing!");
          } else {
            console.log("✅ [LEVEL 5] Collision mesh is ready for ground/wall detection");
            console.log("✅ [LEVEL 5] Collision mesh bounds:", {
              min: `${bbox.min.x.toFixed(2)}, ${bbox.min.y.toFixed(2)}, ${bbox.min.z.toFixed(2)}`,
              max: `${bbox.max.x.toFixed(2)}, ${bbox.max.y.toFixed(2)}, ${bbox.max.z.toFixed(2)}`
            });
          }
        } else {
          console.warn("⚠️ [LEVEL 5] No geometries to merge for collision");
        }
      } else {
        console.warn("⚠️ [LEVEL 5] No meshes found in GLTF for collision mesh - ground/wall collision disabled");
      }
      
      // Final verification: Check if collision mesh is ready
      if (collisionMesh && collisionMesh.geometry && collisionMesh.geometry.boundsTree) {
        console.log("✅ [LEVEL 5] Collision mesh final verification:", {
          name: collisionMesh.name,
          vertices: collisionMesh.geometry.attributes.position.count,
          indices: collisionMesh.geometry.index ? collisionMesh.geometry.index.count : 0,
          inScene: scene.children.includes(collisionMesh),
          visible: collisionMesh.visible
        });
      } else {
        console.error("❌ [LEVEL 5] CRITICAL: Collision mesh verification failed!", {
          collisionMesh: !!collisionMesh,
          hasGeometry: !!collisionMesh?.geometry,
          hasBoundsTree: !!collisionMesh?.geometry?.boundsTree
        });
      }
    } catch (collisionError) {
      console.error("❌ [LEVEL 5] Failed to create collision mesh:", collisionError);
      console.error("   Error details:", collisionError.stack);
      // Continue without collision mesh (player can fly through, but no ground detection)
    }
    
    // Create Level 5 chests (with small delay to ensure level is fully initialized)
    setTimeout(async () => {
      // CRITICAL: Load opened chests from database before creating chests (January 4, 2026)
      // This ensures chests appear as opened when warping back to a level
      if (resolvedDiscordId && chestSystem) {
        console.log("📥 [LEVEL 5] Loading opened chests from database...");
        await chestSystem.loadOpenedChests(resolvedDiscordId, API_BASE_URL);
      }
      createLevel5Chests();
    }, 100);
    
    level5State.built = true;
    level5State.group.visible = false; // Hidden until level is active
    
  } catch (error) {
    console.error("❌ [LEVEL 5] Failed to load Klagenfurt map:", error);
    // Create fallback placeholder if map fails to load
    const fallbackGeometry = new THREE.PlaneGeometry(300, 300);
    const fallbackMaterial = new THREE.MeshStandardMaterial({ color: 0x87ceeb });
    const fallback = new THREE.Mesh(fallbackGeometry, fallbackMaterial);
    fallback.rotation.x = -Math.PI / 2;
    fallback.position.y = 0;
    level5State.group.add(fallback);
    level5State.built = true;
    console.warn("⚠️ [LEVEL 5] Using fallback placeholder due to loading error");
  }
}

// ==================== LEVEL 6: PHOENIX BOSS ARENA ====================

// Level 6 "Phoenix Boss Arena" - Simple arena for Phoenix boss fight
async function buildLevel6PhoenixArena() {
  if (level6State.built) {
    console.log("✅ [LEVEL 6] Already built, skipping rebuild");
    return;
  }
  
  console.log("🔥 [LEVEL 6] Building Phoenix Boss Arena...");
  
  // Level group is already created in level6State initialization
  level6State.group.name = "Level6_PhoenixArena";
  
  // NOTE: GLTF map loading is now handled by the ground system (grass-system.js)
  // The ground system will load the map when groundType is 'gltf'
  // We only need to handle collision mesh creation here
  
  // CRITICAL: Check ground type FIRST - only load GLTF map if groundType is 'gltf'
  const groundConfig = getGroundConfigForLevel(LEVEL_IDS.LEVEL6);
  const shouldLoadGLTF = groundConfig && groundConfig.groundType === 'gltf';
  
  console.log("🔍 [LEVEL 6] Ground configuration:", {
    groundType: groundConfig?.groundType || 'unknown',
    shouldLoadGLTF: shouldLoadGLTF
  });
  
  // Check if grass system has loaded the GLTF map (only if groundType is 'gltf')
  let mapLoaded = false;
  let mapModel = null;
  let mapGroundY = 0;
  
  // CRITICAL: Only try to load GLTF map if groundType is 'gltf'
  if (shouldLoadGLTF && grassSystem && typeof grassSystem.getGLTFMapModel === 'function') {
    let retryCount = 0;
    const maxRetries = 10;
    const retryDelay = 100; // 100ms between retries
    
    while (retryCount < maxRetries && !mapModel) {
      mapModel = grassSystem.getGLTFMapModel();
      if (!mapModel) {
        retryCount++;
        if (retryCount < maxRetries) {
          console.log(`⏳ [LEVEL 6] Map not ready yet, retrying... (${retryCount}/${maxRetries})`);
          await new Promise(resolve => setTimeout(resolve, retryDelay));
        }
      }
    }
    
    console.log("🔍 [LEVEL 6] Checking grass system map model:", {
      hasGrassSystem: !!grassSystem,
      hasGetGLTFMapModel: typeof grassSystem.getGLTFMapModel === 'function',
      mapModel: !!mapModel,
      mapModelType: mapModel ? mapModel.constructor.name : 'null',
      mapModelChildren: mapModel ? mapModel.children?.length : 0,
      retries: retryCount
    });
    
    if (mapModel) {
      mapLoaded = true;
      // Calculate ground level from map
      const mapBox = new THREE.Box3().setFromObject(mapModel);
      mapGroundY = mapBox.min.y;
      console.log("🗺️ [LEVEL 6] Using GLTF map from ground system, ground level:", mapGroundY);
      // Store reference for collision system
      level6State.mapModel = mapModel;
      
      // CRITICAL: Ensure map is in level group (grass system adds it to scene directly)
      // If map is not in level group, add it (but don't remove from scene, as grass system manages it)
      if (!level6State.group.children.includes(mapModel)) {
        // Don't add to group if it's already in scene (grass system manages it)
        // Just ensure it's visible and accessible
        console.log("🗺️ [LEVEL 6] Map from grass system is in scene, ensuring visibility");
      }
      
      // CRITICAL: Set up collision map model with BVH trees for terrain collision
      console.log("🌳 [LEVEL 6] Creating BVH trees for grass system map meshes...");
      let bvhCount = 0;
      let bvhErrorCount = 0;
      mapModel.traverse((child) => {
        if (child.isMesh && child.geometry && child.geometry.isBufferGeometry) {
          try {
            // Create BVH tree for this mesh
            if (!child.geometry.boundsTree) {
              child.geometry.boundsTree = new MeshBVH(child.geometry);
              bvhCount++;
            }
            // Enable accelerated raycasting for this mesh
            child.raycast = acceleratedRaycast;
          } catch (bvhError) {
            bvhErrorCount++;
            console.warn(`⚠️ [LEVEL 6] Failed to create BVH for mesh "${child.name}":`, bvhError);
          }
        }
      });
      console.log(`✅ [LEVEL 6] Created ${bvhCount} BVH trees for grass system map meshes${bvhErrorCount > 0 ? ` (${bvhErrorCount} errors)` : ''}`);
      
      // CRITICAL: Store collision map model and verify it's set correctly
      level6State.collisionMapModel = mapModel;
      console.log(`✅ [LEVEL 6] Collision map model set from grass system:`, {
        hasModel: !!level6State.collisionMapModel,
        modelName: level6State.collisionMapModel?.name || 'unnamed',
        children: level6State.collisionMapModel?.children?.length || 0,
        inScene: level6State.collisionMapModel ? scene.children.includes(level6State.collisionMapModel) : false,
        visible: level6State.collisionMapModel?.visible ?? false,
        sameReference: level6State.collisionMapModel === mapModel
      });
    } else {
      console.log("✅ [LEVEL 6] No GLTF map from grass system (ground type is not 'gltf' or map not loaded)");
    }
  } else if (shouldLoadGLTF) {
    // Ground type is 'gltf' but grass system didn't load it - try loading directly (fallback)
    console.warn("⚠️ [LEVEL 6] Ground type is 'gltf' but grass system didn't load map, trying direct load...");
  } else {
    console.log("✅ [LEVEL 6] Ground type is not 'gltf' - using normal ground system (no GLTF map needed)");
  }
  
  // Legacy: If ground system didn't load map AND groundType is 'gltf', try loading directly (fallback)
  const mapFileName = LEVEL_MAP_CONFIG[LEVEL_IDS.LEVEL6];
  const mapPath = mapFileName ? resolveAssetPath(`textures/3d models/Maps/${mapFileName}`) : null;
  
  if (!mapLoaded && mapPath && shouldLoadGLTF) {
    console.log("🗺️ [LEVEL 6] Ground type is 'gltf', attempting to load GLTF map directly...");
    try {
      console.log("🗺️ [LEVEL 6] Loading GLTF map:", mapPath);
      const loader = new GLTFLoader();
      const gltf = await new Promise((resolve, reject) => {
      loader.load(
        mapPath,
        (gltf) => {
          console.log("✅ [LEVEL 6] GLTF map loaded successfully");
          resolve(gltf);
        },
        (progress) => {
          if (progress.lengthComputable) {
            const percentComplete = (progress.loaded / progress.total) * 100;
            console.log(`📦 [LEVEL 6] Loading map: ${percentComplete.toFixed(1)}%`);
          }
        },
        (error) => {
          console.error("❌ [LEVEL 6] GLTF loader error:", error);
          reject(error);
        }
      );
      });
      
      console.log("✅ [LEVEL 6] The Field map loaded:", gltf);
      console.log("📊 [LEVEL 6] Map structure:", {
        children: gltf.scene.children.length,
        hasAnimations: gltf.animations.length > 0,
        scene: gltf.scene
      });
      
      // Ensure all children are visible and ready
      gltf.scene.traverse((child) => {
        if (child.isMesh) {
          child.visible = true;
          child.frustumCulled = true; // Enable frustum culling for performance
          child.receiveShadow = true;
          child.castShadow = true;
          // Ensure materials are set up correctly
          if (child.material) {
            if (Array.isArray(child.material)) {
              child.material.forEach(mat => {
                if (mat) {
                  mat.needsUpdate = true;
                }
              });
            } else if (child.material) {
              child.material.needsUpdate = true;
            }
          }
        }
        // Also ensure groups are visible
        if (child.isGroup || child.isObject3D) {
          child.visible = true;
        }
      });
      
      // Ensure the root scene is visible
      gltf.scene.visible = true;
      console.log("👁️ [LEVEL 6] Map scene visibility:", gltf.scene.visible, "children:", gltf.scene.children.length);
      
      // Calculate map dimensions for scaling/positioning
      const box = new THREE.Box3().setFromObject(gltf.scene);
      const size = box.getSize(new THREE.Vector3());
      const center = box.getCenter(new THREE.Vector3());
      const maxDimension = Math.max(size.x, size.y, size.z);
      
      console.log("📏 [LEVEL 6] Map dimensions:", {
        size: size,
        center: center,
        maxDimension: maxDimension,
        boundingBox: box
      });
      
      // Scale map if needed (thefield.gltf might already be at correct scale)
      // For boss arena, we want a reasonable size - adjust if needed
      const targetSize = 200; // Match fallback ground plane size
      if (maxDimension > 0 && maxDimension !== targetSize) {
        const scaleFactor = targetSize / maxDimension;
        gltf.scene.scale.setScalar(scaleFactor);
        console.log(`📐 [LEVEL 6] Map scaled by ${scaleFactor.toFixed(4)}x to ${targetSize} units`);
      }
      
      // Center map at origin (subtract center offset)
      gltf.scene.position.sub(center.clone().multiplyScalar(gltf.scene.scale.x));
      
      // Recalculate bounding box after scaling/positioning
      const scaledBox = new THREE.Box3().setFromObject(gltf.scene);
      const scaledMin = scaledBox.min;
      const scaledMax = scaledBox.max;
      
      console.log("📏 [LEVEL 6] Map after scaling/positioning:", {
        min: scaledMin,
        max: scaledMax,
        size: scaledBox.getSize(new THREE.Vector3())
      });
      
      // Remove old ground plane if it exists (from previous load or fallback)
      if (level6State.groundPlane) {
        console.log("🗑️ [LEVEL 6] Removing old ground plane...");
        level6State.group.remove(level6State.groundPlane);
        if (level6State.groundPlane.geometry) level6State.groundPlane.geometry.dispose();
        if (level6State.groundPlane.material) level6State.groundPlane.material.dispose();
        level6State.groundPlane = null;
      }
      
      // CRITICAL: Remove grass system ground mesh if it exists (grass system creates its own ground)
      if (grassSystem && grassSystem.groundMesh) {
        console.log("🗑️ [LEVEL 6] Removing grass system ground mesh...");
        scene.remove(grassSystem.groundMesh);
        if (grassSystem.groundMesh.geometry) grassSystem.groundMesh.geometry.dispose();
        if (grassSystem.groundMesh.material) grassSystem.groundMesh.material.dispose();
        grassSystem.groundMesh = null;
      }
      if (grassSystem && grassSystem.colorMesh) {
        console.log("🗑️ [LEVEL 6] Removing grass system color mesh...");
        scene.remove(grassSystem.colorMesh);
        if (grassSystem.colorMesh.geometry) grassSystem.colorMesh.geometry.dispose();
        if (grassSystem.colorMesh.material) grassSystem.colorMesh.material.dispose();
        grassSystem.colorMesh = null;
      }
      if (grassSystem && grassSystem.blankMesh) {
        console.log("🗑️ [LEVEL 6] Removing grass system blank mesh...");
        scene.remove(grassSystem.blankMesh);
        if (grassSystem.blankMesh.geometry) grassSystem.blankMesh.geometry.dispose();
        if (grassSystem.blankMesh.material) grassSystem.blankMesh.material.dispose();
        grassSystem.blankMesh = null;
      }
      
      // Add map to level group
      level6State.group.add(gltf.scene);
      level6State.mapModel = gltf.scene;
      mapModel = gltf.scene; // Store in local variable for collision system
      mapLoaded = true;
      
      // Calculate ground level from map
      const mapBox = new THREE.Box3().setFromObject(gltf.scene);
      mapGroundY = mapBox.min.y;
      
      // Final visibility check
      console.log(`✅ [LEVEL 6] ${mapFileName} map added to scene successfully`);
      console.log("👁️ [LEVEL 6] Map visibility check:", {
        mapModelVisible: level6State.mapModel.visible,
        mapModelInGroup: level6State.group.children.includes(level6State.mapModel),
        groupVisible: level6State.group.visible,
        groupInScene: scene.children.includes(level6State.group)
      });
    } catch (error) {
      console.warn(`⚠️ [LEVEL 6] Failed to load GLTF map (${mapFileName}), using fallback ground plane:`, error);
      mapLoaded = false;
    }
  } else {
    mapLoaded = false;
  }
  
  // Fallback: Create simple flat ground plane if GLTF map failed to load
  if (!mapLoaded) {
    console.log("🔄 [LEVEL 6] Creating fallback ground plane...");
  const groundSize = 200;
  const groundGeometry = new THREE.PlaneGeometry(groundSize, groundSize);
  const groundMaterial = new THREE.MeshStandardMaterial({
    color: 0x333333, // Dark gray ground
    roughness: 0.8,
    metalness: 0.1
  });
  
  const groundPlane = new THREE.Mesh(groundGeometry, groundMaterial);
  groundPlane.rotation.x = -Math.PI / 2; // Rotate to be horizontal
  groundPlane.position.set(0, 0, 0);
  groundPlane.receiveShadow = true;
  level6State.group.add(groundPlane);
  level6State.groundPlane = groundPlane;
  }
  
  // Create collision mesh from GLTF map or fallback to simple plane
  if (collisionMesh) {
    scene.remove(collisionMesh);
    if (collisionMesh.geometry) collisionMesh.geometry.dispose();
    if (collisionMesh.material) collisionMesh.material.dispose();
  }
  
  let collisionGeometry;
  
  if (mapLoaded && (level6State.mapModel || mapModel)) {
    // Use mapModel from ground system if available, otherwise use level6State.mapModel
    const activeMapModel = mapModel || level6State.mapModel;
    // Use GLTF map geometry for collision - use map meshes directly without merging
    console.log("🗺️ [LEVEL 6] Creating collision mesh from GLTF map geometry...");
    
    // For performance, we'll use the map's meshes directly for collision
    // This avoids the UV1 attribute merging issue and works better with BVH
    // The collision system will check against all meshes in the map
    
    // Create a single collision mesh from the map's bounding box (simplified approach)
    // This gives us walkable terrain that matches the map's general shape
    const mapBox = new THREE.Box3().setFromObject(activeMapModel);
    const mapSize = mapBox.getSize(new THREE.Vector3());
    const mapCenter = mapBox.getCenter(new THREE.Vector3());
    
    console.log("📏 [LEVEL 6] Map collision bounds:", {
      size: mapSize,
      center: mapCenter,
      min: mapBox.min,
      max: mapBox.max
    });
    
    // CRITICAL: Find actual walkable surface using raycasting (not just bounding box min)
    // The bounding box min might include underground parts, so we need to find the actual surface
    let actualGroundY = mapBox.min.y; // Start with bounding box min as fallback
    
    // Raycast from above the map to find the actual walkable surface at spawn position
    const raycaster = new THREE.Raycaster();
    const spawnX = level6State.spawnPosition ? level6State.spawnPosition.x : mapCenter.x;
    const spawnZ = level6State.spawnPosition ? level6State.spawnPosition.z : mapCenter.z;
    const rayStart = new THREE.Vector3(spawnX, mapBox.max.y + 10, spawnZ); // Start well above the map
    const rayDir = new THREE.Vector3(0, -1, 0); // Cast downward
    
    raycaster.set(rayStart, rayDir);
    raycaster.far = mapSize.y + 20; // Cast through entire map height
    
    // Create temporary collision geometry from map meshes for raycasting
    const tempHits = [];
    activeMapModel.traverse((child) => {
      if (child.isMesh && child.geometry) {
        const hits = raycaster.intersectObject(child, false);
        if (hits.length > 0) {
          tempHits.push(...hits);
        }
      }
    });
    
    if (tempHits.length > 0) {
      // Find the highest hit point (closest to ray start) - this is the walkable surface
      tempHits.sort((a, b) => b.point.y - a.point.y); // Sort by Y descending
      actualGroundY = tempHits[0].point.y;
      console.log(`🎯 [LEVEL 6] Found walkable surface via raycast at Y: ${actualGroundY.toFixed(2)} (was using ${mapBox.min.y.toFixed(2)})`);
    } else {
      // Fallback: Use bounding box min, but add 10 units to account for underground parts
      actualGroundY = mapBox.min.y + 10;
      console.log(`⚠️ [LEVEL 6] Raycast found no surface, using adjusted bounding box min: ${actualGroundY.toFixed(2)}`);
    }
    
    // CRITICAL: Use actual map geometry for collision (not a flat plane!)
    // This allows walking on hills and terrain with ups and downs
    // We'll use the map model directly for collision detection
    
    // Create BVH trees for all map meshes for efficient collision detection
    console.log("🌳 [LEVEL 6] Creating BVH trees for map meshes...");
    let bvhCount = 0;
    activeMapModel.traverse((child) => {
      if (child.isMesh && child.geometry && child.geometry.isBufferGeometry) {
        try {
          // Create BVH tree for this mesh
          if (!child.geometry.boundsTree) {
            child.geometry.boundsTree = new MeshBVH(child.geometry);
            bvhCount++;
          }
          // Enable accelerated raycasting for this mesh
          child.raycast = acceleratedRaycast;
        } catch (bvhError) {
          console.warn(`⚠️ [LEVEL 6] Failed to create BVH for mesh "${child.name}":`, bvhError);
        }
      }
    });
    console.log(`✅ [LEVEL 6] Created ${bvhCount} BVH trees for map meshes`);
    
    // Store the map model as collision mesh (we'll use recursive intersection)
    // The ground detection system will use intersectObject with recursive=true
    level6State.collisionMapModel = activeMapModel;
    
    // CRITICAL: Verify collision map model is set correctly
    console.log(`✅ [LEVEL 6] Collision map model set:`, {
      hasModel: !!level6State.collisionMapModel,
      modelName: level6State.collisionMapModel?.name || 'unnamed',
      children: level6State.collisionMapModel?.children?.length || 0,
      inScene: level6State.collisionMapModel ? scene.children.includes(level6State.collisionMapModel) : false,
      inGroup: level6State.collisionMapModel ? level6State.group.children.includes(level6State.collisionMapModel) : false,
      visible: level6State.collisionMapModel?.visible ?? false
    });
    
    // For spawn position, use the actual ground level we found
    const groundY = actualGroundY;
    
    console.log(`✅ [LEVEL 6] Using actual map geometry for collision (${bvhCount} meshes with BVH trees)`);
    console.log(`📍 [LEVEL 6] Map ground level: Y=${groundY.toFixed(2)}, Map center: (${mapCenter.x.toFixed(2)}, ${mapCenter.y.toFixed(2)}, ${mapCenter.z.toFixed(2)})`);
    
    // CRITICAL: Update spawn position to be on top of the actual walkable surface
    if (level6State.spawnPosition) {
      level6State.spawnPosition.y = groundY + 2.0; // 2 units above ground
      console.log(`📍 [LEVEL 6] Updated spawn position to: (${level6State.spawnPosition.x.toFixed(2)}, ${level6State.spawnPosition.y.toFixed(2)}, ${level6State.spawnPosition.z.toFixed(2)})`);
    }
    
    // Create a dummy collision geometry for the collisionMesh variable (won't be used, but prevents errors)
    // The actual collision will use level6State.collisionMapModel
    collisionGeometry = new THREE.PlaneGeometry(1, 1); // Minimal dummy geometry
  } else {
    // Fallback: Create simple flat collision plane (for normal ground system)
    console.log("🔄 [LEVEL 6] Creating fallback collision plane...");
    const groundSize = 200;
    collisionGeometry = new THREE.PlaneGeometry(groundSize, groundSize);
  collisionGeometry.rotateX(-Math.PI / 2);
  collisionGeometry.translate(0, 0, 0);
  
    // CRITICAL: For normal ground system, ground is at y=0
    // Update spawn position to be at ground level (player feet on ground)
    if (level6State.spawnPosition) {
      level6State.spawnPosition.y = 0; // Player feet at ground (y=0)
      console.log(`📍 [LEVEL 6] Updated spawn position for normal ground: (${level6State.spawnPosition.x.toFixed(2)}, ${level6State.spawnPosition.y.toFixed(2)}, ${level6State.spawnPosition.z.toFixed(2)})`);
    }
  }
  
  // Create BVH tree for collision (only if we have a real collision geometry, not the dummy)
  // For Level 6 with GLTF map, we use the map model directly, so skip this
  if (mapLoaded && level6State.collisionMapModel) {
    // Map collision is handled by level6State.collisionMapModel with BVH trees on each mesh
    // We don't need a separate collisionMesh for Level 6
    console.log("✅ [LEVEL 6] Using map geometry for collision (no separate collision mesh needed)");
    // Set collisionMesh to null so ground detection knows to use the map model
    collisionMesh = null;
  } else {
    // Fallback: Create BVH tree for flat plane collision (if map didn't load)
    try {
      if (collisionGeometry && collisionGeometry.isBufferGeometry) {
    collisionGeometry.boundsTree = new MeshBVH(collisionGeometry);
        console.log("✅ [LEVEL 6] BVH tree created for fallback collision plane");
      } else {
        console.warn("⚠️ [LEVEL 6] Invalid geometry for BVH tree, skipping");
      }
  } catch (bvhError) {
      console.warn("⚠️ [LEVEL 6] Failed to create BVH tree (non-critical):", bvhError);
    }
    
    // Create invisible collision mesh (fallback flat plane)
    if (collisionGeometry && collisionGeometry.isBufferGeometry) {
  collisionMesh = new THREE.Mesh(collisionGeometry, new THREE.MeshBasicMaterial({ visible: false }));
  collisionMesh.visible = false;
  collisionMesh.name = "Level6_CollisionMesh";
  scene.add(collisionMesh);
      console.log("✅ [LEVEL 6] Fallback collision mesh created successfully!");
    } else {
      console.warn("⚠️ [LEVEL 6] Invalid geometry for collision mesh, skipping");
    }
  }
  
  // Ambient lighting
  const ambient = new THREE.AmbientLight(0xffffff, 0.5);
  level6State.group.add(ambient);
  const directional = new THREE.DirectionalLight(0xffffff, 0.8);
  directional.position.set(50, 100, 50);
  directional.castShadow = true;
  directional.shadow.mapSize.width = 2048;
  directional.shadow.mapSize.height = 2048;
  directional.shadow.camera.near = 0.5;
  directional.shadow.camera.far = 500;
  directional.shadow.camera.left = -100;
  directional.shadow.camera.right = 100;
  directional.shadow.camera.top = 100;
  directional.shadow.camera.bottom = -100;
  level6State.group.add(directional);
  
  // Create Level 6 chests (with small delay to ensure level is fully initialized)
  setTimeout(async () => {
    // CRITICAL: Load opened chests from database before creating chests (January 4, 2026)
    // This ensures chests appear as opened when warping back to a level
    if (resolvedDiscordId && chestSystem) {
      console.log("📥 [LEVEL 6] Loading opened chests from database...");
      await chestSystem.loadOpenedChests(resolvedDiscordId, API_BASE_URL);
    }
    createLevel6Chests();
  }, 100);
  
  level6State.built = true;
  console.log("🔥 [LEVEL 6] Phoenix Boss Arena built successfully. Spawn position:", level6State.spawnPosition);
}

// Calculate wave-based difficulty (returns difficulty object)
function calculateLevel4WaveDifficulty(waveNumber) {
  const isFinalWave = waveNumber > LEVEL4_WAVES_COUNT;
  const normalizedWave = isFinalWave ? LEVEL4_WAVES_COUNT + 1 : waveNumber; // Final wave = 13
  
  // Progressive difficulty scaling (1-13 waves)
  const waveProgress = (normalizedWave - 1) / (LEVEL4_WAVES_COUNT + 1); // 0 to 1
  
  // Difficulty multipliers (steeper curve for last 2 waves)
  const aggressiveness = isFinalWave ? 1.0 : Math.min(0.9, 0.2 + waveProgress * 0.7);
  const smartness = isFinalWave ? 1.0 : Math.min(0.95, 0.3 + waveProgress * 0.65);
  const speedMultiplier = isFinalWave ? 2.5 : 1.0 + (waveProgress * 1.5); // 1.0x to 2.5x
  const sizeMultiplier = isFinalWave ? 0.6 : 1.0 - (waveProgress * 0.4); // 1.0 to 0.6
  const dodgeDistance = isFinalWave ? 30 : 12 + (waveProgress * 18); // 12 to 30 units
  const targetChangeSpeed = isFinalWave ? 0.5 : 3.0 - (waveProgress * 2.5); // 3.0 to 0.5 seconds
  
  // Color based on wave (like Snake bosses)
  let color = new THREE.Color(0xffff00); // Yellow (default)
  let colorName = "yellow";
  if (waveNumber <= 3) {
    color = new THREE.Color(0xffff00); // Yellow (easy)
    colorName = "yellow";
  } else if (waveNumber <= 6) {
    color = new THREE.Color(0xffaa00); // Orange (medium)
    colorName = "orange";
  } else if (waveNumber <= 9) {
    color = new THREE.Color(0xff6600); // Dark orange (hard)
    colorName = "dark-orange";
  } else if (waveNumber <= 12) {
    color = new THREE.Color(0xff3300); // Red-orange (very hard)
    colorName = "red-orange";
  } else {
    color = new THREE.Color(0xff0000); // Red (extreme - final wave)
    colorName = "red";
  }
  
  return {
    waveNumber: normalizedWave,
    aggressiveness,
    smartness,
    speedMultiplier,
    sizeMultiplier,
    dodgeDistance,
    targetChangeSpeed,
    color,
    colorName,
    isFinalWave
  };
}

// Show wave countdown popup (like Snake/Tetris)
function showLevel4WaveCountdown(waveNumber, onComplete) {
  if (level4RiddleState.waveCountdownActive) return; // Already showing
  
  level4RiddleState.waveCountdownActive = true;
  level4RiddleState.waveCountdownTime = LEVEL4_WAVE_COUNTDOWN_TIME;
  level4RiddleState.waveCountdownCallback = onComplete; // Store callback
  
  // Create countdown popup element (mad mode style - smaller, top-right)
  let countdownElement = document.getElementById('level4-wave-countdown');
  if (!countdownElement) {
    countdownElement = document.createElement('div');
    countdownElement.id = 'level4-wave-countdown';
    countdownElement.style.cssText = `
      position: fixed;
      top: 20px;
      right: 20px;
      background: linear-gradient(135deg, rgba(0, 0, 0, 0.95), rgba(30, 30, 30, 0.95));
      color: #fff;
      padding: 12px 20px;
      border-radius: 8px;
      font-size: 18px;
      font-weight: bold;
      z-index: 10000;
      text-align: center;
      border: 2px solid #ffaa00;
      box-shadow: 0 4px 12px rgba(255, 170, 0, 0.6), inset 0 0 8px rgba(255, 255, 255, 0.2);
      backdrop-filter: blur(4px);
      user-select: none;
      pointer-events: none;
      font-family: 'Arial', sans-serif;
      animation: madModePulse 0.3s ease-out;
    `;
    document.body.appendChild(countdownElement);
  }
  
  const difficulty = calculateLevel4WaveDifficulty(waveNumber);
  const waveText = difficulty.isFinalWave ? "FINAL WAVE" : `WAVE ${waveNumber}`;
  const colorHex = `#${difficulty.color.getHexString()}`;
  countdownElement.style.borderColor = colorHex;
  countdownElement.style.boxShadow = `0 0 30px ${colorHex}80`;
  
  // Start countdown (will be updated in updateLevel4) - mad mode style
  countdownElement.innerHTML = `
    <div style="font-size: 14px; margin-bottom: 4px; color: ${colorHex}; opacity: 0.9;">${waveText}</div>
    <div style="font-size: 24px; color: ${colorHex}; font-weight: bold;">${Math.ceil(level4RiddleState.waveCountdownTime)}</div>
  `;
}

function spawnLevel4Cheeses(count = null) {
  // Wave-based spawning: spawn exactly 4 cheeses per wave (or 2 for final wave)
  const isFinalWave = level4RiddleState.currentWave > LEVEL4_WAVES_COUNT;
  const cheesesToSpawn = isFinalWave ? LEVEL4_FINAL_WAVE_CHEESES : LEVEL4_CHEESES_PER_WAVE;
  
  // Don't spawn if we've already caught 50
  if (level4RiddleState.cheesesCaught >= LEVEL4_CHEESES_TO_CATCH) {
    return;
  }
  
  // Don't spawn if there are already active cheeses (wait for wave completion)
  const activeCount = level4State.cheeses.filter(c => c.mesh && c.mesh.visible).length;
  if (activeCount > 0) return; // Wait for current wave to complete
  
  // Don't spawn more than needed
  const remaining = LEVEL4_CHEESES_TO_CATCH - level4RiddleState.cheesesCaught;
  const maxNeeded = Math.min(cheesesToSpawn, remaining);
  
  if (maxNeeded <= 0) return;

  const cheeseTexture = loadTexture("textures/blocks/cheese-stone.png");
  const arenaCenter = level4Config.origin.clone();
  arenaCenter.y = 1;
  
  // Get wave-based difficulty
  const difficulty = calculateLevel4WaveDifficulty(level4RiddleState.currentWave);
  
  // Smart spawn positioning (spread out, not all in one place)
  const playerPosition = new THREE.Vector3().lerpVectors(playerCollider.start, playerCollider.end, 0.5);
  
  for (let i = 0; i < maxNeeded; i++) {
    // Smart spawn position: spread out, avoid clustering
    let spawnPos;
    let attempts = 0;
    do {
      const angle = Math.random() * Math.PI * 2;
      // Spawn distance varies by wave (later waves spawn further/behind player)
      let distance;
      if (difficulty.isFinalWave) {
        // Final wave: spawn far away or behind player
        distance = 50 + Math.random() * 40; // 50-90 units
        if (Math.random() < 0.5) {
          // 50% chance to spawn behind player
          const playerAngle = Math.atan2(playerPosition.z - arenaCenter.z, playerPosition.x - arenaCenter.x);
          const behindAngle = playerAngle + Math.PI + (Math.random() - 0.5) * 0.8; // Behind ±40 degrees
          spawnPos = new THREE.Vector3(
            arenaCenter.x + Math.cos(behindAngle) * distance,
            arenaCenter.y + 8 + Math.random() * 6, // Higher variation
            arenaCenter.z + Math.sin(behindAngle) * distance
          );
        } else {
          spawnPos = new THREE.Vector3(
            arenaCenter.x + Math.cos(angle) * distance,
            arenaCenter.y + 8 + Math.random() * 6,
            arenaCenter.z + Math.sin(angle) * distance
          );
        }
      } else if (level4RiddleState.currentWave <= 4) {
        // Easy waves: spawn in visible areas
        distance = 25 + Math.random() * 35; // 25-60 units
        spawnPos = new THREE.Vector3(
          arenaCenter.x + Math.cos(angle) * distance,
          arenaCenter.y + 8 + Math.random() * 4,
          arenaCenter.z + Math.sin(angle) * distance
        );
      } else {
        // Medium/hard waves: mixed positions
        distance = 30 + Math.random() * 50; // 30-80 units
        if (Math.random() < 0.3) {
          // 30% chance behind player
          const playerAngle = Math.atan2(playerPosition.z - arenaCenter.z, playerPosition.x - arenaCenter.x);
          const behindAngle = playerAngle + Math.PI + (Math.random() - 0.5) * 1.0;
          spawnPos = new THREE.Vector3(
            arenaCenter.x + Math.cos(behindAngle) * distance,
            arenaCenter.y + 8 + Math.random() * 5,
            arenaCenter.z + Math.sin(behindAngle) * distance
          );
        } else {
          spawnPos = new THREE.Vector3(
            arenaCenter.x + Math.cos(angle) * distance,
            arenaCenter.y + 8 + Math.random() * 5,
            arenaCenter.z + Math.sin(angle) * distance
          );
        }
      }
      
      // Check minimum distance from other cheeses (20 units)
      const tooClose = level4State.cheeses.some(c => 
        c.mesh && c.mesh.visible && spawnPos.distanceTo(c.mesh.position) < 20
      );
      if (!tooClose || attempts > 10) break;
      attempts++;
    } while (attempts < 20);
    
    const cheese = new FloatingCheese({
      texture: cheeseTexture,
      center: arenaCenter.clone(),
      roamRadius: 70,
      baseHeight: 8,
      levelId: "CHEESE_TEMPLE_LEVEL4",
      gameFieldSize: level4Config.size,
      waveNumber: level4RiddleState.currentWave,
      difficulty: difficulty
    });
    
    // Apply wave-based difficulty
    cheese.mesh.scale.multiplyScalar(difficulty.sizeMultiplier);
    cheese.moveSpeed *= difficulty.speedMultiplier;
    cheese.floatSpeed *= difficulty.speedMultiplier;
    cheese.aggressiveness = difficulty.aggressiveness;
    cheese.smartness = difficulty.smartness;
    cheese.dodgeDistance = difficulty.dodgeDistance;
    cheese.targetChangeInterval = difficulty.targetChangeSpeed;
    
    // Apply wave color (emissive glow)
    cheese.mesh.material.emissive = difficulty.color.clone();
    cheese.mesh.material.emissiveIntensity = 0.4 + (level4RiddleState.currentWave * 0.03); // 0.4 to 0.8
    cheese.waveColor = difficulty.color.clone();
    cheese.waveColorName = difficulty.colorName;
    
    // Final wave: bigger and more aggressive
    if (difficulty.isFinalWave) {
      cheese.mesh.scale.multiplyScalar(1.2); // 20% bigger (but still harder due to speed/aggressiveness)
      cheese.aggressiveness = 1.0;
      cheese.smartness = 1.0;
    }
    
    cheese.mesh.position.copy(spawnPos);
    cheese.center = arenaCenter.clone();
    level4State.group.add(cheese.mesh);
    level4State.cheeses.push(cheese);
  }
  
  const waveText = difficulty.isFinalWave ? "FINAL WAVE" : `Wave ${level4RiddleState.currentWave}`;
  console.log(`🎯 [LEVEL 4] Spawned ${maxNeeded} cheeses for ${waveText} (${level4RiddleState.cheesesCaught}/${LEVEL4_CHEESES_TO_CATCH} caught, color: ${difficulty.colorName})`);
}

function createLevel4TriggerBlock() {
  const blockSize = 1;
  const geometry = new THREE.BoxGeometry(blockSize, blockSize, blockSize);
  // Use normal cheese-stone.png texture
  const texture = loadTexture("textures/blocks/cheese-stone.png");
  // Use MeshLambertMaterial like Level 2/3 trigger block
  const material = new THREE.MeshLambertMaterial({
    map: texture,
    emissive: new THREE.Color(0x000000), // No yellow glow - normal texture
    emissiveIntensity: 0.0
  });
  const triggerBlock = new THREE.Mesh(geometry, material);
  triggerBlock.scale.set(1.4, 0.35, 1.4); // Same scale as Level 2/3
  
  // Position block same as Level 2/3: blockHeight = 0.35, center at floorY + (blockHeight / 2) + 0.05
  const blockHeight = blockSize * 0.35; // Scaled height = 0.35
  const floorY = level4Config.origin.y; // Floor is at y: 0
  const blockCenterY = floorY + (blockHeight / 2) + 0.05; // Center at 0.225, top at 0.4 (same as Level 2/3)
  
  triggerBlock.position.set(
    level4Config.origin.x - 20,
    blockCenterY,
    level4Config.origin.z - 30
  );
  triggerBlock.visible = true;
  triggerBlock.userData.isTrigger = true;
  level4State.group.add(triggerBlock);
  level4RiddleState.triggerBlock = triggerBlock;

  // Visual clone for animation (same as Level 2/3)
  const visualMaterial = material.clone();
  const visualBlock = new THREE.Mesh(geometry.clone(), visualMaterial);
  visualBlock.scale.copy(triggerBlock.scale);
  visualBlock.position.copy(triggerBlock.position);
  visualBlock.userData.restY = visualBlock.position.y;
  visualBlock.userData.pressedY = visualBlock.position.y - 0.2;
  visualBlock.userData.lerpSpeed = 6;
  level4State.group.add(visualBlock);
  level4RiddleState.triggerBlockVisual = visualBlock;
  level4RiddleState.triggerBlockTargetY = visualBlock.userData.restY;

  // Hide the collider block, show only the visual
  triggerBlock.visible = false;
  console.log("🧩 [LEVEL 4] Hidden cheese stone trigger block created at:", {
    x: triggerBlock.position.x.toFixed(2),
    y: triggerBlock.position.y.toFixed(2),
    z: triggerBlock.position.z.toFixed(2),
    blockTopY: (triggerBlock.position.y + blockHeight / 2).toFixed(2),
    floorY: floorY.toFixed(2)
  });
}

// NEW: Spawn individual Level 4 Monster
// FOLLOWS RULE #14: Use SkeletonUtils.clone() for GLTF models with animations
// PATTERN MATCHES Level 3 (which works perfectly) but with cloning for multiple instances
async function spawnLevel4Monster(monsterPath, spawnPosition, waveNumber, sizeMultiplier, speedMultiplier, isFinalWave) {
  try {
    const gltf = await loadModel(monsterPath);
    
    // CRITICAL: Use SkeletonUtils.clone() for GLTF models with skinned meshes (animations)
    // Rule #14: Standard clone() doesn't preserve skeleton structure, causing rendering issues
    // SkeletonUtils.clone() properly clones skinned meshes with their skeleton intact
    // This matches Level 3 pattern but adds cloning for multiple instances (3 monsters per wave)
    let monsterMesh;
    try {
      monsterMesh = SkeletonUtils.clone(gltf.scene);
    } catch (cloneError) {
      console.error(`❌ [LEVEL 4] SkeletonUtils.clone() failed for ${monsterPath}:`, cloneError);
      // Fallback to standard clone (may cause issues but better than crashing)
      console.warn(`⚠️ [LEVEL 4] Falling back to standard clone() for ${monsterPath} - skeleton may not work properly`);
      monsterMesh = gltf.scene.clone(true);
    }
    
    // Validate skeleton after cloning
    monsterMesh.traverse((child) => {
      if (child.isSkinnedMesh && child.skeleton) {
        if (!child.skeleton.bones || child.skeleton.bones.length === 0) {
          console.warn(`⚠️ [LEVEL 4] Invalid skeleton for ${monsterPath} - skeleton has no bones`);
        }
      }
    });
    
    // Apply size multiplier (ensure it's large enough to be visible)
    // Level 3 uses baseScale 0.4-1.2, so we need similar scaling
    // For wave 1-2, sizeMultiplier is 1.2, which should be visible
    // But ensure minimum scale for visibility
    const finalScale = Math.max(sizeMultiplier, 0.5); // Minimum 0.5x scale
    monsterMesh.scale.set(finalScale, finalScale, finalScale);
    
    console.log(`🐉 [LEVEL 4] Monster scale applied:`, {
      requested: sizeMultiplier,
      final: finalScale,
      wave: waveNumber
    });
    
    // Determine if this is a flying monster (based on path)
    const isFlying = monsterPath.includes('/Flying/');
    
    // Set spawn position
    let spawnY;
    if (isFlying) {
      // Flying monsters: random height between 3-12 units
      spawnY = level4Config.origin.y + 3 + Math.random() * 9;
    } else {
      // Ground monsters: on ground level (match Level 3 pattern exactly)
      spawnY = level4Config.origin.y + 1.2 + (sizeMultiplier - 0.4) * 0.5;
    }
    monsterMesh.position.set(spawnPosition.x, spawnY, spawnPosition.z);
    
    // CRITICAL: Store baseY like Level 3 does (prevents falling/standing issues)
    const baseY = spawnY;
    
    // Set up animations (same as Level 3 pattern)
    let mixer = null;
    const animations = {};
    if (gltf.animations && gltf.animations.length > 0) {
      try {
        mixer = new THREE.AnimationMixer(monsterMesh);
        gltf.animations.forEach((clip) => {
          try {
            const action = mixer.clipAction(clip);
            if (action) {
              animations[clip.name] = action;
            }
          } catch (actionError) {
            console.warn(`⚠️ [LEVEL 4] Failed to create animation action for ${clip.name}:`, actionError);
          }
        });
        // Play appropriate animation
        if (animations['Walk'] || animations['walk']) {
          const walkAnim = animations['Walk'] || animations['walk'];
          walkAnim.reset().fadeIn(0.2).play().setLoop(THREE.LoopRepeat);
        } else if (animations['Run'] || animations['run']) {
          const runAnim = animations['Run'] || animations['run'];
          runAnim.reset().fadeIn(0.2).play().setLoop(THREE.LoopRepeat);
        } else if (animations['Fly'] || animations['fly']) {
          const flyAnim = animations['Fly'] || animations['fly'];
          flyAnim.reset().fadeIn(0.2).play().setLoop(THREE.LoopRepeat);
        } else if (Object.keys(animations).length > 0) {
          const firstAnimKey = Object.keys(animations)[0];
          const firstAnim = animations[firstAnimKey];
          firstAnim.reset().fadeIn(0.2).play().setLoop(THREE.LoopRepeat);
        }
      } catch (animationError) {
        console.warn(`⚠️ [LEVEL 4] Animation setup failed for ${monsterPath}, continuing without animations:`, animationError);
        mixer = null; // Disable animations if setup fails
      }
    }
    
    // CRITICAL: Initial target position should be far from spawn (ensure visible movement)
    const origin = level4Config.origin;
    const size = level4Config.size;
    const margin = 20;
    
    // Make initial target position at least 15-30 units away from spawn (ensures visible movement)
    let targetX, targetZ;
    let attempts = 0;
    do {
      targetX = origin.x + (Math.random() * (size - margin * 2) - (size / 2 - margin));
      targetZ = origin.z + (Math.random() * (size - margin * 2) - (size / 2 - margin));
      const distFromSpawn = Math.sqrt(
        Math.pow(targetX - spawnPosition.x, 2) + 
        Math.pow(targetZ - spawnPosition.z, 2)
      );
      attempts++;
      // Ensure target is at least 15 units away, but don't loop forever
      if (distFromSpawn >= 15 || attempts > 10) break;
    } while (attempts < 10);
    
    let targetY = spawnY;
    if (isFlying) {
      // Flying monsters: random height between 3-12 units
      targetY = level4Config.origin.y + 3 + Math.random() * 9;
    }
    const targetPosition = new THREE.Vector3(targetX, targetY, targetZ);
    
    // Monster speed (base speed * multiplier)
    const baseSpeed = isFlying ? 4.0 : 3.0;
    const speed = baseSpeed * speedMultiplier;
    
    // Monster properties
    const monster = {
      mesh: monsterMesh,
      mixer: mixer,
      animations: animations,
      targetPosition: targetPosition,
      speed: speed,
      path: monsterPath,
      waveNumber: waveNumber,
      isFlying: isFlying,
      isFinalWave: isFinalWave,
      health: isFinalWave ? LEVEL4_FINAL_MONSTER_WAVE_HEALTH : 1, // Final wave: 2 hits
      defeated: false,
      sizeMultiplier: sizeMultiplier,
      baseY: baseY, // Store baseY for consistent Y positioning (matches Level 3)
      lastProjectileTime: 0 // For final wave shooting
    };
    
    // Ensure monster mesh is visible and properly positioned
    monsterMesh.visible = true;
    
    // Make sure all children are visible and raycastable
    // CRITICAL: After skeleton conversion, ensure geometry is properly set up for raycasting
    monsterMesh.traverse((child) => {
      if (child.isMesh) {
        child.visible = true;
        
        // Ensure geometry is ready for rendering (same as Level 3)
        if (child.geometry) {
          child.geometry.computeBoundingBox();
          child.geometry.computeBoundingSphere();
        }
        
        // Ensure materials are properly set (same as Level 3)
        if (child.material) {
          if (Array.isArray(child.material)) {
            child.material.forEach(mat => {
              if (mat) mat.visible = true;
            });
          } else {
            child.material.visible = true;
          }
        }
      }
    });
    
    // Add to group (same as Level 3 pattern)
    level4State.group.add(monsterMesh);
    
    // CRITICAL: Ensure group is in scene and visible (EXACTLY like Level 3)
    if (!scene.children.includes(level4State.group)) {
      scene.add(level4State.group);
      console.log("🐉 [LEVEL 4] Added level4State.group to scene");
    }
    level4State.group.visible = true;
    
    // CRITICAL: Verify monster mesh is actually visible and in scene
    // Count visible child meshes
    let visibleMeshCount = 0;
    let totalMeshCount = 0;
    monsterMesh.traverse((child) => {
      if (child.isMesh) {
        totalMeshCount++;
        if (child.visible) visibleMeshCount++;
        // Check if skeleton is valid
        if (child.isSkinnedMesh && child.skeleton) {
          const skeletonValid = child.skeleton.bones && child.skeleton.bones.length > 0;
          if (!skeletonValid) {
            console.warn(`⚠️ [LEVEL 4] Invalid skeleton for mesh in ${monsterPath}`);
          }
        }
      }
    });
    
    console.log(`🐉 [LEVEL 4] Monster mesh verification:`, {
      meshVisible: monsterMesh.visible,
      visibleChildMeshes: `${visibleMeshCount}/${totalMeshCount}`,
      meshInGroup: level4State.group.children.includes(monsterMesh),
      groupVisible: level4State.group.visible,
      groupInScene: scene.children.includes(level4State.group),
      position: { x: monsterMesh.position.x.toFixed(2), y: monsterMesh.position.y.toFixed(2), z: monsterMesh.position.z.toFixed(2) },
      scale: { x: monsterMesh.scale.x.toFixed(2), y: monsterMesh.scale.y.toFixed(2), z: monsterMesh.scale.z.toFixed(2) },
      children: monsterMesh.children.length,
      meshCount: monsterMesh.children.filter(c => c.isMesh).length
    });
    
    level4State.monsters.push(monster);
    
    // Verify monster is in scene with comprehensive debug info
    const monsterWorldPos = new THREE.Vector3();
    monsterMesh.getWorldPosition(monsterWorldPos);
    const monsterWorldScale = new THREE.Vector3();
    monsterMesh.getWorldScale(monsterWorldScale);
    
    console.log(`🐉 [LEVEL 4] Monster added to scene:`, {
      inGroup: level4State.group.children.includes(monsterMesh),
      groupVisible: level4State.group.visible,
      groupInScene: scene.children.includes(level4State.group),
      monsterVisible: monsterMesh.visible,
      localPosition: monsterMesh.position.toArray().map(n => n.toFixed(2)),
      worldPosition: monsterWorldPos.toArray().map(n => n.toFixed(2)),
      localScale: monsterMesh.scale.toArray().map(n => n.toFixed(2)),
      worldScale: monsterWorldScale.toArray().map(n => n.toFixed(2)),
      meshChildren: monsterMesh.children.length
    });
    
    const monsterNameRaw = monsterPath.split('/').pop().replace('.gltf', '');
    const monsterName = monsterNameRaw.charAt(0).toUpperCase() + monsterNameRaw.slice(1);
    console.log(`🐉 [LEVEL 4] Monster "${monsterName}" spawned at position:`, {
      x: monsterMesh.position.x.toFixed(2),
      y: monsterMesh.position.y.toFixed(2),
      z: monsterMesh.position.z.toFixed(2),
      worldX: monsterWorldPos.x.toFixed(2),
      worldY: monsterWorldPos.y.toFixed(2),
      worldZ: monsterWorldPos.z.toFixed(2),
      scale: `${(finalScale * 100).toFixed(0)}%`,
      worldScale: `${(monsterWorldScale.x * 100).toFixed(0)}%`,
      wave: waveNumber,
      flying: isFlying,
      visible: monsterMesh.visible,
      inScene: level4State.group.children.includes(monsterMesh),
      totalMonsters: level4State.monsters.length
    });
    
  } catch (error) {
    console.error("❌ [LEVEL 4] Failed to spawn monster:", error, {
      path: monsterPath,
      waveNumber: waveNumber,
      position: spawnPosition
    });
    throw error; // Re-throw so spawnMonsterWave can catch it
  }
}

// NEW: Spawn Monster Wave (spawns 3 monsters in triangle formation)
async function spawnMonsterWave(waveNumber) {
  const waveIndex = waveNumber - 1; // 0-based index
  if (waveIndex < 0 || waveIndex >= LEVEL4_MONSTER_WAVE_QUEUE.length) {
    console.error("❌ [LEVEL 4] Invalid monster wave number:", waveNumber);
    return;
  }
  
  const monsterPaths = LEVEL4_MONSTER_WAVE_QUEUE[waveIndex];
  if (!monsterPaths || monsterPaths.length !== LEVEL4_MONSTERS_PER_WAVE) {
    console.error("❌ [LEVEL 4] Invalid monster wave queue:", waveIndex);
    return;
  }
  
  const isFinalWave = waveNumber > LEVEL4_MONSTER_WAVES_COUNT;
  
  // Calculate size multipliers based on wave
  let baseSizeMultiplier;
  const sizeVariations = [1.2, 1.0, 0.9]; // For waves 3-8 variation
  
  if (waveNumber <= 2) {
    baseSizeMultiplier = 1.2; // 120% - LARGE
  } else if (waveNumber <= 4) {
    baseSizeMultiplier = 1.1; // 110% base with variation
  } else if (waveNumber <= 6) {
    baseSizeMultiplier = 1.0; // 100% base with variation
  } else if (waveNumber <= 8) {
    baseSizeMultiplier = 0.85; // 85% base with variation
  } else if (waveNumber <= 10) {
    baseSizeMultiplier = 1.5; // 150% - HUGE flying monsters
  } else {
    baseSizeMultiplier = 1.8; // 180% - MASSIVE final wave
  }
  
  // Calculate speed multiplier
  let speedMultiplier = 1.0;
  if (waveNumber <= 2) speedMultiplier = 1.0;
  else if (waveNumber <= 4) speedMultiplier = 1.2;
  else if (waveNumber <= 6) speedMultiplier = 1.4;
  else if (waveNumber <= 8) speedMultiplier = 1.6;
  else if (waveNumber <= 10) speedMultiplier = 2.0;
  else speedMultiplier = 2.5; // Final wave
  
  // Spawn position (triangle formation, IN FRONT OF player for visibility)
  const origin = level4Config.origin;
  const size = level4Config.size;
  const margin = 20;
  const playerSpawn = level4Config.spawnPosition;
  
  // CRITICAL: Spawn monsters IN FRONT of player (positive Z direction) for immediate visibility
  // Player spawns at z: 950, looking forward (positive Z), so spawn monsters at z: 960-980 (in front)
  const spawnDistance = 15 + Math.random() * 10; // 15-25 units IN FRONT of player
  const spawnAngle = (Math.PI / 6) + (Math.random() * (Math.PI / 3)); // 30-90 degrees (front-right quadrant)
  // Spawn in front of player (positive Z direction from player spawn)
  const forwardOffset = spawnDistance * 0.8; // Most of the distance forward
  const sideOffset = (Math.random() - 0.5) * spawnDistance * 0.6; // Some side variation
  const centerX = playerSpawn.x + sideOffset;
  const centerZ = playerSpawn.z + forwardOffset; // IN FRONT (positive Z)
  
  // Clamp to arena bounds
  const minX = origin.x - size / 2 + margin;
  const maxX = origin.x + size / 2 - margin;
  const minZ = origin.z - size / 2 + margin;
  const maxZ = origin.z + size / 2 - margin;
  const finalCenterX = Math.max(minX, Math.min(maxX, centerX));
  const finalCenterZ = Math.max(minZ, Math.min(maxZ, centerZ));
  
  const triangleRadius = 8; // Distance between monsters
  
  console.log(`🐉 [LEVEL 4] Spawning wave ${waveNumber} near player:`, {
    playerSpawn: { x: playerSpawn.x.toFixed(2), z: playerSpawn.z.toFixed(2) },
    spawnCenter: { x: finalCenterX.toFixed(2), z: finalCenterZ.toFixed(2) },
    distance: Math.sqrt(Math.pow(finalCenterX - playerSpawn.x, 2) + Math.pow(finalCenterZ - playerSpawn.z, 2)).toFixed(2)
  });
  
  // Spawn all 3 monsters (await each one)
  for (let i = 0; i < monsterPaths.length; i++) {
    // Triangle formation: position monsters in equilateral triangle
    const angle = (Math.PI * 2 * i) / 3; // 0, 120°, 240°
    const offsetX = Math.cos(angle) * triangleRadius;
    const offsetZ = Math.sin(angle) * triangleRadius;
    
    const spawnX = finalCenterX + offsetX;
    const spawnZ = finalCenterZ + offsetZ;
    
    // Size variation for waves 3-8
    let sizeMultiplier = baseSizeMultiplier;
    if (waveNumber >= 3 && waveNumber <= 8) {
      sizeMultiplier = baseSizeMultiplier * sizeVariations[i % sizeVariations.length];
    }
    
    try {
      await spawnLevel4Monster(
        monsterPaths[i],
        new THREE.Vector3(spawnX, 0, spawnZ), // Y will be adjusted in spawn function
        waveNumber,
        sizeMultiplier,
        speedMultiplier,
        isFinalWave
      );
      console.log(`🐉 [LEVEL 4] Monster ${i + 1}/3 spawned for wave ${waveNumber}`);
    } catch (error) {
      console.error(`❌ [LEVEL 4] Failed to spawn monster ${i + 1} for wave ${waveNumber}:`, error);
    }
  }
  
  const waveText = isFinalWave ? "FINAL BOSS WAVE" : `Monster Wave ${waveNumber}`;
  console.log(`🐉 [LEVEL 4] Completed spawning ${monsterPaths.length} monsters for ${waveText}. Active monsters: ${level4State.monsters.length}`);
  
  // Debug: Log all active monsters to verify they're in the scene
  if (level4State.monsters.length > 0) {
    console.log(`🐉 [LEVEL 4] ✅ Active monsters (${level4State.monsters.length}):`, level4State.monsters.map(m => ({
      name: m.path.split('/').pop(),
      position: [m.mesh.position.x.toFixed(2), m.mesh.position.y.toFixed(2), m.mesh.position.z.toFixed(2)],
      visible: m.mesh.visible,
      inScene: level4State.group.children.includes(m.mesh)
    })));
  } else {
    console.error("❌ [LEVEL 4] No monsters in array after spawning wave! Check spawn errors above.");
  }
}

function resetLevel4Progress() {
  // Reset cheese wave system
  level4RiddleState.currentWave = 1;
  level4RiddleState.cheesesInCurrentWave = 0;
  level4RiddleState.waveCountdownActive = false;
  level4RiddleState.waveCountdownTime = 0;
  level4RiddleState.step0Complete = false;
  level4RiddleState.step0StandingSoundPlayed = false;
  level4RiddleState.triggerBlockTimer = 0;
  level4RiddleState.step0TraitUnlocked = false;
  level4RiddleState.step1Active = false;
  level4RiddleState.cheesesCaught = 0;
  // Remove countdown element if exists
  const countdownElement = document.getElementById('level4-wave-countdown');
  if (countdownElement && countdownElement.parentNode) {
    countdownElement.parentNode.removeChild(countdownElement);
  }
  level4RiddleState.step1TraitUnlocked = false;
  // NEW: Reset monster wave system
  level4RiddleState.step2Active = false;
  level4RiddleState.monstersDefeated = 0;
  level4RiddleState.currentMonsterWave = 1;
  level4RiddleState.monstersInCurrentWave = 0;
  level4RiddleState.monsterWaveCountdownActive = false;
  level4RiddleState.monsterWaveCountdownTime = 0;
  // Remove monster wave countdown element if exists
  const monsterCountdownElement = document.getElementById('level4-monster-wave-countdown');
  if (monsterCountdownElement && monsterCountdownElement.parentNode) {
    monsterCountdownElement.parentNode.removeChild(monsterCountdownElement);
  }
  level4RiddleState.step2TraitUnlocked = false;
  level4RiddleState.step2Complete = false;
  level4RiddleState.step3Complete = false;
  level4RiddleState.step3TraitUnlocked = false;
  // Clear monsters and projectiles
  level4State.monsters.forEach((monster) => {
    if (monster.mesh && monster.mesh.parent) {
      monster.mesh.parent.remove(monster.mesh);
    }
    if (monster.mixer) {
      monster.mixer.stopAllAction();
    }
  });
  level4State.monsters = [];
  level4State.monsterProjectiles.forEach((projectile) => {
    if (projectile.mesh && projectile.mesh.parent) {
      projectile.mesh.parent.remove(projectile.mesh);
    }
  });
  level4State.monsterProjectiles = [];
  level4RiddleState.difficultyLevel = 1;
  // Reset heat/overload system
  level4State.weaponHeat = 0;
  level4State.isOverheated = false;
  level4State.lastOverheatTime = 0;
  level4State.tripleShotActive = false;
  level4State.tripleShotBulletsRemaining = 0;
  if (level4RiddleState.triggerBlock) {
    level4RiddleState.triggerBlock.visible = false;
  }
  if (level4RiddleState.triggerBlockVisual) {
    level4RiddleState.triggerBlockVisual.visible = true;
    level4RiddleState.triggerBlockVisual.position.y = level4RiddleState.triggerBlockVisual.userData.restY;
  }
  // Remove cheeses
  level4State.cheeses.forEach(cheese => {
    if (cheese.mesh && cheese.mesh.parent) {
      cheese.mesh.parent.remove(cheese.mesh);
    }
  });
  // Remove weapon viewmodel
  removeLevel4WeaponViewmodel();
  level4State.weaponBobPhase = 0;
  level4State.weaponRecoilOffset = 0;
  level4State.lastShotTime = 0;
  level4State.currentWeaponSlot = 1; // Reset to default weapon slot
  level4State.weaponSlots = {}; // Clear weapon cache
  
  // Reset weapon system if available
  if (weaponSystem && typeof weaponSystem.reset === 'function') {
    weaponSystem.reset();
  }
  level4State.cheeses = [];
  // CRITICAL: Reset intro state so intro toast can show again
  level4State.introShown = false;
  if (level4State.introToastElement && document.body.contains(level4State.introToastElement)) {
    document.body.removeChild(level4State.introToastElement);
    level4State.introToastElement = null;
  }
  
  if (level4State.portal) {
    level4State.portal.visible = false;
  }
  level4State.portalActive = false;
  level4State.completionScreenShown = false;
}

function checkLevel4TriggerBlockStanding() {
  if (!level4RiddleState.triggerBlock) return false;
  const block = level4RiddleState.triggerBlock;
  const blockTopY = block.position.y + (block.scale.y * 0.5);
  const playerFeet = playerCollider.start;
  const horizontalDistance = Math.sqrt(
    Math.pow(playerFeet.x - block.position.x, 2) + Math.pow(playerFeet.z - block.position.z, 2)
  );
  const verticalDistance = Math.abs(playerFeet.y - blockTopY);
  return horizontalDistance < 1.2 && verticalDistance < 0.8;
}

async function updateLevel4Step0(delta) {
  const isStandingOnTrigger = checkLevel4TriggerBlockStanding();
  
  if (isStandingOnTrigger) {
    if (!level4RiddleState.step0StandingSoundPlayed) {
      playCheesePlatformSound();
      level4RiddleState.step0StandingSoundPlayed = true;
    }
    level4RiddleState.triggerBlockTimer += delta;
    if (level4RiddleState.triggerBlockTimer >= RIDDLE_AIM_TIME && !level4RiddleState.step0Complete) {
      level4RiddleState.step0Complete = true;
      level4RiddleState.triggerBlockTimer = RIDDLE_AIM_TIME;
      if (level4RiddleState.triggerBlock) {
        level4RiddleState.triggerBlock.visible = false;
      }
      if (level4RiddleState.triggerBlockVisual) {
        level4RiddleState.triggerBlockVisual.visible = false;
      }
      showRiddleToast("Step 1 begins! The First Shot awaits...", {
        id: "level4_step1_start",
        duration: 5000
      });
      if (!level4RiddleState.step0TraitUnlocked) {
        unlockLevel4Trait(LEVEL4_STEP0_TRAIT, "Level 4 Step 0");
      }
      awardLevel4DspoincReward("CHEESE_TEMPLE_LEVEL4_STEP0", 100, "Level 4 Step 0");
      // Start Step 1 - Show countdown and spawn first wave
      level4RiddleState.step1Active = true;
      createLevel4ProgressHUD(); // Create progress HUD
      // Show countdown for first wave
      showLevel4WaveCountdown(level4RiddleState.currentWave, () => {
        spawnLevel4Cheeses(); // Spawn first wave after countdown
      });
      // CRITICAL: Ensure weapons are loaded (they should already be loaded at Level 4 start)
      // If weapons aren't loaded yet, load them now
      if (isFirstPerson()) {
        if (weaponSystem && typeof weaponSystem.loadWeapon === 'function') {
          const hasWeapon = weaponSystem.weaponViewmodel !== null && weaponSystem.camera && weaponSystem.camera.children.includes(weaponSystem.weaponViewmodel);
          if (!hasWeapon) {
            // Load slot 1 (active weapon) if not already loaded
            console.log("🔫 [LEVEL 4] Weapon not loaded, loading weapon slot 1 (active)...");
            await weaponSystem.loadWeapon(1, null, false); // false = active weapon
            console.log("✅ [LEVEL 4] Weapon slot 1 loaded");
          } else {
            console.log("✅ [LEVEL 4] Weapon already loaded from Level 4 start");
          }
          
          // Ensure slot 2 is preloaded (check if it's cached)
          if (!weaponSystem.weapons || !weaponSystem.weapons[2]) {
            console.log("🔫 [LEVEL 4] Preloading weapon slot 2 (SF13)...");
            weaponSystem.loadWeapon(2, null, true).then((weapon) => { // true = preload only
              if (weapon) {
                console.log("✅ [LEVEL 4] Weapon slot 2 preloaded successfully (cached, not attached)");
              } else {
                console.warn("⚠️ [LEVEL 4] Weapon slot 2 preload returned null");
              }
            }).catch(err => {
              console.error("❌ [LEVEL 4] Failed to preload weapon slot 2:", err);
            });
          } else {
            console.log("✅ [LEVEL 4] Weapon slot 2 already preloaded");
          }
        } else if (typeof loadLevel4WeaponViewmodel === 'function') {
          // Legacy fallback
          const hasWeapon = level4State.weaponViewmodel !== null;
          if (!hasWeapon) {
            await loadLevel4WeaponViewmodel(null, 1);
          }
          // Preload slot 2
          loadLevel4WeaponViewmodel(null, 2).catch(err => {
            console.warn("⚠️ [LEVEL 4] Failed to preload weapon slot 2:", err);
          });
        }
      }
      // Automatically request pointer lock for shooting (if not already locked and not in joystick view)
      if (playerControls && !playerControls.getPointerLockControls().isLocked && !isJoystickView() && !isGamePaused) {
        try {
          playerControls.getPointerLockControls().lock();
          console.log("🎯 [LEVEL 4] Pointer lock automatically requested for Step 1");
        } catch (e) {
          console.log("🎯 [LEVEL 4] Pointer lock auto-request failed, showing hint:", e);
          showRiddleToast("Click to lock pointer and start shooting!", {
            id: "level4_pointer_lock_hint",
            duration: 4000
          });
        }
      } else if (playerControls && !playerControls.getPointerLockControls().isLocked && !isJoystickView()) {
        // Show hint if pointer lock couldn't be auto-requested (e.g., game is paused)
        showRiddleToast("Click to lock pointer and start shooting!", {
          id: "level4_pointer_lock_hint",
          duration: 4000
        });
      }
      console.log("🎯 [LEVEL 4] Step 0 complete! Step 1 active - hunt 2 cheeses with weapon!");
    }
  } else {
    level4RiddleState.triggerBlockTimer = Math.max(0, level4RiddleState.triggerBlockTimer - delta * 0.5);
    level4RiddleState.step0StandingSoundPlayed = false;
  }
  
  // Update visual block animation
  const targetY = isStandingOnTrigger && level4RiddleState.triggerBlockVisual
    ? level4RiddleState.triggerBlockVisual.userData?.pressedY ?? level4RiddleState.triggerBlockVisual.position.y
    : level4RiddleState.triggerBlockVisual?.userData?.restY ?? level4RiddleState.triggerBlockVisual?.position.y;
  level4RiddleState.triggerBlockTargetY = targetY;
  updateLevel4TriggerBlockVisual(delta);
}

function updateLevel4TriggerBlockVisual(delta) {
  const visual = level4RiddleState.triggerBlockVisual;
  if (!visual || !visual.visible) return;
  const targetY = level4RiddleState.triggerBlockTargetY ?? visual.position.y;
  const speed = visual.userData?.lerpSpeed ?? 6;
  const t = Math.min(1, delta * speed);
  const newY = THREE.MathUtils.lerp(visual.position.y, targetY, t);
  visual.position.y = newY;
}

function updateLevel4(delta) {
  if (!level4State.built || currentLevel !== LEVEL_IDS.LEVEL4) return;
  updateLevel4Step0(delta);
  
  // Update wave countdown if active
  if (level4RiddleState.waveCountdownActive) {
    level4RiddleState.waveCountdownTime -= delta;
    const countdownElement = document.getElementById('level4-wave-countdown');
    if (countdownElement) {
      const timeLeft = Math.ceil(level4RiddleState.waveCountdownTime);
      const difficulty = calculateLevel4WaveDifficulty(level4RiddleState.currentWave);
      const waveText = difficulty.isFinalWave ? "FINAL WAVE" : `WAVE ${level4RiddleState.currentWave}`;
      const colorHex = `#${difficulty.color.getHexString()}`;
      
      if (timeLeft > 0) {
        countdownElement.innerHTML = `
          <div style="font-size: 14px; margin-bottom: 4px; color: ${colorHex}; opacity: 0.9;">${waveText}</div>
          <div style="font-size: 24px; color: ${colorHex}; font-weight: bold;">${timeLeft}</div>
        `;
      } else {
        countdownElement.innerHTML = `
          <div style="font-size: 14px; margin-bottom: 4px; color: ${colorHex}; opacity: 0.9;">${waveText}</div>
          <div style="font-size: 24px; color: ${colorHex}; font-weight: bold;">GO!</div>
        `;
        setTimeout(() => {
          if (countdownElement.parentNode) {
            countdownElement.parentNode.removeChild(countdownElement);
          }
          level4RiddleState.waveCountdownActive = false;
          // Spawn wave after countdown (callback was stored in showLevel4WaveCountdown)
          if (level4RiddleState.waveCountdownCallback) {
            level4RiddleState.waveCountdownCallback();
            level4RiddleState.waveCountdownCallback = null;
          }
        }, 500);
      }
    }
  }
  
  // Update hit indicator
  updateLevel4HitIndicator(delta);
  
  // Update monster wave countdown if active
  if (level4RiddleState.monsterWaveCountdownActive) {
    level4RiddleState.monsterWaveCountdownTime -= delta;
    const countdownElement = document.getElementById('level4-monster-wave-countdown');
    if (countdownElement) {
      const timeLeft = Math.ceil(level4RiddleState.monsterWaveCountdownTime);
      const isFinalWave = level4RiddleState.currentMonsterWave > LEVEL4_MONSTER_WAVES_COUNT;
      const waveText = isFinalWave ? "FINAL BOSS WAVE" : `MONSTER WAVE ${level4RiddleState.currentMonsterWave}`;
      const colorHex = isFinalWave ? "#ff0000" : "#ff3300";
      
      if (timeLeft > 0) {
        countdownElement.innerHTML = `
          <div style="font-size: 14px; margin-bottom: 4px; color: ${colorHex}; opacity: 0.9;">${waveText}</div>
          <div style="font-size: 24px; color: ${colorHex}; font-weight: bold;">${timeLeft}</div>
        `;
      } else {
        countdownElement.innerHTML = `
          <div style="font-size: 14px; margin-bottom: 4px; color: ${colorHex}; opacity: 0.9;">${waveText}</div>
          <div style="font-size: 24px; color: ${colorHex}; font-weight: bold;">GO!</div>
        `;
        setTimeout(() => {
          if (countdownElement.parentNode) {
            countdownElement.parentNode.removeChild(countdownElement);
          }
          level4RiddleState.monsterWaveCountdownActive = false;
          // Spawn wave after countdown
          if (level4RiddleState.monsterWaveCountdownCallback) {
            level4RiddleState.monsterWaveCountdownCallback();
            level4RiddleState.monsterWaveCountdownCallback = null;
          }
        }, 500);
      }
    }
  }
  
  // Step 1: Update cheeses if active
  if (level4RiddleState.step1Active) {
    const playerPosition = new THREE.Vector3().lerpVectors(playerCollider.start, playerCollider.end, 0.5);
    level4State.cheeses.forEach((cheese, index) => {
      if (cheese && cheese.mesh && cheese.mesh.visible) {
        cheese.update(delta, playerPosition, () => {
          captureLevel4Cheese(index);
        });
      }
    });
    
    // Update weapon system (bullets, triple-shot, heat)
    if (weaponSystem && typeof weaponSystem.update === 'function') {
      weaponSystem.update(delta);
    } else {
      // Legacy fallback
      updateLevel4Bullets(delta);
      updateLevel4TripleShot(delta);
      updateLevel4Heat(delta);
    }
    
    // Update weapon animation (only in first-person view)
    if (isFirstPerson()) {
      // Check if player is moving (for weapon bobbing) - use playerVelocity magnitude
      const velocityMagnitude = Math.sqrt(
        (playerVelocity?.x || 0) * (playerVelocity?.x || 0) +
        (playerVelocity?.z || 0) * (playerVelocity?.z || 0)
      );
      const isMoving = velocityMagnitude > 0.1; // Player is moving if velocity > 0.1
      updateLevel4WeaponAnimation(delta, isMoving);
    }
  }
  
  // NEW: Step 2: Update monsters if active
  if (level4RiddleState.step2Active) {
    // Update monster movement and AI
    updateLevel4Monsters(delta);
    
    // SAFETY CHECK: Auto-complete wave if stuck (monsters exist but none visible for too long)
    if (level4State.monsters.length > 0 && level4RiddleState.monstersInCurrentWave < LEVEL4_MONSTERS_PER_WAVE) {
      const visibleMonsters = level4State.monsters.filter(m => m.mesh && m.mesh.visible && !m.defeated);
      if (visibleMonsters.length === 0) {
        // No visible monsters but monsters array has entries - possible stuck state
        if (!level4RiddleState.stuckMonsterCheckTime) {
          level4RiddleState.stuckMonsterCheckTime = performance.now();
        } else {
          const stuckTime = performance.now() - level4RiddleState.stuckMonsterCheckTime;
          if (stuckTime > 10000) { // 10 seconds stuck
            console.warn("⚠️ [LEVEL 4] Stuck monster detected! Auto-clearing and respawning wave...");
            // Clear stuck monsters
            level4State.monsters.forEach((monster) => {
              if (monster.mesh && monster.mesh.parent) {
                monster.mesh.parent.remove(monster.mesh);
              }
            });
            level4State.monsters = [];
            level4RiddleState.monstersInCurrentWave = 0;
            level4RiddleState.stuckMonsterCheckTime = null;
            // Respawn current wave
            spawnMonsterWave(level4RiddleState.currentMonsterWave);
          }
        }
      } else {
        // Reset stuck timer if we have visible monsters
        level4RiddleState.stuckMonsterCheckTime = null;
      }
    } else {
      // Reset stuck timer if wave complete or no monsters
      level4RiddleState.stuckMonsterCheckTime = null;
    }
    
    // CRITICAL: Update weapon system (bullets, triple-shot, heat) - SAME AS STEP 1
    // This ensures bullets move and weapon system works correctly in Step 2
    if (weaponSystem && typeof weaponSystem.update === 'function') {
      weaponSystem.update(delta);
    } else {
      // Legacy fallback
    updateLevel4Bullets(delta);
    updateLevel4TripleShot(delta);
    updateLevel4Heat(delta);
    }
    
    // Update weapon animation (only in first-person view) - same for monsters
    if (isFirstPerson()) {
      // Check if player is moving (for weapon bobbing) - use playerVelocity magnitude
      const velocityMagnitude = Math.sqrt(
        (playerVelocity?.x || 0) * (playerVelocity?.x || 0) +
        (playerVelocity?.z || 0) * (playerVelocity?.z || 0)
      );
      const isMoving = velocityMagnitude > 0.1; // Player is moving if velocity > 0.1
      updateLevel4WeaponAnimation(delta, isMoving);
    }
    
    // Update monster projectiles (final wave only)
    updateMonsterProjectiles(delta);
  }
  
  // Handle portal proximity if portal is active
  if (level4State.portalActive && level4State.portal) {
    const playerPosition = new THREE.Vector3().lerpVectors(playerCollider.start, playerCollider.end, 0.5);
    handleLevel4PortalProximity(playerPosition, delta);
  }
  
  // Update progress HUD
  if (level4RiddleState.step1Active || level4RiddleState.step2Active) {
    updateLevel4ProgressHUD();
  }
  
  // Update explosion particles
  level4State.explosionParticles = level4State.explosionParticles.filter(particle => {
    if (!particle.parent) return false; // Already removed
    
    particle.userData.age += delta;
    if (particle.userData.age >= particle.userData.lifetime) {
      level4State.group.remove(particle);
      return false; // Remove from array
    }
    
    // Update position
    particle.position.addScaledVector(particle.userData.velocity, delta);
    particle.userData.velocity.y += particle.userData.gravity * delta;
    
    // Fade out
    const opacity = 1 - (particle.userData.age / particle.userData.lifetime);
    if (particle.material) {
      particle.material.opacity = opacity;
    }
    
    // Rotate for visual effect
    particle.rotation.x += delta * 5;
    particle.rotation.y += delta * 5;
    
    return true; // Keep in array
  });
}

