// DEBUG: Force respawn current wave (if stuck)
window.forceRespawnLevel4Wave = function() {
  if (!level4RiddleState.step2Active) {
    console.log("❌ [DEBUG] Monster waves not active!");
    return;
  }
  
  // Clear all current monsters
  level4State.monsters.forEach((monster) => {
    if (monster.mesh && monster.mesh.parent) {
      monster.mesh.parent.remove(monster.mesh);
    }
    if (monster.mixer) {
      monster.mixer.stopAllAction();
    }
  });
  level4State.monsters = [];
  
  // Reset wave progress
  level4RiddleState.monstersInCurrentWave = 0;
  
  // Respawn current wave
  console.log(`🔄 [DEBUG] Respawning wave ${level4RiddleState.currentMonsterWave}...`);
  spawnMonsterWave(level4RiddleState.currentMonsterWave);
};

// DEBUG: Skip to next wave (emergency bypass)
window.skipToNextLevel4Wave = function() {
  if (!level4RiddleState.step2Active) {
    console.log("❌ [DEBUG] Monster waves not active!");
    return;
  }
  
  // Mark current wave as complete
  level4RiddleState.monstersInCurrentWave = LEVEL4_MONSTERS_PER_WAVE;
  
  // Clear all current monsters
  level4State.monsters.forEach((monster) => {
    if (monster.mesh && monster.mesh.parent) {
      monster.mesh.parent.remove(monster.mesh);
    }
    if (monster.mixer) {
      monster.mixer.stopAllAction();
    }
  });
  level4State.monsters = [];
  
  // Advance to next wave
  level4RiddleState.currentMonsterWave++;
  level4RiddleState.monstersInCurrentWave = 0;
  
  console.log(`⏭️ [DEBUG] Skipped to wave ${level4RiddleState.currentMonsterWave}`);
  
  // Spawn next wave
  spawnMonsterWave(level4RiddleState.currentMonsterWave);
};

// DEBUG: Fix monster visibility (force make visible)
window.fixLevel4MonsterVisibility = function(monsterIndex) {
  if (!level4RiddleState.step2Active || !level4State.monsters[monsterIndex]) {
    console.log("❌ [DEBUG] Invalid monster index or waves not active!");
    return;
  }
  
  const monster = level4State.monsters[monsterIndex];
  
  console.log(`🔧 [DEBUG] Fixing visibility for monster ${monsterIndex} (${monster.path.split('/').pop()})...`);
  
  // Force visibility on main mesh
  monster.mesh.visible = true;
  
  // Force visibility on all child meshes
  monster.mesh.traverse((child) => {
    if (child.isMesh) {
      child.visible = true;
      
      // Fix materials
      if (child.material) {
        if (Array.isArray(child.material)) {
          child.material.forEach(mat => {
            if (mat) {
              mat.visible = true;
              mat.transparent = false;
              mat.opacity = 1.0;
              mat.side = THREE.FrontSide;
              mat.needsUpdate = true;
            }
          });
        } else {
          child.material.visible = true;
          child.material.transparent = false;
          child.material.opacity = 1.0;
          child.material.side = THREE.FrontSide;
          child.material.needsUpdate = true;
        }
      }
      
      // Fix skeleton if broken - convert to regular mesh to prevent update errors
      if (child.isSkinnedMesh && (!child.skeleton || !child.skeleton.bones || child.skeleton.bones.length === 0)) {
        console.warn(`⚠️ [DEBUG] Converting broken skeleton to regular mesh for ${monster.path.split('/').pop()}`);
        child.isSkinnedMesh = false;
        delete child.skeleton;
        delete child.bindMatrix;
      }
      
      // Recompute bounding boxes
      if (child.geometry) {
        child.geometry.computeBoundingBox();
        child.geometry.computeBoundingSphere();
      }
    }
  });
  
  // Ensure it's in the scene
  if (!level4State.group.children.includes(monster.mesh)) {
    level4State.group.add(monster.mesh);
    console.log(`✅ [DEBUG] Re-added monster ${monsterIndex} to scene`);
  }
  
  // Force matrix update
  monster.mesh.updateMatrixWorld(true);
  
  console.log(`✅ [DEBUG] Visibility fix applied to monster ${monsterIndex}`);
  console.log(`  Visible: ${monster.mesh.visible}`);
  console.log(`  In Scene: ${level4State.group.children.includes(monster.mesh)}`);
  console.log(`  Position: (${monster.mesh.position.x.toFixed(2)}, ${monster.mesh.position.y.toFixed(2)}, ${monster.mesh.position.z.toFixed(2)})`);
};

// NEW: Update Level 4 Monsters Movement and AI
function updateLevel4Monsters(delta) {
  if (!level4RiddleState.step2Active || !level4State.monsters) return;
  
  const playerPosition = new THREE.Vector3().lerpVectors(playerCollider.start, playerCollider.end, 0.5);
  const origin = level4Config.origin;
  const size = level4Config.size;
  const margin = 20;
  
  level4State.monsters.forEach((monster, index) => {
    if (!monster || monster.defeated) return;
    
    // Simple validation (like Level 3)
    if (!monster.mesh || !monster.mesh.parent) return;
    
    // Update animation mixer
    if (monster.mixer) {
      monster.mixer.update(delta);
    }
    
    // Update monster movement (EXACTLY like Level 3 pattern - simple and working)
    const monsterPos = monster.mesh.position.clone();
    const targetPos = monster.targetPosition.clone();
    
    // For ground monsters, ignore Y when calculating direction (like Level 3)
    if (!monster.isFlying) {
      monsterPos.y = 0;
      targetPos.y = 0;
    }
    
    const direction = new THREE.Vector3().subVectors(targetPos, monsterPos).normalize();
    
    // Calculate horizontal distance (like Level 3)
    const horizontalDistance = new THREE.Vector2(monster.mesh.position.x, monster.mesh.position.z)
      .distanceTo(new THREE.Vector2(monster.targetPosition.x, monster.targetPosition.z));
    
    if (horizontalDistance > 2.0) {
      // Move towards target (EXACTLY like Level 3)
      const moveDistance = monster.speed * delta;
      monster.mesh.position.x += direction.x * moveDistance;
      monster.mesh.position.z += direction.z * moveDistance;
      
      // ALWAYS use stored baseY for Y position (prevents falling/standing issues - matches Level 3)
      if (monster.isFlying) {
        // Flying monsters: interpolate Y to target Y
        const currentY = monster.mesh.position.y;
        const targetY = monster.targetPosition.y;
        if (Math.abs(currentY - targetY) > 0.5) {
          monster.mesh.position.y += Math.sign(targetY - currentY) * moveDistance * 0.5;
        }
      } else {
        // Ground monsters: ALWAYS use baseY (prevents falling/standing)
        monster.mesh.position.y = monster.baseY;
      }
      
      // Rotate to face movement direction (EXACTLY like Level 3)
      if (direction.lengthSq() > 0.01) {
        const targetRotation = Math.atan2(direction.x, direction.z);
        monster.mesh.rotation.y = targetRotation;
      }
    } else {
      // Reached target, pick new random target (EXACTLY like Level 3)
      if (monster.isFlying) {
        // Flying monsters: full 3D movement
        const newX = origin.x + (Math.random() * (size - margin * 2) - (size / 2 - margin));
        const newZ = origin.z + (Math.random() * (size - margin * 2) - (size / 2 - margin));
        const newY = origin.y + 3 + Math.random() * 9; // Random height 3-12
        monster.targetPosition.set(newX, newY, newZ);
      } else {
        // Ground monsters: 2D movement (ALWAYS use stored baseY like Level 3)
        const newX = origin.x + (Math.random() * (size - margin * 2) - (size / 2 - margin));
        const newZ = origin.z + (Math.random() * (size - margin * 2) - (size / 2 - margin));
        const newY = monster.baseY; // ALWAYS use stored baseY
        monster.targetPosition.set(newX, newY, newZ);
      }
    }
    
    monster.mesh.updateMatrixWorld(true);
    
    // Final wave: Monster projectile shooting
    if (monster.isFinalWave && !monster.defeated) {
      const currentTime = performance.now();
      if (currentTime - monster.lastProjectileTime > LEVEL4_MONSTER_PROJECTILE_COOLDOWN) {
        // Shoot projectile at player
        shootMonsterProjectile(monster, playerPosition);
        monster.lastProjectileTime = currentTime;
      }
    }
  });
  
  // Update monster projectiles
  updateMonsterProjectiles(delta);
}

// NEW: Shoot monster projectile at player (final wave only)
function shootMonsterProjectile(monster, playerPosition) {
  const monsterPos = monster.mesh.position.clone();
  const direction = new THREE.Vector3().subVectors(playerPosition, monsterPos);
  const distance = direction.length();
  if (distance < 0.1) return; // Too close
  direction.normalize();
  
  // Create projectile
  const projectile = new THREE.Mesh(
    new THREE.SphereGeometry(0.3, 8, 8),
    new THREE.MeshLambertMaterial({ 
      color: 0xff0000,
      emissive: 0xff0000,
      emissiveIntensity: 0.8
    })
  );
  projectile.position.copy(monsterPos);
  
  // Calculate velocity (clone direction to avoid modifying original)
  const velocity = direction.clone().multiplyScalar(LEVEL4_MONSTER_PROJECTILE_SPEED);
  
  level4State.group.add(projectile);
  level4State.monsterProjectiles.push({
    mesh: projectile,
    velocity: velocity,
    lifetime: 5.0,
    age: 0
  });
}

// NEW: Update monster projectiles
function updateMonsterProjectiles(delta) {
  level4State.monsterProjectiles = level4State.monsterProjectiles.filter(projectile => {
    if (!projectile.mesh || !projectile.mesh.parent) return false;
    
    projectile.age += delta;
    if (projectile.age >= projectile.lifetime) {
      level4State.group.remove(projectile.mesh);
      return false;
    }
    
    // Update position
    projectile.mesh.position.addScaledVector(projectile.velocity, delta);
    
    // Check collision with player
    const playerPos = new THREE.Vector3().lerpVectors(playerCollider.start, playerCollider.end, 0.5);
    const distance = projectile.mesh.position.distanceTo(playerPos);
    const PLAYER_RADIUS = 0.5;
    
    if (distance < PLAYER_RADIUS) {
      // Player hit! Game over!
      console.error("💥 [LEVEL 4] Player hit by monster projectile! Game over!");
      triggerLevel4MonsterGameOver();
      level4State.group.remove(projectile.mesh);
      return false;
    }
    
    return true;
  });
}

// NEW: Trigger game over from monster projectile hit
function triggerLevel4MonsterGameOver() {
  // Use same game over screen as Level 3 crush death
  showLevel3GameOverScreen();
  // Could add custom message for monster death if needed
}

function createLevel4Portal() {
  const position = level4Config.portalPosition.clone();
  const portal = createPortalMesh({
    position,
    width: RIDDLE3_PORTAL_SCALE,
    height: RIDDLE3_PORTAL_SCALE,
    depth: 2,
    rotationY: Math.PI,
    parent: level4State.group,
    visible: false
  });
  portal.userData.levelId = "CHEESE_TEMPLE_LEVEL_4";
  return portal;
}

function handleLevel4PortalProximity(playerPos, delta) {
  if (!level4State.portal || !level4State.portalActive) return;
  const portalPos = level4State.portal.position;
  const horizontalDistance = Math.sqrt(
    Math.pow(playerPos.x - portalPos.x, 2) + Math.pow(playerPos.z - portalPos.z, 2)
  );
  const verticalDistance = Math.abs(playerPos.y - portalPos.y);
  const canEnter =
    horizontalDistance < RIDDLE3_PORTAL_ENTER_DISTANCE && verticalDistance < 3.0;

  const suctionRadius = 6.0;
  const suctionStrength = 16.0;
  if (!canEnter && horizontalDistance < suctionRadius) {
    const pullDir = new THREE.Vector3().subVectors(portalPos, playerPos);
    pullDir.y = 0;
    if (pullDir.lengthSq() > 0.0001) {
      pullDir.normalize();
      playerVelocity.addScaledVector(pullDir, suctionStrength * delta);
    }
  }

  if (canEnter && !level4RiddleState.step3Complete) {
    // Complete Step 3 - Portal entry (renamed from Step 2)
    level4RiddleState.step3Complete = true;
    if (!level4RiddleState.step3TraitUnlocked) {
      unlockLevel4Trait(LEVEL4_STEP3_TRAIT, "Level 4 Step 3 - Portal Entry");
      awardLevel4DspoincReward("CHEESE_TEMPLE_LEVEL4_STEP3", 200, "Level 4 Step 3 - Portal Entry");
    }
    showLevel4CompletionScreen();
  }
}

