// Create 3 levers for Riddle #4 (Hidden Secret Riddle)
function createRiddle4Levers(spawnData, blockSize) {
  // Position: On a wall, spaced apart horizontally (side by side)
  // Move 10 blocks to the LEFT from x: 20 to x: 10 to reach the actual wall
  // Space them horizontally: lever1 at z: 95, lever2 at z: 100, lever3 at z: 105
  // Y position: y: 2.5 (same height for all, horizontal line)
  // Position them slightly forward from the wall so they're visible and clickable
  const wallX = 10 * blockSize + blockSize / 2; // Wall position (10 blocks left from x: 20 to reach wall)
  const leverY = 2 * blockSize + blockSize / 2; // y: 2.5 (same height for all levers)
  // Position levers slightly forward from wall (z: 100.2) so they're clearly visible
  const leverZ = 100 * blockSize + blockSize / 2 + 0.2; // z: 100.7 (slightly forward from wall at z: 100.5)
  
  console.log("🧩 [RIDDLE #4] Creating 3 secret levers on wall (horizontal):", {
    spawnData: { x: spawnData.x, y: spawnData.y, z: spawnData.z },
    wallX: wallX,
    leverY: leverY,
    leverZ: leverZ,
    blockSize: blockSize
  });
  
  // Create Lever 1 (left)
  const lever1Z = leverZ - 5 * blockSize; // z: 95.7 (5 blocks to the left)
  const lever1 = createRiddle4Lever(wallX, leverY, lever1Z, blockSize, 1);
  riddleState.riddle4.lever1 = lever1;
  
  // Create Lever 2 (middle)
  const lever2Z = leverZ; // z: 100.7 (middle position)
  const lever2 = createRiddle4Lever(wallX, leverY, lever2Z, blockSize, 2);
  riddleState.riddle4.lever2 = lever2;
  
  // Create Lever 3 (right)
  const lever3Z = leverZ + 5 * blockSize; // z: 105.7 (5 blocks to the right)
  const lever3 = createRiddle4Lever(wallX, leverY, lever3Z, blockSize, 3);
  riddleState.riddle4.lever3 = lever3;
  
  console.log("🧩 [RIDDLE #4] All 3 secret levers created and added to scene (horizontal line on wall at x: 10)");
}

// Helper function to create a single Riddle #4 lever
function createRiddle4Lever(x, y, z, blockSize, leverNumber) {
  // Lever geometry: width 0.8, height 0.6, depth 0.3 (flattened against wall)
  const leverGeometry = new THREE.BoxGeometry(blockSize * 0.8, blockSize * 0.6, blockSize * 0.3);
  const leverTextureOff = loadTexture("textures/blocks/slever1.png");
  const leverMaterial = new THREE.MeshLambertMaterial({ 
    map: leverTextureOff,
    emissive: new THREE.Color(0x000000), // Black (no base glow)
    emissiveIntensity: 0.0, // No base emissive - texture shows correctly
    transparent: false
  });
  
  const lever = new THREE.Mesh(leverGeometry, leverMaterial);
  lever.position.set(x, y, z);
  // Rotate lever to face outward from wall (if on z: 0 wall, rotate 180 degrees on Y axis)
  // Actually, levers should face the player, so if wall is at z: 0, lever should face positive Z
  // No rotation needed - default orientation faces positive Z which is correct for z: 0 wall
  lever.visible = true; // Always visible (unlike Riddle #3 lever)
  lever.castShadow = false;
  lever.receiveShadow = false;
  
  // Add userData for Riddle #4
  lever.userData.isRiddleBlock = true;
  lever.userData.isRiddle4Lever = true;
  lever.userData.riddleId = 'CHEESE_TEMPLE_RIDDLE_04';
  lever.userData.leverNumber = leverNumber; // 1, 2, or 3
  lever.userData.leverState = 'off'; // off or on
  
  // Store off and on textures
  lever.userData.textureOff = leverTextureOff;
  lever.userData.textureOn = loadTexture("textures/blocks/slever2.png");
  
  // Ensure matrix is updated
  lever.matrixAutoUpdate = true;
  lever.updateMatrix();
  lever.updateMatrixWorld(true);
  
  scene.add(lever);
  
  console.log(`🧩 [RIDDLE #4] Lever ${leverNumber} created:`, {
    position: { x: x.toFixed(2), y: y.toFixed(2), z: z.toFixed(2) },
    inScene: scene.children.includes(lever),
    visible: lever.visible
  });
  
  return lever;
}

